'AddProductTipText' => 'ਸਪਸ਼ਟ ਉਤਪਾਦ ਨਾਮ ਅਤੇ ਵਿਲੱਖਣ ਕੋਡ ਵਰਤੋ। ਪਹਿਲੀ ਚੁਣੀ ਸ਼੍ਰੇਣੀ ਪੁਰਾਣੀਆਂ ਰਿਪੋਰਟਾਂ ਵਿੱਚ ਵਰਤੀ ਜਾਣ ਵਾਲੀ ਮੁੱਖ ਸ਼੍ਰੇਣੀ ਹੈ।',
