'ProductNameTooltip' => 'ਰਸੀਦਾਂ, ਇਨਵੌਇਸਾਂ, ਤੁਹਾਡੇ ਸਟੋਰ ਅਤੇ ਰਿਪੋਰਟਾਂ \'ਤੇ ਦਿਖਾਇਆ ਜਾਣ ਵਾਲਾ ਨਾਮ। 3 ਤੋਂ 55 ਅੱਖਰ।',
'BarcodeSymbologyTooltip' => 'ਬਾਰਕੋਡ ਫਾਰਮੈਟ ਜੋ ਤੁਹਾਡੇ ਉਤਪਾਦ ਲੇਬਲ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ। ਜ਼ਿਆਦਾਤਰ ਉਤਪਾਦਾਂ ਲਈ CODE128 ਸੁਰੱਖਿਅਤ ਡਿਫਾਲਟ ਹੈ।',
'ProductCodeTooltip' => 'ਇਸ ਉਤਪਾਦ ਲਈ ਇੱਕ ਵਿਲੱਖਣ ਪਛਾਣਕਰਤਾ। ਮੌਜੂਦਾ ਬਾਰਕੋਡ ਸਕੈਨ ਕਰੋ ਜਾਂ ਨਵਾਂ ਤਿਆਰ ਕਰਨ ਲਈ ਬਾਰਕੋਡ ਬਟਨ \'ਤੇ ਕਲਿੱਕ ਕਰੋ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਉੱਪਰਲੀ ਸਿੰਬੋਲੋਜੀ ਕੋਡ ਨਾਲ ਮੇਲ ਖਾਂਦੀ ਹੈ।',
'Barcode_GTIN' => 'ਬਾਰਕੋਡ (GTIN, UPC, EAN, ISBN)',
'Barcode_GTIN_Tooltip' => 'ਪੈਕੇਜਿੰਗ \'ਤੇ ਛਪਿਆ ਮਿਆਰੀ ਉਤਪਾਦ ਬਾਰਕੋਡ ਨੰਬਰ (GTIN, UPC, EAN ਜਾਂ ISBN)। ਵਿਕਲਪਿਕ, ਅਤੇ ਅੰਦਰੂਨੀ ਕੋਡ/SKU ਤੋਂ ਵੱਖਰਾ। WooCommerce ਨਾਲ ਉਤਪਾਦ Global Unique ID ਵਜੋਂ ਸਿੰਕ ਹੁੰਦਾ ਹੈ।',
'Barcode_GTIN_Placeholder' => 'ਜਿਵੇਂ 0123456789012',
