'BrandTooltip' => 'ਵਿਕਲਪਿਕ। ਇਸ ਉਤਪਾਦ ਦਾ ਨਿਰਮਾਤਾ ਜਾਂ ਬ੍ਰਾਂਡ। ਫਿਲਟਰਿੰਗ, ਰਿਪੋਰਟਿੰਗ ਅਤੇ ਸਟੋਰਫਰੰਟ ਬ੍ਰਾਊਜ਼ਿੰਗ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।',
'DescriptionTooltip' => 'ਵਿਕਲਪਿਕ। ਰਸੀਦਾਂ, ਇਨਵੌਇਸਾਂ ਅਤੇ ਤੁਹਾਡੇ ਔਨਲਾਈਨ ਸਟੋਰ \'ਤੇ ਦਿਖਾਇਆ ਜਾਣ ਵਾਲਾ ਛੋਟਾ ਵੇਰਵਾ। ਇਸਨੂੰ ਸੰਖੇਪ ਅਤੇ ਗਾਹਕ-ਅਨੁਕੂਲ ਰੱਖੋ।',
