'Code_Invalid_UPC' => 'UPC ਲਈ 11 ਅੰਕ ਲੋੜੀਂਦੇ ਹਨ (ਜਾਂ ਵੈਧ ਚੈੱਕ ਅੰਕ ਨਾਲ 12)',
'Online_Store_Accounts' => 'ਆਨਲਾਈਨ ਸਟੋਰ ਖਾਤੇ',
'Customers_without_login_alert' => 'ਇਹ ਤੁਹਾਡੇ POS / ਵਾਕ-ਇਨ ਗਾਹਕ ਹਨ ਜਿਨ੍ਹਾਂ ਦਾ ਅਜੇ ਆਨਲਾਈਨ ਸਟੋਰ ਖਾਤਾ ਨਹੀਂ ਹੈ। ਸਟੋਰ ਲੌਗਇਨ (ਈਮੇਲ + ਪਾਸਵਰਡ) ਬਣਾਉਣ ਲਈ "ਖਾਤਾ ਰਜਿਸਟਰ ਕਰੋ" ਵਰਤੋ ਤਾਂ ਜੋ ਗਾਹਕ ਸਾਈਨ ਇਨ ਕਰਕੇ ਤੁਹਾਡੇ ਆਨਲਾਈਨ ਸਟੋਰ \'ਤੇ ਖਰੀਦਦਾਰੀ ਕਰ ਸਕੇ।',
'Customers_with_login_alert' => 'ਇਹਨਾਂ ਗਾਹਕਾਂ ਦਾ ਆਨਲਾਈਨ ਸਟੋਰ ਖਾਤਾ ਹੈ ਅਤੇ ਉਹ ਤੁਹਾਡੇ ਸਟੋਰਫਰੰਟ ਵਿੱਚ ਸਾਈਨ ਇਨ ਕਰ ਸਕਦੇ ਹਨ। ਇੱਥੇ ਕੀਤੀਆਂ ਤਬਦੀਲੀਆਂ (ਈਮੇਲ, ਪਾਸਵਰਡ, ਸਥਿਤੀ, ਬਲੌਕ) ਸਿਰਫ਼ ਉਹਨਾਂ ਦੇ ਆਨਲਾਈਨ ਸਟੋਰ ਲੌਗਇਨ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀਆਂ ਹਨ - ਉਹਨਾਂ ਦੇ POS ਗਾਹਕ ਰਿਕਾਰਡ ਨੂੰ ਨਹੀਂ।',
'Assigned_Permissions' => 'ਨਿਰਧਾਰਤ ਅਨੁਮਤੀਆਂ',
'Modules' => 'ਮੋਡੀਊਲ',
'Resize_Product_Images' => 'ਉਤਪਾਦ ਚਿੱਤਰਾਂ ਦਾ ਆਕਾਰ ਬਦਲੋ',
'Resize_Product_Images_Help' => 'ਸੇਵ ਕਰਦੇ ਸਮੇਂ ਉਤਪਾਦ, ਵੇਰੀਐਂਟ ਅਤੇ ਗੈਲਰੀ ਚਿੱਤਰਾਂ ਦਾ ਆਕਾਰ ਘਟਾਓ। ਅੱਪਲੋਡ ਕੀਤੀਆਂ ਫ਼ਾਈਲਾਂ ਨੂੰ ਉਹਨਾਂ ਦੇ ਅਸਲ ਰੈਜ਼ੋਲਿਊਸ਼ਨ \'ਤੇ ਸਟੋਰ ਕਰਨ ਲਈ ਇਸਨੂੰ ਬੰਦ ਕਰੋ (ਵੱਡੀਆਂ ਫ਼ਾਈਲਾਂ, ਹੌਲੀ ਪੰਨੇ)।',
'Product_Image_Max_Size' => 'ਉਤਪਾਦ ਚਿੱਤਰ ਦਾ ਵੱਧ ਤੋਂ ਵੱਧ ਆਕਾਰ',
'Product_Image_Max_Size_Help' => 'ਸਭ ਤੋਂ ਲੰਬਾ ਕਿਨਾਰਾ, ਪਿਕਸਲਾਂ ਵਿੱਚ, ਜਿਸ ਵਿੱਚ ਸੇਵ ਕੀਤੇ ਉਤਪਾਦ ਚਿੱਤਰ ਫਿੱਟ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਆਕਾਰ ਅਨੁਪਾਤ ਬਰਕਰਾਰ ਰਹਿੰਦਾ ਹੈ ਅਤੇ ਛੋਟੇ ਚਿੱਤਰ ਕਦੇ ਵੱਡੇ ਨਹੀਂ ਕੀਤੇ ਜਾਂਦੇ।',
'Grid_View' => 'ਕਾਰਡ',
'Table_View' => 'ਟੇਬਲ',
'Image_Max_2MB' => 'ਚਿੱਤਰ 2 MB ਜਾਂ ਇਸ ਤੋਂ ਛੋਟਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।',
'Units_Guide_Title' => 'ਯੂਨਿਟਾਂ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀਆਂ ਹਨ',
'Units_Guide_Base' => 'ਮੂਲ ਯੂਨਿਟ: "ਮੂਲ ਯੂਨਿਟ" ਖਾਲੀ ਛੱਡੋ। ਸਟਾਕ ਹਮੇਸ਼ਾ ਇਸ ਯੂਨਿਟ ਵਿੱਚ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ, ਉਦਾਹਰਨ ਲਈ ਪੀਸ।',
'Units_Guide_Sub' => 'ਉਪ-ਯੂਨਿਟ: ਇੱਕ "ਮੂਲ ਯੂਨਿਟ" ਚੁਣੋ, ਫਿਰ ਇਸਨੂੰ ਉਸ ਮੂਲ ਯੂਨਿਟ ਵਿੱਚ ਬਦਲਣ ਲਈ "ਓਪਰੇਟਰ" ਅਤੇ "ਓਪਰੇਸ਼ਨ ਮੁੱਲ" ਵਰਤੋ।',
'Units_Guide_Example_Multiply' => 'ਉਦਾਹਰਨ: ਮੂਲ ਯੂਨਿਟ ਪੀਸ, ਓਪਰੇਟਰ * ਅਤੇ ਮੁੱਲ 12 ਵਾਲਾ ਇੱਕ ਡੱਬਾ। 1 ਡੱਬਾ ਵੇਚਣ ਨਾਲ ਸਟਾਕ ਵਿੱਚੋਂ 12 ਪੀਸ ਘਟਦੇ ਹਨ।',
'Units_Guide_Example_Divide' => 'ਉਦਾਹਰਨ: ਮੂਲ ਯੂਨਿਟ ਕਿਲੋਗ੍ਰਾਮ, ਓਪਰੇਟਰ / ਅਤੇ ਮੁੱਲ 1000 ਵਾਲਾ ਇੱਕ ਗ੍ਰਾਮ। 500 ਗ੍ਰਾਮ ਵੇਚਣ ਨਾਲ ਸਟਾਕ ਵਿੱਚੋਂ 0.5 ਕਿਲੋਗ੍ਰਾਮ ਘਟਦਾ ਹੈ।',
'Units_Guide_Note' => 'ਸਿਰਫ਼ ਮੂਲ ਯੂਨਿਟਾਂ ਨੂੰ ਹੀ "ਮੂਲ ਯੂਨਿਟ" ਵਜੋਂ ਚੁਣਿਆ ਜਾ ਸਕਦਾ ਹੈ, ਅਤੇ ਜਦੋਂ ਤੱਕ ਉਪ-ਯੂਨਿਟਾਂ ਕਿਸੇ ਯੂਨਿਟ ਨੂੰ ਵਰਤਦੀਆਂ ਹਨ ਉਸਨੂੰ ਮਿਟਾਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ।',
'Amount_Paid' => 'ਅਦਾ ਕੀਤੀ ਰਕਮ',
'Payment_Amounts_Help' => 'ਅਦਾ ਕੀਤੀ ਰਕਮ ਬਕਾਇਆ ਨਿਪਟਾਉਂਦੀ ਹੈ ਅਤੇ ਦੇਣਯੋਗ ਰਕਮ ਘਟਾਉਂਦੀ ਹੈ। ਪ੍ਰਾਪਤ ਰਕਮ ਸੌਂਪੀ ਗਈ ਨਕਦੀ ਹੈ: ਇਹ ਸਿਰਫ਼ ਵਾਪਸ ਦੇਣ ਵਾਲੀ ਬਾਕੀ ਰਕਮ ਗਿਣਨ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਦੇਣਯੋਗ ਰਕਮ ਨਹੀਂ ਬਦਲਦੀ।',
'Show_Tax_Desc' => 'ਚੈੱਕਆਊਟ ਵੇਲੇ ਪੂਰੀ ਵਿਕਰੀ \'ਤੇ ਲਾਗੂ ਟੈਕਸ, ਕੁੱਲ ਰਕਮਾਂ ਵਿੱਚ ਆਪਣੀ ਵੱਖਰੀ "ਆਰਡਰ ਟੈਕਸ" ਲਾਈਨ ਵਜੋਂ ਪ੍ਰਿੰਟ ਹੁੰਦਾ ਹੈ।',
'Show_Items_Tax_Desc' => 'ਹਰ ਉਤਪਾਦ ਦੇ ਆਪਣੇ ਟੈਕਸ ਦਾ ਜੋੜ, "ਕੁੱਲ ਆਈਟਮ ਟੈਕਸ" ਲਾਈਨ ਵਜੋਂ ਪ੍ਰਿੰਟ ਹੁੰਦਾ ਹੈ। ਯੋਗ ਹੋਣ \'ਤੇ, ਉਪ-ਜੋੜ ਇਹਨਾਂ ਟੈਕਸਾਂ ਤੋਂ ਬਿਨਾਂ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।',
'Show_Discount_Desc' => 'ਪੂਰੀ ਵਿਕਰੀ \'ਤੇ ਲਾਗੂ ਛੋਟ (ਕਿਸੇ ਵੀ ਪੁਆਇੰਟ ਛੋਟ ਸਮੇਤ), ਕੁੱਲ ਰਕਮਾਂ ਵਿੱਚ ਆਪਣੀ ਵੱਖਰੀ ਲਾਈਨ ਵਜੋਂ ਪ੍ਰਿੰਟ ਹੁੰਦੀ ਹੈ।',
'Show_Product_Discount_Desc' => 'ਹਰ ਉਤਪਾਦ ਦੀ ਆਪਣੀ ਛੋਟ, ਆਈਟਮ ਸੂਚੀ ਵਿੱਚ ਉਸ ਉਤਪਾਦ ਦੇ ਹੇਠਾਂ ਪ੍ਰਿੰਟ ਹੁੰਦੀ ਹੈ।',
'Receipt_Font_Family' => 'ਰਸੀਦ ਫੌਂਟ',
'Receipt_Font_Family_Desc' => 'ਪ੍ਰਿੰਟ ਕੀਤੀ ਰਸੀਦ ਦੇ ਸਾਰੇ ਟੈਕਸਟ ਲਈ ਵਰਤਿਆ ਜਾਣ ਵਾਲਾ ਫੌਂਟ। "ਡਿਫੌਲਟ" ਮਿਆਰੀ ਰਸੀਦ ਫੌਂਟ ਬਰਕਰਾਰ ਰੱਖਦਾ ਹੈ।',
'Receipt_Font_Size' => 'ਰਸੀਦ ਫੌਂਟ ਆਕਾਰ (px)',
'Receipt_Font_Size_Desc' => 'ਪੂਰੀ ਰਸੀਦ ਵਿੱਚ ਟੈਕਸਟ ਦਾ ਆਕਾਰ, 8 ਤੋਂ 24 ਪਿਕਸਲ ਤੱਕ। ਡਿਫੌਲਟ ਆਕਾਰ ਰੱਖਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।',
'Font_Default' => 'ਡਿਫਾਲਟ',
'Amount_Paid_Help' => 'ਇਸ ਦਸਤਾਵੇਜ਼ \'ਤੇ ਲਾਗੂ ਰਕਮ; ਇਹ ਬਾਕੀ ਦੇਣਯੋਗ ਰਕਮ ਘਟਾਉਂਦੀ ਹੈ।',
'Received_Amount_Help' => 'ਅਸਲ ਵਿੱਚ ਸੌਂਪੀ ਗਈ ਨਕਦੀ। ਅਦਾ ਕੀਤੀ ਰਕਮ ਤੋਂ ਵੱਧ ਜੋ ਵੀ ਹੈ ਉਹ ਬਾਕੀ ਵਜੋਂ ਵਾਪਸ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਦੇਣਯੋਗ ਰਕਮ ਨਹੀਂ ਘਟਾਉਂਦਾ।',
'OpeningBalanceReceived' => 'ਸ਼ੁਰੂਆਤੀ ਬਕਾਇਆ ਪ੍ਰਾਪਤ',
'OpeningBalancePaid' => 'ਸ਼ੁਰੂਆਤੀ ਬਕਾਇਆ ਅਦਾ',
'Customize_Profit' => 'ਮੁਨਾਫ਼ਾ ਅਨੁਕੂਲਿਤ ਕਰੋ',
'Custom_Profit' => 'ਕਸਟਮ ਮੁਨਾਫ਼ਾ',
'Custom_Profit_Hint' => 'ਆਪਣਾ ਮੁਨਾਫ਼ਾ ਅੰਕੜਾ ਬਣਾਉਣ ਲਈ ਚੁਣੋ ਕਿ ਕਿਹੜੀਆਂ ਰਕਮਾਂ ਜੋੜੀਆਂ ਜਾਂ ਘਟਾਈਆਂ ਜਾਣ। ਤੁਹਾਡੀ ਚੋਣ ਇਸ ਡਿਵਾਈਸ \'ਤੇ ਸੇਵ ਹੁੰਦੀ ਹੈ।',
'Profit_Formula' => 'ਮੁਨਾਫ਼ਾ ਫਾਰਮੂਲਾ',
'Income_Statement' => 'ਆਮਦਨ ਬਿਆਨ',
'Gross_Sales' => 'ਕੁੱਲ ਵਿਕਰੀ',
'Net_Revenue' => 'ਸ਼ੁੱਧ ਆਮਦਨ',
'COGS' => 'ਵੇਚੇ ਗਏ ਮਾਲ ਦੀ ਲਾਗਤ',
'Service_Revenue' => 'ਸੇਵਾ ਆਮਦਨ',
'Service_Profit' => 'ਸੇਵਾ ਮੁਨਾਫ਼ਾ',
'Service_Parts_Cost' => 'ਸੇਵਾ ਪੁਰਜ਼ਿਆਂ ਦੀ ਲਾਗਤ',
'Taxes_Collected' => 'ਇਕੱਠੇ ਕੀਤੇ ਟੈਕਸ (ਵਿਕਰੀ)',
'Taxes_Paid' => 'ਅਦਾ ਕੀਤੇ ਟੈਕਸ (ਖਰੀਦ)',
'Discounts_Given' => 'ਦਿੱਤੀਆਂ ਛੋਟਾਂ (ਵਿਕਰੀ)',
'Discounts_Received' => 'ਪ੍ਰਾਪਤ ਛੋਟਾਂ (ਖਰੀਦ)',
'Shipping_Charged' => 'ਵਸੂਲੀ ਸ਼ਿਪਿੰਗ (ਵਿਕਰੀ)',
'Shipping_Paid' => 'ਅਦਾ ਕੀਤੀ ਸ਼ਿਪਿੰਗ (ਖਰੀਦ)',
'Expenses_By_Category' => 'ਸ਼੍ਰੇਣੀ ਅਨੁਸਾਰ ਖਰਚੇ',
'Daily_Trend' => 'ਰੋਜ਼ਾਨਾ ਰੁਝਾਨ',
'Additional_Information' => 'ਵਾਧੂ ਜਾਣਕਾਰੀ',
'Warehouses_Tab_Help' => 'ਆਪਣੇ ਵੇਅਰਹਾਊਸਾਂ (ਸਟੋਰਾਂ/ਸ਼ਾਖਾਵਾਂ) ਦਾ ਪ੍ਰਬੰਧਨ ਕਰੋ। ਹਰ ਵੇਅਰਹਾਊਸ ਆਪਣਾ ਸਟਾਕ ਰੱਖਦਾ ਹੈ, ਅਤੇ ਹਰ ਦਸਤਾਵੇਜ਼ — ਵਿਕਰੀ, ਖਰੀਦ, ਟ੍ਰਾਂਸਫਰ, ਸਮਾਯੋਜਨ — ਉਹਨਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਇੱਕ ਵਿੱਚ ਦਰਜ ਹੁੰਦਾ ਹੈ।',
'Warehouse_Locations_Tab_Help' => 'ਹਰ ਵੇਅਰਹਾਊਸ ਦੇ ਅੰਦਰ ਰੈਕ / ਸ਼ੈਲਫ ਟਿਕਾਣੇ ਪਰਿਭਾਸ਼ਿਤ ਕਰੋ (ਜਿਵੇਂ ਕਤਾਰ 2 – ਰੈਕ B)। ਆਈਟਮਾਂ ਭੌਤਿਕ ਤੌਰ \'ਤੇ ਕਿੱਥੇ ਰੱਖੀਆਂ ਹਨ ਇਹ ਦਿਖਾਉਣ ਲਈ ਇਹਨਾਂ ਨੂੰ ਉਤਪਾਦਾਂ ਨੂੰ ਨਿਰਧਾਰਤ ਕਰੋ।',
'Already_Converted' => 'ਵਿਕਰੀ ਵਿੱਚ ਬਦਲਿਆ ਗਿਆ',
'Salesperson' => 'ਸੇਲਜ਼ਪਰਸਨ',
'Select_Salesperson' => 'ਸੇਲਜ਼ਪਰਸਨ ਚੁਣੋ',
'You' => 'ਤੁਸੀਂ',
'Enable_Pos_Salesperson_Switch' => 'ਚੈੱਕਆਊਟ ਦੌਰਾਨ ਸੇਲਜ਼ਪਰਸਨ ਬਦਲੋ',
'Enable_Pos_Salesperson_Switch_Hint' => 'POS ਸਕ੍ਰੀਨ \'ਤੇ ਸੇਲਜ਼ਪਰਸਨ ਚੋਣਕਾਰ ਦਿਖਾਓ ਤਾਂ ਜੋ ਲੌਗ ਆਊਟ ਕੀਤੇ ਬਿਨਾਂ ਵਿਕਰੀ ਕਿਸੇ ਹੋਰ ਕਰਮਚਾਰੀ ਦੇ ਨਾਮ ਕੀਤੀ ਜਾ ਸਕੇ। ਚੁਣਿਆ ਗਿਆ ਸੇਲਜ਼ਪਰਸਨ ਇਨਵੌਇਸ \'ਤੇ ਸੇਵ ਹੁੰਦਾ ਹੈ ਅਤੇ ਵਿਕਰੀ ਰਿਪੋਰਟਾਂ ਵਿੱਚ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ; ਸਰਗਰਮ POS ਸੈਸ਼ਨ ਨਹੀਂ ਬਦਲਦਾ।',
'Wallet_Payment_Method_Missing' => 'Wallet ਭੁਗਤਾਨ ਵਿਧੀ ਮੌਜੂਦ ਨਹੀਂ ਹੈ',
'Wallet_Payment_Method_Missing_Help' => 'ਬਿਲਕੁਲ "Wallet" ਨਾਮ ਵਾਲੀ ਕੋਈ ਭੁਗਤਾਨ ਵਿਧੀ ਨਹੀਂ ਮਿਲੀ। POS ਵਾਲੇਟ ਭੁਗਤਾਨ ਇਸ ਨਾਮ ਨਾਲ ਮਿਲਾਇਆ ਜਾਂਦਾ ਹੈ, ਇਸ ਲਈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇੱਥੇ "Wallet" ਨਾਮ ਦੀ ਭੁਗਤਾਨ ਵਿਧੀ ਸ਼ਾਮਲ ਨਹੀਂ ਕਰਦੇ, ਗਾਹਕ ਆਪਣੇ ਵਾਲੇਟ ਨਾਲ ਭੁਗਤਾਨ ਨਹੀਂ ਕਰ ਸਕਦੇ:',
'Show_Previous_Dues_Line' => 'ਪਿਛਲੇ ਬਕਾਏ ਦੀ ਲਾਈਨ ਦਿਖਾਓ',
'Show_Previous_Dues_Line_Desc' => 'ਇਸ ਵਿਕਰੀ ਤੋਂ ਪਹਿਲਾਂ ਗਾਹਕ ਵੱਲ ਬਕਾਇਆ ਰਕਮ। ਸਿਰਫ਼ ਉਦੋਂ ਪ੍ਰਿੰਟ ਹੁੰਦੀ ਹੈ ਜਦੋਂ ਇਹ ਜ਼ੀਰੋ ਤੋਂ ਵੱਧ ਹੋਵੇ।',
'Show_Net_Balance_Line' => 'ਸ਼ੁੱਧ ਬਕਾਇਆ ਲਾਈਨ ਦਿਖਾਓ',
'Show_Net_Balance_Line_Desc' => 'ਪਿਛਲਾ ਬਕਾਇਆ ਜਮ੍ਹਾਂ ਇਸ ਵਿਕਰੀ \'ਤੇ ਅਜੇ ਬਾਕੀ ਰਕਮ। ਸਿਰਫ਼ ਉਦੋਂ ਪ੍ਰਿੰਟ ਹੁੰਦੀ ਹੈ ਜਦੋਂ ਪਿਛਲਾ ਬਕਾਇਆ ਜ਼ੀਰੋ ਤੋਂ ਵੱਧ ਹੋਵੇ।',
'QZ_Tray_Printer' => 'QZ Tray (ਇਸ ਕੰਪਿਊਟਰ \'ਤੇ ਪ੍ਰਿੰਟਰ)',
'QZ_Printer_Name_Hint' => 'ਪ੍ਰਿੰਟਰ ਦਾ ਨਾਮ ਜਿਵੇਂ ਇਹ QZ Tray ਚਲਾ ਰਹੇ ਕੰਪਿਊਟਰ \'ਤੇ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ। ਉਸ ਕੰਪਿਊਟਰ ਦਾ ਡਿਫੌਲਟ ਪ੍ਰਿੰਟਰ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ। ਪ੍ਰਿੰਟਰ ਲੱਭਣ ਲਈ ⟳ \'ਤੇ ਕਲਿੱਕ ਕਰੋ।',
'QZ_Not_Running' => 'QZ Tray ਇਸ ਕੰਪਿਊਟਰ \'ਤੇ ਨਹੀਂ ਚੱਲ ਰਿਹਾ। ਇਸਨੂੰ qz.io ਤੋਂ ਇੰਸਟਾਲ ਕਰੋ ਅਤੇ ਚੱਲਦਾ ਰੱਖੋ, ਫਿਰ QZ ਦੇ ਪੁੱਛਣ \'ਤੇ ਇਸ ਵੈੱਬਸਾਈਟ ਦੀ ਆਗਿਆ ਦਿਓ।',
'Detect_Printers' => 'ਪ੍ਰਿੰਟਰ ਲੱਭੋ',
'QZ_Download_Cert' => 'ਸਰਟੀਫਿਕੇਟ ਡਾਊਨਲੋਡ ਕਰੋ (override.crt)',
'QZ_Setup_Title' => 'QZ Tray ਪ੍ਰਿੰਟਿੰਗ ਕਿਵੇਂ ਸੈੱਟ ਕਰੀਏ (ਇੱਕ ਵਾਰ, ਲੇਬਲ ਪ੍ਰਿੰਟ ਕਰਨ ਵਾਲੇ ਹਰ ਕੰਪਿਊਟਰ \'ਤੇ)',
'QZ_Step_Install' => '1. ਇਸ ਕੰਪਿਊਟਰ \'ਤੇ QZ Tray ਇੰਸਟਾਲ ਕਰੋ — ਇਸਨੂੰ qz.io ਤੋਂ ਮੁਫ਼ਤ ਡਾਊਨਲੋਡ ਕਰੋ, ਫਿਰ ਚਾਲੂ ਕਰੋ ਅਤੇ ਚੱਲਦਾ ਛੱਡ ਦਿਓ (ਇਹ Windows \'ਤੇ ਸਿਸਟਮ ਟ੍ਰੇ ਵਿੱਚ ਜਾਂ macOS \'ਤੇ ਮੀਨੂ ਬਾਰ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ)।',
'QZ_Step_Connect' => '2. ਆਪਣਾ ਲੇਬਲ ਪ੍ਰਿੰਟਰ USB ਨਾਲ ਜੋੜੋ ਅਤੇ ਜਾਂਚ ਕਰੋ ਕਿ ਇਹ ਓਪਰੇਟਿੰਗ ਸਿਸਟਮ ਵਿੱਚ ਇੰਸਟਾਲ ਹੈ (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners)।',
'QZ_Step_Detect' => '3. ਇਸ ਕੰਪਿਊਟਰ \'ਤੇ ਪ੍ਰਿੰਟਰ ਲੱਭਣ ਲਈ ਉੱਪਰ "ਪ੍ਰਿੰਟਰ ਦਾ ਨਾਮ" ਦੇ ਕੋਲ ⟳ ਬਟਨ \'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਫਿਰ ਆਪਣਾ ਲੇਬਲ ਪ੍ਰਿੰਟਰ ਚੁਣੋ। ਕੰਪਿਊਟਰ ਦਾ ਡਿਫੌਲਟ ਪ੍ਰਿੰਟਰ ਵਰਤਣ ਲਈ ਖੇਤਰ ਖਾਲੀ ਛੱਡੋ।',
'QZ_Step_Cert' => '4. ਬਿਨਾਂ ਅਨੁਮਤੀ ਪੌਪਅੱਪ ਦੇ ਪ੍ਰਿੰਟਿੰਗ ਲਈ, ਹੇਠਾਂ ਦਿੱਤਾ ਸਰਟੀਫਿਕੇਟ ਡਾਊਨਲੋਡ ਕਰੋ ਅਤੇ ਇਸਨੂੰ override.crt ਨਾਮ ਦੇ ਕੇ QZ Tray ਇੰਸਟਾਲੇਸ਼ਨ ਫੋਲਡਰ ਵਿੱਚ ਕਾਪੀ ਕਰੋ (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray)। ਫਿਰ QZ Tray ਬੰਦ ਕਰੋ ਅਤੇ ਦੁਬਾਰਾ ਚਾਲੂ ਕਰੋ।',
'QZ_Step_Test' => '5. ਹੇਠਾਂ "ਟੈਸਟ ਲੇਬਲ ਪ੍ਰਿੰਟ ਕਰੋ" \'ਤੇ ਕਲਿੱਕ ਕਰੋ। ਜੇ QZ Tray ਅਨੁਮਤੀ ਮੰਗੇ, ਤਾਂ ਆਗਿਆ ਦਿਓ \'ਤੇ ਕਲਿੱਕ ਕਰੋ — ਸਰਟੀਫਿਕੇਟ ਇੰਸਟਾਲ ਹੋਣ ਨਾਲ ਇਹ ਦੁਬਾਰਾ ਨਹੀਂ ਪੁੱਛੇਗਾ।',
'QZ_Step_Save' => '6. ਇਹ ਸੈਟਿੰਗਾਂ ਸੇਵ ਕਰਨ ਲਈ ਸਬਮਿਟ \'ਤੇ ਕਲਿੱਕ ਕਰੋ। ਬਾਰਕੋਡ ਪ੍ਰਿੰਟ ਕਰੋ ਪੰਨੇ ਤੋਂ ਲੇਬਲ ਹੁਣ ਬਿਨਾਂ ਬ੍ਰਾਊਜ਼ਰ ਪ੍ਰਿੰਟ ਡਾਇਲਾਗ ਦੇ ਸਿੱਧੇ ਇਸ ਪ੍ਰਿੰਟਰ \'ਤੇ ਪ੍ਰਿੰਟ ਹੋਣਗੇ।',
'QZ_Setup_Note' => 'QZ Tray ਉਸ ਕੰਪਿਊਟਰ \'ਤੇ ਚੱਲਦਾ ਹੈ ਜਿਸ ਤੋਂ ਤੁਸੀਂ ਬ੍ਰਾਊਜ਼ ਕਰ ਰਹੇ ਹੋ, ਇਸ ਲਈ ਇਹ ਉਦੋਂ ਵੀ ਕੰਮ ਕਰਦਾ ਹੈ ਜਦੋਂ Stocky ਰਿਮੋਟ ਸਰਵਰ \'ਤੇ ਹੋਸਟ ਹੋਵੇ। ਲੇਬਲ ਪ੍ਰਿੰਟ ਕਰਨ ਵਾਲੇ ਹਰ ਕੰਪਿਊਟਰ \'ਤੇ QZ Tray ਇੰਸਟਾਲ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।',
'PWA_Enabled' => 'ਇੰਸਟਾਲ ਹੋਣ ਯੋਗ ਐਪ ਯੋਗ ਕਰੋ',
'PWA_Enabled_Help' => 'ਬ੍ਰਾਊਜ਼ਰਾਂ ਨੂੰ ਫ਼ੋਨਾਂ, ਟੈਬਲੇਟਾਂ ਅਤੇ ਡੈਸਕਟਾਪਾਂ \'ਤੇ ਇਹ ਐਪ ਇੰਸਟਾਲ ਕਰਨ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰਨ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਆਫ਼ਲਾਈਨ ਕੰਮ ਕਰਨ ਵਾਲੇ ਪੰਨੇ ਕੈਸ਼ ਵਿੱਚ ਰੱਖਦਾ ਹੈ। ਇਸਨੂੰ ਬੰਦ ਕਰਨ ਨਾਲ ਹਰ ਥਾਂ ਤੋਂ ਇੰਸਟਾਲ ਪ੍ਰੋਂਪਟ ਹਟ ਜਾਂਦਾ ਹੈ ਅਤੇ ਅਗਲੀ ਫੇਰੀ \'ਤੇ ਕੈਸ਼ ਸਾਫ਼ ਹੋ ਜਾਂਦਾ ਹੈ।',
'PWA_Identity' => 'ਐਪ ਪਛਾਣ',
'PWA_Launch' => 'ਲਾਂਚ ਅਤੇ ਦਿੱਖ',
'PWA_App_Name' => 'ਐਪ ਦਾ ਨਾਮ',
'PWA_App_Name_Help' => 'ਇੰਸਟਾਲ ਪ੍ਰੋਂਪਟ ਅਤੇ ਐਪ ਸੂਚੀ ਵਿੱਚ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ। ਦਿੱਖ ਸੈਟਿੰਗਾਂ ਵਾਲਾ ਐਪ ਨਾਮ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।',
'PWA_Short_Name' => 'ਛੋਟਾ ਨਾਮ',
'PWA_Short_Name_Help' => 'ਹੋਮ ਸਕ੍ਰੀਨਾਂ \'ਤੇ ਆਈਕਨ ਦੇ ਹੇਠਾਂ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ, ਜਿੱਥੇ ਲੰਬੇ ਨਾਮ ਕੱਟੇ ਜਾਂਦੇ ਹਨ। ਐਪ ਨਾਮ ਦਾ "|" ਤੋਂ ਪਹਿਲਾਂ ਵਾਲਾ ਹਿੱਸਾ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।',
'PWA_Description' => 'ਵੇਰਵਾ',
'PWA_Description_Help' => 'ਕੁਝ ਐਪ ਸਟੋਰਾਂ ਅਤੇ ਇੰਸਟਾਲ ਡਾਇਲਾਗਾਂ ਵੱਲੋਂ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।',
'PWA_Start_Url' => 'ਲਾਂਚ ਪੰਨਾ',
'PWA_Start_Url_Help' => 'ਉਹ ਪੰਨਾ ਜਿਸ \'ਤੇ ਇੰਸਟਾਲ ਕੀਤੀ ਐਪ ਖੁੱਲ੍ਹਦੀ ਹੈ, "/" ਨਾਲ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੇ ਪਾਥ ਵਜੋਂ। ਸਿੱਧਾ POS ਵਿੱਚ ਲਾਂਚ ਕਰਨ ਲਈ /next/pos ਵਰਤੋ।',
'PWA_Display_Mode' => 'ਡਿਸਪਲੇ ਮੋਡ',
'PWA_Display_Mode_Help' => 'standalone ਬ੍ਰਾਊਜ਼ਰ ਬਾਰ ਲੁਕਾਉਂਦਾ ਹੈ; fullscreen ਸਥਿਤੀ ਬਾਰ ਵੀ ਲੁਕਾਉਂਦਾ ਹੈ; browser ਇੱਕ ਆਮ ਟੈਬ ਖੋਲ੍ਹਦਾ ਹੈ।',
'PWA_Orientation' => 'ਦਿਸ਼ਾ-ਸਥਿਤੀ',
'PWA_Theme_Color' => 'ਥੀਮ ਰੰਗ',
'PWA_Theme_Color_Help' => 'ਇੰਸਟਾਲ ਕੀਤੀ ਐਪ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਸਿਸਟਮ ਬਾਰਾਂ ਨੂੰ ਰੰਗ ਦਿੰਦਾ ਹੈ।',
'PWA_Background_Color' => 'ਸਪਲੈਸ਼ ਪਿਛੋਕੜ',
'PWA_Background_Color_Help' => 'ਐਪ ਸ਼ੁਰੂ ਹੋਣ ਵੇਲੇ ਦਿਖਾਈ ਜਾਣ ਵਾਲੀ ਸਪਲੈਸ਼ ਸਕ੍ਰੀਨ ਦਾ ਪਿਛੋਕੜ।',
'PWA_Preview' => 'ਝਲਕ',
'PWA_View_Manifest' => 'ਮੈਨੀਫੈਸਟ ਫ਼ਾਈਲ ਦੇਖੋ',
'PWA_Reinstall_Notice' => 'ਜਿਨ੍ਹਾਂ ਡਿਵਾਈਸਾਂ \'ਤੇ ਐਪ ਪਹਿਲਾਂ ਹੀ ਇੰਸਟਾਲ ਹੈ ਉਹ ਪੁਰਾਣਾ ਨਾਮ ਅਤੇ ਆਈਕਨ ਉਦੋਂ ਤੱਕ ਰੱਖਦੀਆਂ ਹਨ ਜਦੋਂ ਤੱਕ ਇਸਨੂੰ ਅਣਇੰਸਟਾਲ ਕਰਕੇ ਦੁਬਾਰਾ ਇੰਸਟਾਲ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ।',
'Label_Render_Mode' => 'ਲੇਬਲ ਰੈਂਡਰਿੰਗ',
'Label_Render_Mode_Hint' => 'ਲੇਬਲ ਕਿਵੇਂ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ। ਪ੍ਰਿੰਟਰ ਫੌਂਟ ਸਭ ਤੋਂ ਤੇਜ਼ ਹਨ ਅਤੇ ਸਭ ਤੋਂ ਤਿੱਖਾ ਬਾਰਕੋਡ ਦਿੰਦੇ ਹਨ, ਪਰ ਸਿਰਫ਼ ਮੁੱਢਲੇ ਲਾਤੀਨੀ ਅੱਖਰ ਪ੍ਰਿੰਟਰ ਦੇ ਆਪਣੇ ਟਾਈਪਫੇਸ ਵਿੱਚ ਪ੍ਰਿੰਟ ਕਰਦੇ ਹਨ। ਪ੍ਰੀਵਿਊ ਚਿੱਤਰ ਤੁਹਾਡੇ ਲੇਬਲ ਡਿਜ਼ਾਈਨ ਨੂੰ ਬਿਲਕੁਲ ਉਸੇ ਤਰ੍ਹਾਂ ਬਣਾਉਂਦਾ ਹੈ — ਤੁਹਾਡਾ ਚੁਣਿਆ ਫੌਂਟ, ਕੋਈ ਵੀ ਭਾਸ਼ਾ — ਜਿਵੇਂ ਸਮਰਪਿਤ ਲੇਬਲ ਸਾਫ਼ਟਵੇਅਰ ਕਰਦਾ ਹੈ।',
'Render_Native' => 'ਪ੍ਰਿੰਟਰ ਫੌਂਟ (ਸਭ ਤੋਂ ਤੇਜ਼)',
'Render_Raster' => 'ਪ੍ਰੀਵਿਊ ਚਿੱਤਰ (ਸਹੀ ਡਿਜ਼ਾਈਨ)',
'Label_Width_Mm' => 'ਲੇਬਲ ਚੌੜਾਈ (mm)',
'Label_Height_Mm' => 'ਲੇਬਲ ਉਚਾਈ (mm)',
'Label_Size_Hint' => 'ਰੋਲ \'ਤੇ ਇੱਕ ਸਟਿੱਕਰ ਦਾ ਭੌਤਿਕ ਆਕਾਰ। ਇਹ ਲੋਡ ਕੀਤੇ ਲੇਬਲਾਂ ਨਾਲ ਬਿਲਕੁਲ ਮੇਲ ਖਾਣਾ ਚਾਹੀਦਾ ਹੈ — ਗਲਤ ਆਕਾਰ ਨਾਲ ਪ੍ਰਿੰਟਰ ਗਲਤ ਥਾਂ \'ਤੇ ਵਿੱਥ ਲੱਭਦਾ ਹੈ, ਇਸ ਲਈ ਹਰ ਲੇਬਲ ਹੋਰ ਥਾਂ ਤੋਂ ਹਟ ਕੇ ਪ੍ਰਿੰਟ ਹੁੰਦਾ ਹੈ।',
'Calibrate_Labels' => 'ਲੇਬਲ ਕੈਲੀਬ੍ਰੇਟ ਕਰੋ',
'Calibrate_Labels_Hint' => 'ਪ੍ਰਿੰਟਰ ਸਟਿੱਕਰ ਅਤੇ ਵਿੱਥ ਨੂੰ ਮਾਪਣ ਲਈ ਕੁਝ ਲੇਬਲ ਅੱਗੇ ਕੱਢਦਾ ਹੈ। ਨਵਾਂ ਰੋਲ ਲੋਡ ਕਰਨ ਤੋਂ ਬਾਅਦ, ਜਾਂ ਜਦੋਂ ਪ੍ਰਿੰਟ ਸਥਿਤੀਆਂ ਖਿਸਕਣ, ਇੱਕ ਵਾਰ ਚਲਾਓ।',
'Calibration_Sent' => 'ਕੈਲੀਬ੍ਰੇਸ਼ਨ ਸ਼ੁਰੂ ਹੋ ਗਈ — ਪ੍ਰਿੰਟਰ ਮਾਪਣ ਲਈ ਕੁਝ ਖਾਲੀ ਲੇਬਲ ਅੱਗੇ ਕੱਢੇਗਾ। ਜਦੋਂ ਇਹ ਰੁਕੇ, ਟੈਸਟ ਪ੍ਰਿੰਟ ਚਲਾਓ।',
'Label_Printer_Dpi' => 'ਪ੍ਰਿੰਟਹੈੱਡ ਰੈਜ਼ੋਲਿਊਸ਼ਨ',
'Label_Printer_Dpi_Hint' => 'ਜ਼ਿਆਦਾਤਰ ਲੇਬਲ ਪ੍ਰਿੰਟਰ 203 dpi ਹੁੰਦੇ ਹਨ। ਪੱਕਾ ਨਹੀਂ? ਹੇਠਾਂ "ਰੈਜ਼ੋਲਿਊਸ਼ਨ ਲੱਭੋ" ਬਟਨ ਵਰਤੋ — ਇਹ ਜਵਾਬ ਪ੍ਰਿੰਟ ਕਰਦਾ ਹੈ।',
'Find_Resolution' => 'ਰੈਜ਼ੋਲਿਊਸ਼ਨ ਲੱਭੋ',
'Find_Resolution_Hint' => '203 ਅਤੇ 300 ਨਿਸ਼ਾਨ ਵਾਲੇ ਦੋ ਲੇਬਲ ਪ੍ਰਿੰਟ ਕਰਦਾ ਹੈ। ਸਹੀ ਵਾਲਾ ਸਟਿੱਕਰ \'ਤੇ ਚਾਰੇ ਪਾਸੇ ਛੋਟੇ ਬਰਾਬਰ ਹਾਸ਼ੀਏ ਨਾਲ ਪੂਰਾ ਆਇਤ ਦਿਖਾਉਂਦਾ ਹੈ; ਗਲਤ ਵਾਲੇ ਵਿੱਚ ਕਿਨਾਰੇ ਗਾਇਬ ਹੁੰਦੇ ਹਨ ਜਾਂ ਇਹ ਅਗਲੇ ਸਟਿੱਕਰ \'ਤੇ ਚਲਾ ਜਾਂਦਾ ਹੈ।',
'Dpi_Test_Sent' => '203 ਅਤੇ 300 ਨਿਸ਼ਾਨ ਵਾਲੇ ਦੋ ਲੇਬਲ ਪ੍ਰਿੰਟ ਹੋ ਰਹੇ ਹਨ। ਸਹੀ ਵਾਲਾ ਚਾਰੇ ਪਾਸੇ ਛੋਟੇ, ਬਰਾਬਰ ਹਾਸ਼ੀਏ ਨਾਲ ਪੂਰਾ ਆਇਤ ਦਿਖਾਉਂਦਾ ਹੈ — "ਪ੍ਰਿੰਟਹੈੱਡ ਰੈਜ਼ੋਲਿਊਸ਼ਨ" ਨੂੰ ਉਸ ਨੰਬਰ \'ਤੇ ਸੈੱਟ ਕਰੋ ਅਤੇ ਸੇਵ ਕਰੋ।',
'Label_Offset_X' => 'ਲੇਟਵਾਂ ਆਫ਼ਸੈੱਟ (mm)',
'Label_Offset_X_Hint' => 'ਪ੍ਰਿੰਟ ਨੂੰ ਸਟਿੱਕਰ \'ਤੇ ਪਾਸੇ ਵੱਲ ਖਿਸਕਾਉਂਦਾ ਹੈ। ਜਦੋਂ ਟੈਕਸਟ ਇੱਕ ਪਾਸੇ ਦੇ ਕਿਨਾਰੇ \'ਤੇ ਕੱਟਿਆ ਜਾਵੇ ਤਾਂ ਵਰਤੋ — ਜਿਵੇਂ 2.5 ਜਦੋਂ ਚਿੱਟਾ ਸਟਿੱਕਰ ਚੌੜੇ ਬੈਕਿੰਗ ਕਾਗਜ਼ \'ਤੇ ਵਿਚਕਾਰ ਹੋਵੇ। 0.5 ਦੇ ਕਦਮਾਂ ਵਿੱਚ ਵਿਵਸਥਿਤ ਕਰੋ।',
'Label_Offset_Y' => 'ਖੜ੍ਹਵਾਂ ਆਫ਼ਸੈੱਟ (mm)',
'Label_Offset_Y_Hint' => 'ਪ੍ਰਿੰਟ ਨੂੰ ਲੇਬਲ ਦੇ ਨਾਲ-ਨਾਲ ਖਿਸਕਾਉਂਦਾ ਹੈ। ਜਦੋਂ ਡਿਜ਼ਾਈਨ ਦਾ ਉੱਪਰਲਾ ਹਿੱਸਾ ਕੱਟਿਆ ਜਾਂ ਗਾਇਬ ਹੋਵੇ ਤਾਂ ਵਧਾਓ; ਜਦੋਂ ਇਹ ਬਹੁਤ ਹੇਠਾਂ ਤੋਂ ਸ਼ੁਰੂ ਹੋਵੇ ਤਾਂ ਘਟਾਓ।',
'Feed_To_Tear' => 'ਟੀਅਰ ਕਿਨਾਰੇ ਤੱਕ ਫੀਡ ਕਰੋ',
'Feed_To_Tear_Hint' => 'ਹਰ ਕੰਮ ਤੋਂ ਬਾਅਦ ਲੇਬਲ ਨੂੰ ਟੀਅਰ ਬਾਰ ਤੱਕ ਅੱਗੇ ਵਧਾਉਂਦਾ ਹੈ। ਜੇ ਲੇਬਲ ਹੇਠਾਂ ਵੱਲ ਖਿਸਕ ਕੇ ਜਾਂ ਸਟਿੱਕਰਾਂ ਵਿੱਚ ਵੰਡੇ ਹੋਏ ਪ੍ਰਿੰਟ ਹੋਣ ਤਾਂ ਬੰਦ ਰੱਖੋ — ਬਹੁਤ ਸਾਰੇ ਪ੍ਰਿੰਟਰ ਅਗਲੇ ਲੇਬਲ ਤੋਂ ਪਹਿਲਾਂ ਵਾਪਸ ਪਿੱਛੇ ਨਹੀਂ ਜਾਂਦੇ।',
