'Recovery_Required_Text' => 'ਆਟੋਮੈਟਿਕ ਰੋਲਬੈਕ ਆਪਣੇ ਆਪ ਪੂਰਾ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਤੁਹਾਡਾ ਅੱਪਡੇਟ ਤੋਂ ਪਹਿਲਾਂ ਦਾ ਬੈਕਅੱਪ ਸੁਰੱਖਿਅਤ ਹੈ। ਤੁਸੀਂ ਰੋਲਬੈਕ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕਦੇ ਹੋ, ਜਾਂ ਬੈਕਅੱਪ ਪੈਨਲ ਤੋਂ ਬੈਕਅੱਪ ਬਹਾਲ ਕਰ ਸਕਦੇ ਹੋ। ਇਸਦੇ ਹੱਲ ਹੋਣ ਤੱਕ ਕੁਝ ਵੀ ਮਿਟਾਇਆ ਨਹੀਂ ਜਾਵੇਗਾ।',
