'Restore_Backup_Confirm_Text' => 'ਇਹ ਬੈਕਅੱਪ ਬਹਾਲ ਕਰਨਾ ਹੈ? ਮੌਜੂਦਾ ਫ਼ਾਈਲਾਂ ਅਤੇ ਮੌਜੂਦਾ ਡਾਟਾਬੇਸ ਬੈਕਅੱਪ ਨਾਲ ਬਦਲ ਦਿੱਤੇ ਜਾਣਗੇ। ਪਹਿਲਾਂ ਮੌਜੂਦਾ ਡਾਟਾਬੇਸ ਦੀ ਸੁਰੱਖਿਆ ਕਾਪੀ ਲਈ ਜਾਂਦੀ ਹੈ।',
