'Preorder_Uses_Delivery_Date' => 'ਉਪਲਬਧਤਾ ਉੱਪਰ ਸਟੋਰ ਭਾਗ ਵਿੱਚ ਸੈੱਟ ਕੀਤੀ ਅਨੁਮਾਨਿਤ ਡਿਲੀਵਰੀ ਮਿਤੀ ਵਰਤਦੀ ਹੈ।',
'Related_Products' => 'ਸਬੰਧਤ ਉਤਪਾਦ',
'Related_Products_Hint' => 'ਇਸ ਉਤਪਾਦ ਪੰਨੇ \'ਤੇ "ਸਬੰਧਤ ਉਤਪਾਦ" ਵਿੱਚ ਦਿਖਾਏ ਜਾਣ ਵਾਲੇ ਉਤਪਾਦ ਕ੍ਰਮ ਵਿੱਚ ਚੁਣੋ। ਆਟੋਮੈਟਿਕ ਨਿਯਮ (ਉਹੀ ਸ਼੍ਰੇਣੀ, ਫਿਰ ਸਭ ਤੋਂ ਨਵੇਂ) ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।',
'Enable_Wholesale_Pricing' => 'ਮਾਤਰਾ ਅਨੁਸਾਰ ਥੋਕ ਕੀਮਤ',
'Enable_Wholesale_Pricing_Hint' => 'ਉਤਪਾਦਾਂ ਨੂੰ ਮਾਤਰਾ ਪੱਧਰ (10-19 pcs, 20-49 pcs, 100+ ...) ਰੱਖਣ ਦਿਓ ਜੋ ਆਰਡਰ ਕੀਤੀ ਮਾਤਰਾ ਕਿਸੇ ਪੱਧਰ ਤੱਕ ਪਹੁੰਚਣ \'ਤੇ POS ਅਤੇ ਆਨਲਾਈਨ ਸਟੋਰ ਵਿੱਚ ਪ੍ਰਚੂਨ ਕੀਮਤ ਦੀ ਥਾਂ ਆਪਣੇ ਆਪ ਲੈ ਲੈਂਦੇ ਹਨ। ਇਸਨੂੰ ਬੰਦ ਕਰੋ ਅਤੇ ਸਭ ਕੁਝ ਫਿਰ ਤੋਂ ਆਮ ਪ੍ਰਚੂਨ ਕੀਮਤ \'ਤੇ ਵਿਕਦਾ ਹੈ — ਸੰਰਚਿਤ ਪੱਧਰ ਰੱਖੇ ਜਾਂਦੇ ਹਨ, ਬੱਸ ਲਾਗੂ ਨਹੀਂ ਹੁੰਦੇ।',
'Wholesale_Pricing_By_Quantity' => 'ਮਾਤਰਾ ਅਨੁਸਾਰ ਥੋਕ ਕੀਮਤ',
'Wholesale_Pricing_By_Quantity_Hint' => 'ਆਰਡਰ ਕੀਤੀ ਮਾਤਰਾ ਕਿਸੇ ਪੱਧਰ ਤੱਕ ਪਹੁੰਚਣ \'ਤੇ ਪ੍ਰਤੀ ਪੀਸ ਕੀਮਤ। ਖੁੱਲ੍ਹੇ ਸਿਖਰਲੇ ਪੱਧਰ (ਜਿਵੇਂ 100 ਅਤੇ ਵੱਧ) ਲਈ ਵੱਧ ਤੋਂ ਵੱਧ ਖਾਲੀ ਛੱਡੋ। ਪਹਿਲੇ ਪੱਧਰ ਤੋਂ ਘੱਟ \'ਤੇ ਉਤਪਾਦ ਆਪਣੀ ਆਮ ਪ੍ਰਚੂਨ ਕੀਮਤ \'ਤੇ ਵਿਕਦਾ ਹੈ।',
'Wholesale_Pricing_Variants_Hint' => 'ਇੱਕ ਪੌੜੀ ਪੂਰੇ ਉਤਪਾਦ ਨੂੰ ਕਵਰ ਕਰਦੀ ਹੈ: ਹਰ ਵੇਰੀਐਂਟ ਉਦੋਂ ਪੱਧਰ ਕੀਮਤ \'ਤੇ ਵਿਕਦਾ ਹੈ ਜਦੋਂ ਉਸਦੀ ਆਪਣੀ ਲਾਈਨ ਕਿਸੇ ਪੱਧਰ ਤੱਕ ਪਹੁੰਚਦੀ ਹੈ।',
'Min_Quantity' => 'ਘੱਟੋ-ਘੱਟ ਮਾਤਰਾ',
'Max_Quantity' => 'ਵੱਧ ਤੋਂ ਵੱਧ ਮਾਤਰਾ',
'Price_Per_Piece' => 'ਪ੍ਰਤੀ ਪੀਸ ਕੀਮਤ',
'Wholesale' => 'ਥੋਕ',
'Wholesale_Tier_Applied' => 'ਇਸ ਲਾਈਨ \'ਤੇ ਥੋਕ ਮਾਤਰਾ ਪੱਧਰ ਲਾਗੂ ਹੁੰਦਾ ਹੈ',
'Orders_Guide' => 'ਆਰਡਰ ਗਾਈਡ',
'Ord_Guide_Intro' => 'ਤੁਹਾਡੇ ਆਨਲਾਈਨ ਸਟੋਰ \'ਤੇ ਦਿੱਤਾ ਆਰਡਰ ਤੁਹਾਡੇ ਸਟਾਕ ਅਤੇ ਖਾਤਿਆਂ ਤੱਕ ਕਿਵੇਂ ਪਹੁੰਚਦਾ ਹੈ, ਅਤੇ ਪੈਸਾ ਅਸਲ ਵਿੱਚ ਕਿੱਥੇ ਦਰਜ ਹੁੰਦਾ ਹੈ।',
'Ord_Guide_Lifecycle_Title' => 'ਆਰਡਰ ਸਥਿਤੀ',
'Ord_Guide_Lifecycle_Pending' => 'ਤੁਹਾਡੀ ਸਮੀਖਿਆ ਦੀ ਉਡੀਕ ਕਰ ਰਿਹਾ ਨਵਾਂ ਆਰਡਰ। ਸਿਰਫ਼ ਬਕਾਇਆ ਆਰਡਰ ਹੀ ਪੁਸ਼ਟੀ ਜਾਂ ਰੱਦ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।',
'Ord_Guide_Lifecycle_Confirmed' => 'ਤੁਸੀਂ ਆਰਡਰ ਸਵੀਕਾਰ ਕੀਤਾ। Stocky ਤੁਹਾਡੇ ਚੁਣੇ ਵੇਅਰਹਾਊਸ ਵਿੱਚ ਇੱਕ ਵਿਕਰੀ ਬਣਾਉਂਦਾ ਹੈ ਅਤੇ ਸਟਾਕ ਘਟਾਉਂਦਾ ਹੈ — ਉਹ ਵਿਕਰੀ ਉਹ ਰਿਕਾਰਡ ਹੈ ਜਿਸ ਤੋਂ ਤੁਹਾਡੀਆਂ ਸਟਾਕ, ਭੁਗਤਾਨ ਅਤੇ ਮੁਨਾਫ਼ਾ ਰਿਪੋਰਟਾਂ ਪੜ੍ਹਦੀਆਂ ਹਨ।',
'Ord_Guide_Lifecycle_Shipped' => 'ਤੁਸੀਂ ਆਰਡਰ ਭੇਜ ਦਿੱਤਾ। ਸਿਰਫ਼ ਪੂਰਤੀ: ਸਟਾਕ ਪੁਸ਼ਟੀ ਕਰਨ ਵੇਲੇ ਹੀ ਘਟਾਇਆ ਜਾ ਚੁੱਕਾ ਸੀ।',
'Ord_Guide_Lifecycle_Delivered' => 'ਗਾਹਕ ਨੂੰ ਆਰਡਰ ਮਿਲ ਗਿਆ। ਇਸੇ ਨਾਲ ਵਾਪਸੀ ਦੀ ਮਿਆਦ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ।',
'Ord_Guide_Lifecycle_Cancelled' => 'ਆਰਡਰ ਪੁਸ਼ਟੀ ਤੋਂ ਪਹਿਲਾਂ ਛੱਡ ਦਿੱਤਾ ਗਿਆ, ਇਸ ਲਈ ਕੋਈ ਵਿਕਰੀ ਨਹੀਂ ਬਣੀ ਅਤੇ ਕੋਈ ਸਟਾਕ ਨਹੀਂ ਘਟਿਆ।',
'Ord_Guide_PaymentStatus_Tip' => 'ਚੈੱਕਆਊਟ ਵੇਲੇ ਸੈੱਟ ਹੁੰਦਾ ਹੈ ਅਤੇ ਇੱਥੇ ਸੰਪਾਦਨਯੋਗ ਨਹੀਂ। ਭੁਗਤਾਨ ਕਿਵੇਂ ਦਰਜ ਕਰਨਾ ਹੈ ਦੇਖਣ ਲਈ ਕਲਿੱਕ ਕਰੋ।',
'Ord_Guide_Payment_Title' => 'ਭੁਗਤਾਨ ਸਥਿਤੀ',
'Ord_Guide_Payment_Intro' => 'ਇਹ ਕਾਲਮ ਦਰਜ ਕਰਦਾ ਹੈ ਕਿ ਗਾਹਕ ਨੇ ਚੈੱਕਆਊਟ ਵੇਲੇ ਭੁਗਤਾਨ ਕਿਵੇਂ ਕਰਨਾ ਚੁਣਿਆ। ਇਹ ਸਟੋਰਫਰੰਟ ਦੁਆਰਾ ਸੈੱਟ ਹੁੰਦਾ ਹੈ ਅਤੇ ਇਸ ਪੰਨੇ ਤੋਂ ਸੰਪਾਦਿਤ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ — ਪੈਸਾ ਖੁਦ ਉਸ ਵਿਕਰੀ \'ਤੇ ਟ੍ਰੈਕ ਹੁੰਦਾ ਹੈ ਜੋ ਆਰਡਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਨਾਲ ਬਣਦੀ ਹੈ।',
'Ord_Guide_Payment_Paid' => 'ਗਾਹਕ ਪਹਿਲਾਂ ਹੀ ਪੇਮੈਂਟ ਗੇਟਵੇ ਰਾਹੀਂ ਆਨਲਾਈਨ ਭੁਗਤਾਨ ਕਰ ਚੁੱਕਾ ਹੈ। ਆਰਡਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਨਾਲ ਵਿਕਰੀ ਅਦਾ ਵਜੋਂ ਬਣਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੇ ਲਈ ਭੁਗਤਾਨ ਦਰਜ ਹੋ ਜਾਂਦਾ ਹੈ — ਹੋਰ ਕੁਝ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।',
'Ord_Guide_Payment_Pending' => 'ਡਿਲੀਵਰੀ \'ਤੇ ਨਕਦ, ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਜਾਂ ਕੋਈ ਹੋਰ ਬਾਅਦ ਵਿੱਚ ਭੁਗਤਾਨ ਵਿਧੀ। ਆਰਡਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਨਾਲ ਵਿਕਰੀ ਅਣਅਦਾ ਵਜੋਂ ਬਣਦੀ ਹੈ, ਇਸ ਲਈ ਪੈਸਾ ਇਕੱਠਾ ਕਰਨ ਤੋਂ ਬਾਅਦ ਤੁਸੀਂ ਖੁਦ ਦਰਜ ਕਰਦੇ ਹੋ — ਹੇਠਾਂ ਦਿੱਤੇ ਕਦਮ ਦੇਖੋ।',
'Ord_Guide_Payment_Failed' => 'ਗੇਟਵੇ ਨੇ ਭੁਗਤਾਨ ਅਸਵੀਕਾਰ ਕਰ ਦਿੱਤਾ ਜਾਂ ਗਾਹਕ ਨੇ ਇਸਨੂੰ ਛੱਡ ਦਿੱਤਾ। ਆਰਡਰ ਆਪਣੇ ਆਪ ਰੱਦ ਹੋ ਜਾਂਦਾ ਹੈ।',
'Ord_Guide_MarkPaid_Title' => 'ਭੁਗਤਾਨ ਨੂੰ ਬਕਾਇਆ ਤੋਂ ਅਦਾ ਵਿੱਚ ਬਦਲਣਾ',
'Ord_Guide_MarkPaid_Step1' => 'ਪਹਿਲਾਂ ਇੱਥੇ ਆਰਡਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ — ਪੁਸ਼ਟੀ ਕਰਨ ਨਾਲ ਹੀ ਵਿਕਰੀ ਬਣਦੀ ਹੈ।',
'Ord_Guide_MarkPaid_Step2' => 'ਵਿਕਰੀ > ਸਾਰੀਆਂ ਵਿਕਰੀਆਂ ਖੋਲ੍ਹੋ ਅਤੇ ਉਹ ਵਿਕਰੀ ਲੱਭੋ (ਉਹੀ ਗਾਹਕ, ਅਤੇ ਵੇਰਵੇ ਪੰਨਾ ਉਹ ਆਨਲਾਈਨ ਆਰਡਰ ਦਿਖਾਉਂਦਾ ਹੈ ਜਿਸ ਤੋਂ ਇਹ ਆਈ)।',
'Ord_Guide_MarkPaid_Step3' => 'ਕਤਾਰ ਕਾਰਵਾਈਆਂ ਮੀਨੂ ਖੋਲ੍ਹੋ ਅਤੇ ਭੁਗਤਾਨ ਬਣਾਓ ਚੁਣੋ।',
'Ord_Guide_MarkPaid_Step4' => 'ਰਕਮ, ਭੁਗਤਾਨ ਵਿਧੀ ਅਤੇ ਮਿਤੀ ਦਰਜ ਕਰੋ, ਫਿਰ ਸੇਵ ਕਰੋ। ਰਕਮ ਦੇ ਅਨੁਸਾਰ, ਵਿਕਰੀ ਆਪਣੇ ਆਪ ਅੰਸ਼ਕ ਜਾਂ ਅਦਾ ਵਿੱਚ ਚਲੀ ਜਾਂਦੀ ਹੈ।',
'Ord_Guide_MarkPaid_Note' => 'ਇੱਥੇ ਦਿਖਾਈ ਗਈ ਭੁਗਤਾਨ ਸਥਿਤੀ ਚੈੱਕਆਊਟ ਚੋਣ ਨੂੰ ਦਰਜ ਕਰਦੀ ਰਹਿੰਦੀ ਹੈ ਅਤੇ ਜਿਵੇਂ ਹੈ ਤਿਵੇਂ ਰਹਿੰਦੀ ਹੈ। ਵਿਕਰੀ ਲੇਖਾ ਰਿਕਾਰਡ ਹੈ, ਅਤੇ ਇਹੀ ਤੁਹਾਡੀਆਂ ਭੁਗਤਾਨ ਅਤੇ ਮੁਨਾਫ਼ਾ ਰਿਪੋਰਟਾਂ ਨੂੰ ਡਾਟਾ ਦਿੰਦੀ ਹੈ। ਤੁਹਾਡੇ ਦਰਜ ਕੀਤੇ ਦੀ ਸਮੀਖਿਆ ਜਾਂ ਸੰਪਾਦਨ ਲਈ ਵਿਕਰੀ \'ਤੇ ਭੁਗਤਾਨ ਦਿਖਾਓ ਵਰਤੋ।',
'Ord_Guide_Notes_Title' => 'ਜਾਣਨਯੋਗ ਗੱਲਾਂ',
'Ord_Guide_Note_Warehouse' => 'ਪੁਸ਼ਟੀ ਕਰਦੇ ਸਮੇਂ ਤੁਹਾਡਾ ਚੁਣਿਆ ਵੇਅਰਹਾਊਸ ਤੈਅ ਕਰਦਾ ਹੈ ਕਿ ਸਟਾਕ ਕਿੱਥੋਂ ਲਿਆ ਜਾਵੇ। ਜਿਹੜੇ ਵੇਅਰਹਾਊਸ ਪੂਰਾ ਆਰਡਰ ਪੂਰਾ ਨਹੀਂ ਕਰ ਸਕਦੇ ਉਹ ਉਸ ਸੂਚੀ ਵਿੱਚ ਸਟਾਕ ਖਤਮ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਹੁੰਦੇ ਹਨ।',
'Ord_Guide_Note_Preorder' => 'ਪ੍ਰੀ-ਆਰਡਰ ਆਈਟਮਾਂ ਸਟਾਕ ਜਾਂਚ ਛੱਡ ਦਿੰਦੀਆਂ ਹਨ, ਇਸ ਲਈ ਉਹਨਾਂ ਵਾਲੇ ਆਰਡਰ ਦੀ ਪੁਸ਼ਟੀ ਉਦੋਂ ਵੀ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ ਜਦੋਂ ਮਾਤਰਾ ਅਜੇ ਹੱਥ ਵਿੱਚ ਨਾ ਹੋਵੇ।',
'Ord_Guide_Note_Flagged' => 'ਫਲੈਗ ਕੀਤਾ ਟੈਗ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਆਰਡਰ ਚੈੱਕਆਊਟ ਵੇਲੇ ਧੋਖਾਧੜੀ ਜਾਂਚ ਵਿੱਚ ਫਸਿਆ। ਕਾਰਨ ਦੇਖਣ ਲਈ ਟੈਗ \'ਤੇ ਹੋਵਰ ਕਰੋ ਅਤੇ ਪੁਸ਼ਟੀ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਰਡਰ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।',
'Ord_Guide_Note_Cancel' => 'ਰੱਦ ਕਰਨਾ ਸਿਰਫ਼ ਉਦੋਂ ਸੰਭਵ ਹੈ ਜਦੋਂ ਆਰਡਰ ਅਜੇ ਬਕਾਇਆ ਹੋਵੇ। ਪੁਸ਼ਟੀ ਹੋਣ ਤੋਂ ਬਾਅਦ, ਇਸਦੀ ਬਜਾਏ ਵਿਕਰੀ ਜਾਂ ਗਾਹਕ ਵਾਪਸੀ ਰਾਹੀਂ ਇਸਨੂੰ ਉਲਟਾਓ।',
'CollectAtBranch' => 'ਸ਼ਾਖਾ ਤੋਂ ਲਓ',
'Pickup' => 'ਪਿਕਅੱਪ',
'ProofOfPayment' => 'ਭੁਗਤਾਨ ਦਾ ਸਬੂਤ',
'ReferenceNumber' => 'ਹਵਾਲਾ / ਲੈਣ-ਦੇਣ ਨੰਬਰ',
'AmountSent' => 'ਭੇਜੀ ਗਈ ਰਕਮ',
'PaymentDate' => 'ਭੁਗਤਾਨ ਮਿਤੀ',
'ProofAmountMismatchHint' => 'ਗਾਹਕ ਵੱਲੋਂ ਭੇਜੀ ਦੱਸੀ ਰਕਮ ਆਰਡਰ ਦੀ ਕੁੱਲ ਰਕਮ ਨਹੀਂ ਹੈ।',
'AmountMismatch' => 'ਰਕਮ ਮੇਲ ਨਹੀਂ ਖਾਂਦੀ',
'ViewFile' => 'ਫ਼ਾਈਲ ਦੇਖੋ',
'RejectProof' => 'ਭੁਗਤਾਨ ਦਾ ਸਬੂਤ ਅਸਵੀਕਾਰ ਕਰੋ',
'AwaitingVerification' => 'ਤਸਦੀਕ ਦੀ ਉਡੀਕ',
'PaymentVerified' => 'ਭੁਗਤਾਨ ਤਸਦੀਕ ਹੋਇਆ',
'ProofToVerify' => 'ਤਸਦੀਕ ਲਈ ਸਬੂਤ',
'GCash' => 'GCash',
'BankTransfer' => 'ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ',
'CashOnPickup' => 'ਪਿਕਅੱਪ \'ਤੇ ਨਕਦ',
'OfflinePayments' => 'ਆਫ਼ਲਾਈਨ ਭੁਗਤਾਨ',
'OfflinePaymentsIntro' => 'ਸਿਸਟਮ ਤੋਂ ਬਾਹਰ ਅਦਾ ਕੀਤਾ ਸਭ ਕੁਝ ਇੱਥੇ ਹੈ: ਡਿਲੀਵਰੀ \'ਤੇ ਨਕਦ, ਮੋਬਾਈਲ ਮਨੀ, GCash, ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਅਤੇ ਪਿਕਅੱਪ \'ਤੇ ਨਕਦ। ਇਹ ਆਰਡਰ ਉਦੋਂ ਤੱਕ ਭੁਗਤਾਨ-ਬਕਾਇਆ ਰਹਿੰਦੇ ਹਨ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਉਹਨਾਂ ਨੂੰ ਅਦਾ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਨਹੀਂ ਕਰਦੇ। GCash ਅਤੇ ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਗਾਹਕ ਤੋਂ ਸਕ੍ਰੀਨਸ਼ਾਟ, ਹਵਾਲਾ ਨੰਬਰ ਅਤੇ ਰਕਮ ਮੰਗਦੇ ਹਨ, ਜਿਸਨੂੰ ਤੁਸੀਂ ਆਰਡਰ \'ਤੇ ਮਨਜ਼ੂਰ ਕਰਦੇ ਹੋ।',
'GCashDesc' => 'GCash ਟ੍ਰਾਂਸਫਰ ਰਾਹੀਂ ਭੁਗਤਾਨ ਕਰੋ ਅਤੇ ਭੁਗਤਾਨ ਦਾ ਸਬੂਤ ਅੱਪਲੋਡ ਕਰੋ',
