'Saved_Variants_Removed_On_Save' => 'ਇੱਥੇ ਹਟਾਏ ਗਏ ਸੇਵ ਕੀਤੇ ਵੇਰੀਐਂਟ ਉਤਪਾਦ ਸੇਵ ਕਰਨ \'ਤੇ ਮਿਟਾ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ।',
'Switch_To_List_Confirm' => 'ਸਧਾਰਨ ਸੂਚੀ \'ਤੇ ਜਾਣਾ ਹੈ? ਵਿਕਲਪ ਪਰਿਭਾਸ਼ਾਵਾਂ ਹਟਾ ਦਿੱਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ; ਵੇਰੀਐਂਟ ਕਤਾਰਾਂ ਰੱਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।',
