'Swatches' => 'ਰੰਗ ਸਵੈਚ',
'Guide' => 'ਗਾਈਡ',
'Variants_Guide' => 'ਵੇਰੀਐਂਟ ਗਾਈਡ',
'VG_Intro' => 'ਇੱਕ ਵੇਰੀਏਬਲ ਉਤਪਾਦ ਕਈ ਵੇਰੀਐਂਟਾਂ ਵਜੋਂ ਵੇਚਿਆ ਜਾਂਦਾ ਹੈ। ਉਹਨਾਂ ਨੂੰ ਵਿਕਲਪਾਂ ਤੋਂ (ਸਿਫ਼ਾਰਸ਼ੀ) ਜਾਂ ਨਾਵਾਂ ਦੀ ਸਧਾਰਨ ਸੂਚੀ ਵਜੋਂ ਬਣਾਓ। ਹਰ ਵੇਰੀਐਂਟ ਦਾ ਆਪਣਾ ਕੋਡ, ਕੀਮਤਾਂ, ਚਿੱਤਰ ਅਤੇ ਸਟਾਕ ਹੁੰਦਾ ਹੈ।',
'VG_Options_Title' => 'ਵਿਕਲਪ ਮੋਡ (ਰੰਗ, ਆਕਾਰ...)',
'VG_Opt_Step1' => 'ਕਾਰਡ ਹੈਡਰ ਵਿੱਚ ਸਵਿੱਚ ਨੂੰ "ਵਿਕਲਪ" \'ਤੇ ਰੱਖੋ।',
'VG_Opt_Step2' => 'ਰੰਗ ਜਾਂ ਆਕਾਰ ਵਰਗਾ ਵਿਕਲਪ ਨਾਮ ਟਾਈਪ ਕਰੋ, ਜਾਂ ਸੁਝਾਵਾਂ ਵਿੱਚੋਂ ਇੱਕ ਚੁਣੋ।',
'VG_Opt_Step3' => 'ਇੱਕ ਮੁੱਲ ਟਾਈਪ ਕਰੋ (ਉਦਾਹਰਨ ਲਈ ਲਾਲ) ਅਤੇ Enter ਦਬਾਓ। ਹਰ ਮੁੱਲ ਲਈ ਦੁਹਰਾਓ; ਕੌਮਾ ਵੀ ਮੁੱਲਾਂ ਨੂੰ ਵੱਖ ਕਰਦਾ ਹੈ। ਕਿਸੇ ਮੁੱਲ ਨੂੰ ਹਟਾਉਣ ਲਈ ਉਸਦੇ x \'ਤੇ ਕਲਿੱਕ ਕਰੋ।',
'VG_Opt_Step4' => 'ਦੂਜੇ ਜਾਂ ਤੀਜੇ ਵਿਕਲਪ ਲਈ "ਵਿਕਲਪ ਸ਼ਾਮਲ ਕਰੋ" \'ਤੇ ਕਲਿੱਕ ਕਰੋ (ਵੱਧ ਤੋਂ ਵੱਧ 3 ਵਿਕਲਪ)।',
'VG_Opt_Step5' => '"ਵੇਰੀਐਂਟ ਬਣਾਓ" \'ਤੇ ਕਲਿੱਕ ਕਰੋ। ਹਰ ਸੁਮੇਲ ਲਈ ਇੱਕ ਕਤਾਰ ਬਣਦੀ ਹੈ ਅਤੇ ਇਸਦਾ ਨਾਮ ਆਪਣੇ ਆਪ ਬਣਦਾ ਹੈ, ਉਦਾਹਰਨ ਲਈ "Red / S"।',
'VG_Opt_Step6' => 'ਹਰ ਕਤਾਰ \'ਤੇ ਲਾਗਤ ਅਤੇ ਕੀਮਤ ਦਰਜ ਕਰੋ, ਜਾਂ "ਸਭ \'ਤੇ ਲਾਗੂ ਕਰੋ" ਵਿੱਚ ਇੱਕ ਮੁੱਲ ਟਾਈਪ ਕਰੋ ਅਤੇ ਇਸਨੂੰ ਹਰ ਕਤਾਰ ਵਿੱਚ ਕਾਪੀ ਕਰਨ ਲਈ ਲਾਗਤ ਜਾਂ ਕੀਮਤ \'ਤੇ ਕਲਿੱਕ ਕਰੋ।',
'VG_Opt_Step7' => 'ਕੋਡ ਤੁਹਾਡੇ ਲਈ ਬਣਾਏ ਜਾਂਦੇ ਹਨ। ਆਪਣਾ ਟਾਈਪ ਕਰੋ ਜਾਂ ਹੋਰ ਬਣਾਉਣ ਲਈ ਰਿਫ੍ਰੈਸ਼ ਆਈਕਨ \'ਤੇ ਕਲਿੱਕ ਕਰੋ।',
'VG_Opt_Step8' => 'ਵਿਕਲਪਿਕ: ਕਿਸੇ ਵਿਕਲਪ \'ਤੇ "ਰੰਗ ਸਵੈਚ" ਟਿੱਕ ਕਰੋ ਅਤੇ ਹਰ ਮੁੱਲ ਲਈ ਇੱਕ ਰੰਗ ਚੁਣੋ; ਸਟੋਰ ਇਸਨੂੰ ਰੰਗਦਾਰ ਬਿੰਦੀ ਵਜੋਂ ਦਿਖਾਉਂਦਾ ਹੈ।',
'VG_Rows_Title' => 'ਵੇਰੀਐਂਟ ਕਤਾਰਾਂ',
'VG_Rows_Text' => 'ਹਰ ਕਤਾਰ ਵਿੱਚ ਚਿੱਤਰ, ਕੋਡ, ਬਾਰਕੋਡ, ਲਾਗਤ, ਕੀਮਤ, ਥੋਕ ਕੀਮਤ ਅਤੇ ਘੱਟੋ-ਘੱਟ ਵਿਕਰੀ ਕੀਮਤ ਹੁੰਦੀ ਹੈ। ਉਤਪਾਦ ਬਣਾਉਂਦੇ ਸਮੇਂ ਤੁਸੀਂ ਹਰ ਵੇਰੀਐਂਟ ਲਈ ਪ੍ਰਤੀ ਵੇਅਰਹਾਊਸ ਸ਼ੁਰੂਆਤੀ ਸਟਾਕ ਵੀ ਦਰਜ ਕਰ ਸਕਦੇ ਹੋ। "ਅਧੂਰਾ" ਟੈਗ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਕਤਾਰ ਵਿੱਚ ਕਿਸੇ ਵਿਕਲਪ ਦਾ ਮੁੱਲ ਮੌਜੂਦ ਨਹੀਂ ਹੈ।',
'VG_List_Title' => 'ਸਧਾਰਨ ਸੂਚੀ ਮੋਡ',
'VG_List_Text' => 'ਕਤਾਰ ਜੋੜਨ ਲਈ ਵੇਰੀਐਂਟ ਦਾ ਨਾਮ ਟਾਈਪ ਕਰੋ ਅਤੇ Enter ਦਬਾਓ (ਜਾਂ ਸ਼ਾਮਲ ਕਰੋ \'ਤੇ ਕਲਿੱਕ ਕਰੋ), ਫਿਰ ਇਸਦਾ ਕੋਡ ਅਤੇ ਕੀਮਤਾਂ ਭਰੋ। ਇਹ ਕਲਾਸਿਕ ਵਿਵਹਾਰ ਹੈ ਅਤੇ ਮੌਜੂਦਾ ਉਤਪਾਦਾਂ ਲਈ ਉਪਲਬਧ ਰਹਿੰਦਾ ਹੈ।',
'VG_Edit_Title' => 'ਬਾਅਦ ਵਿੱਚ ਸੰਪਾਦਨ',
'VG_Edit_1' => 'ਇੱਕ ਮੁੱਲ ਸ਼ਾਮਲ ਕਰੋ ਅਤੇ "ਵੇਰੀਐਂਟ ਬਣਾਓ" \'ਤੇ ਕਲਿੱਕ ਕਰੋ: ਸਿਰਫ਼ ਗੁੰਮ ਸੁਮੇਲ ਸ਼ਾਮਲ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਮੌਜੂਦਾ ਕਤਾਰਾਂ ਆਪਣੇ ਕੋਡ, ਕੀਮਤਾਂ ਅਤੇ ਇਤਿਹਾਸ ਬਰਕਰਾਰ ਰੱਖਦੀਆਂ ਹਨ।',
'VG_Edit_2' => 'ਕੋਈ ਮੁੱਲ ਜਾਂ ਵਿਕਲਪ ਹਟਾਉਣ ਨਾਲ ਉਸਨੂੰ ਵਰਤਣ ਵਾਲੀਆਂ ਕਤਾਰਾਂ ਹਟ ਜਾਂਦੀਆਂ ਹਨ। ਪਹਿਲਾਂ ਸੇਵ ਕੀਤੀਆਂ ਕਤਾਰਾਂ ਪੁਸ਼ਟੀ ਤੋਂ ਬਾਅਦ, ਉਤਪਾਦ ਸੇਵ ਕਰਨ \'ਤੇ ਮਿਟਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ।',
'VG_Edit_3' => 'ਜਿਸ ਵੇਰੀਐਂਟ ਵਿੱਚ ਅਜੇ ਵੀ ਸਟਾਕ ਹੈ ਉਸਨੂੰ ਹਟਾਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ। ਪਹਿਲਾਂ ਇਸਦਾ ਸਟਾਕ ਸਮਾਯੋਜਿਤ ਜਾਂ ਟ੍ਰਾਂਸਫਰ ਕਰੋ।',
'VG_Edit_4' => '"ਸਧਾਰਨ ਸੂਚੀ" \'ਤੇ ਜਾਣ ਨਾਲ ਕਤਾਰਾਂ ਅਤੇ ਉਹਨਾਂ ਦੇ ਨਾਮ ਰਹਿੰਦੇ ਹਨ ਪਰ ਵਿਕਲਪ ਪਰਿਭਾਸ਼ਾਵਾਂ ਹਟ ਜਾਂਦੀਆਂ ਹਨ।',
'VG_Store_Title' => 'ਆਨਲਾਈਨ ਸਟੋਰ \'ਤੇ',
'VG_Store_Text' => 'ਗਾਹਕ ਹਰ ਵਿਕਲਪ ਲਈ ਇੱਕ ਮੁੱਲ ਚੁਣਦੇ ਹਨ, ਉਦਾਹਰਨ ਲਈ ਰੰਗ ਫਿਰ ਆਕਾਰ। ਜੋ ਸੁਮੇਲ ਮੌਜੂਦ ਨਹੀਂ ਉਹ ਅਯੋਗ ਹੁੰਦੇ ਹਨ ਅਤੇ ਸਟਾਕ ਖਤਮ ਵਾਲੇ ਕੱਟੇ ਹੋਏ ਦਿਖਾਏ ਜਾਂਦੇ ਹਨ। ਚੁਣਿਆ ਵੇਰੀਐਂਟ ਹੀ ਕਾਰਟ ਵਿੱਚ ਜਾਂਦਾ ਹੈ।',
'Choose_Source' => 'ਸਰੋਤ ਚੁਣੋ',
'Portal_Request' => 'ਪੋਰਟਲ ਬੇਨਤੀ',
'Portal_Quotation_Requests' => 'ਪੋਰਟਲ ਕੋਟੇਸ਼ਨ ਬੇਨਤੀਆਂ',
'Warehouse_Invoice_Address_Help' => 'ਇਸ ਵੇਅਰਹਾਊਸ ਦੁਆਰਾ ਜਾਰੀ ਇਨਵੌਇਸਾਂ \'ਤੇ ਪ੍ਰਿੰਟ ਹੋਣ ਵਾਲਾ ਗਲੀ ਦਾ ਪਤਾ। ਸੈਟਿੰਗਾਂ ਵਾਲਾ ਕੰਪਨੀ ਪਤਾ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।',
'Warehouse_Logo_Help' => 'ਇਸ ਵੇਅਰਹਾਊਸ ਦੇ ਇਨਵੌਇਸਾਂ ਅਤੇ POS ਰਸੀਦਾਂ \'ਤੇ ਪ੍ਰਿੰਟ ਹੋਣ ਵਾਲਾ ਲੋਗੋ। ਕੰਪਨੀ ਲੋਗੋ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।',
'Warehouse_Invoice_Footer_Help' => 'ਇਸ ਵੇਅਰਹਾਊਸ ਦੁਆਰਾ ਜਾਰੀ ਇਨਵੌਇਸਾਂ ਦੇ ਹੇਠਾਂ ਪ੍ਰਿੰਟ ਹੋਣ ਵਾਲਾ ਵਾਧੂ ਨੋਟ।',
'Issued_By' => 'ਜਾਰੀ ਕਰਤਾ',
'Enable_Warehouse_Letterhead' => 'ਇਨਵੌਇਸਾਂ \'ਤੇ ਵੇਅਰਹਾਊਸ ਲੈਟਰਹੈੱਡ',
'Enable_Warehouse_Letterhead_Hint' => 'ਇਨਵੌਇਸਾਂ, POS ਰਸੀਦਾਂ ਅਤੇ ਜਨਤਕ ਇਨਵੌਇਸ ਪੰਨੇ \'ਤੇ ਜਾਰੀ ਕਰਨ ਵਾਲਾ ਵੇਅਰਹਾਊਸ ਪ੍ਰਿੰਟ ਕਰੋ: ਇਸਦਾ ਨਾਮ ਕੰਪਨੀ ਦੇ ਨਾਮ ਦੀ ਥਾਂ ਲੈਂਦਾ ਹੈ, ਅਤੇ ਇਸਦਾ ਪਤਾ, ਫ਼ੋਨ, ਈਮੇਲ, ਲੋਗੋ ਅਤੇ ਫੁੱਟਰ ਨੋਟ ਕੰਪਨੀ ਵਾਲਿਆਂ ਦੀ ਥਾਂ ਲੈਂਦੇ ਹਨ। ਵੇਅਰਹਾਊਸ \'ਤੇ ਖਾਲੀ ਛੱਡਿਆ ਕੋਈ ਵੀ ਖੇਤਰ ਗਲੋਬਲ ਕੰਪਨੀ ਸੈਟਿੰਗਾਂ ਵਰਤਦਾ ਹੈ।',
'Warehouse_Letterhead_Receipt_Notice' => 'ਵੇਅਰਹਾਊਸ ਲੈਟਰਹੈੱਡ ਚਾਲੂ ਹੈ: ਅਸਲ ਰਸੀਦ \'ਤੇ ਪ੍ਰਿੰਟ ਹੋਣ ਵਾਲਾ ਸਟੋਰ ਨਾਮ, ਪਤਾ ਅਤੇ ਫ਼ੋਨ ਵਿਕਰੀ ਜਾਰੀ ਕਰਨ ਵਾਲੇ ਵੇਅਰਹਾਊਸ ਤੋਂ ਆਉਂਦੇ ਹਨ, ਅਤੇ ਇਸਦਾ ਫੁੱਟਰ ਨੋਟ ਗਾਹਕ ਨੋਟ ਦੇ ਹੇਠਾਂ ਜੋੜਿਆ ਜਾਂਦਾ ਹੈ।',
'Warehouse_Letterhead_Receipt_Demo' => 'ਸ਼ਾਖਾ ਫੁੱਟਰ ਨੋਟ — ਵੇਅਰਹਾਊਸ ਹੇਠ ਹਰ ਵੇਅਰਹਾਊਸ ਲਈ ਸੈੱਟ ਕਰੋ।',
