'Shopify_Link_Card_Hint' => 'ਇਸ ਉਤਪਾਦ ਨੂੰ ਤੁਹਾਡੀ ਦੁਕਾਨ ਵਿੱਚ ਪਹਿਲਾਂ ਤੋਂ ਮੌਜੂਦ ਲਿਸਟਿੰਗ ਨਾਲ ਜੋੜੋ, ਤਾਂ ਜੋ ਸਿੰਕ ਦੂਜੀ ਬਣਾਉਣ ਦੀ ਬਜਾਏ ਉਸਨੂੰ ਅੱਪਡੇਟ ਕਰੇ।',
