'Set_Demo_Intro_Desc' => 'ਪਿਛਲੇ 90 ਦਿਨਾਂ ਵਿੱਚ ਫੈਲੇ ਉਤਪਾਦ, ਗਾਹਕ, ਸਪਲਾਇਰ, ਵਿਕਰੀਆਂ, ਖਰੀਦਾਂ, ਕੋਟੇਸ਼ਨ ਅਤੇ ਖਰਚੇ — ਡੈਸ਼ਬੋਰਡ ਅਤੇ ਰਿਪੋਰਟਾਂ ਦੀ ਪੜਚੋਲ ਲਈ ਆਦਰਸ਼। ਬਣਾਇਆ ਸਭ ਕੁਝ ਟੈਗ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਇੱਕ ਕਲਿੱਕ ਵਿੱਚ ਹਟਾਇਆ ਜਾ ਸਕਦਾ ਹੈ।',
