'Set_Env_Not_Writable_Desc' => 'ਵੈੱਬ ਸਰਵਰ .env ਵਿੱਚ ਨਹੀਂ ਲਿਖ ਸਕਦਾ, ਇਸ ਲਈ ਇੱਥੇ ਤਬਦੀਲੀਆਂ ਸੇਵ ਨਹੀਂ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ। ਫ਼ਾਈਲ ਅਨੁਮਤੀਆਂ ਠੀਕ ਕਰੋ, ਫਿਰ ਇਹ ਪੰਨਾ ਮੁੜ ਲੋਡ ਕਰੋ।',
'Set_Env_Written_Directly' => 'ਤਬਦੀਲੀਆਂ ਸਿੱਧੀਆਂ .env ਫ਼ਾਈਲ ਵਿੱਚ ਲਿਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ',
'Set_Env_Written_Directly_Desc' => 'ਸਿਰਫ਼ ਇੱਥੇ ਸੂਚੀਬੱਧ ਕੀਆਂ ਹੀ ਸੰਪਾਦਿਤ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ। ਹਰ ਸੇਵ ਤੋਂ ਪਹਿਲਾਂ ਪਿਛਲੀ .env ਦਾ ਬੈਕਅੱਪ {path} ਵਿੱਚ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ। ਕੀ ਹਟਾਉਣ ਅਤੇ ਬਿਲਟ-ਇਨ ਡਿਫੌਲਟ ਵਰਤਣ ਲਈ ਖੇਤਰ ਖਾਲੀ ਛੱਡੋ।',
