'Upd_Manual_Step_Backup_Files' => 'ਅੱਪਡੇਟ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੀਆਂ ਫ਼ਾਈਲਾਂ ਦਾ ਬੈਕਅੱਪ ਲਓ।',
'Upd_Manual_Step_Download' => 'ਆਪਣੇ CodeCanyon ਖਾਤੇ ਤੋਂ ਨਵੀਨਤਮ ਸੰਸਕਰਣ ਡਾਊਨਲੋਡ ਕਰੋ ਅਤੇ ਇਸਨੂੰ ਐਕਸਟ੍ਰੈਕਟ ਕਰੋ।',
'Upd_Manual_Step_Remove' => 'ਪਿਛਲੀਆਂ ਫ਼ਾਈਲਾਂ ਹਟਾਓ, {except}:',
'Upd_Except' => 'ਸਿਵਾਏ',
'Upd_File_Label' => 'ਫ਼ਾਈਲ: {name}',
'Upd_Folder_Label' => 'ਫੋਲਡਰ: {name}',
'Upd_Manual_Step_Reupload' => 'ਨਵੇਂ ਅੱਪਡੇਟ ਦੀਆਂ ਫ਼ਾਈਲਾਂ ਅਤੇ ਫੋਲਡਰ ਦੁਬਾਰਾ ਅੱਪਲੋਡ ਕਰੋ, {except} ਉੱਪਰ ਦਿੱਤੇ ਉਹੀ ਤਿੰਨ ਪਾਥ।',
'Upd_Manual_Step_Visit' => 'ਆਪਣਾ ਡਾਟਾਬੇਸ ਅੱਪਡੇਟ ਕਰਨ ਲਈ {url} \'ਤੇ ਜਾਓ।',
'Upd_Manual_Step_Clear_Cache' => 'ਆਪਣੇ ਬ੍ਰਾਊਜ਼ਰ ਦਾ ਕੈਸ਼ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਾਫ਼ ਕਰੋ।',
'Upd_Manual_Step_Done' => 'ਤੁਸੀਂ ਪੂਰਾ ਕਰ ਲਿਆ! ਅੱਪਡੇਟ ਕੀਤੀ ਐਪਲੀਕੇਸ਼ਨ ਦਾ ਆਨੰਦ ਲਓ।',
'Upd_Note_Blank_Pages' => 'ਨੋਟ: ਜੇ ਕੋਈ ਪੰਨਾ ਲੋਡ ਨਹੀਂ ਹੋ ਰਿਹਾ ਜਾਂ ਖਾਲੀ ਹੈ, ਤਾਂ ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਸੀਂ ਆਪਣੇ ਬ੍ਰਾਊਜ਼ਰ ਦਾ ਕੈਸ਼ ਸਾਫ਼ ਕੀਤਾ ਹੈ।',
'Upd_Guide_Before_Title' => '1. ਅੱਪਡੇਟ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ',
'Upd_Guide_Before_Download' => 'ਆਪਣੇ CodeCanyon ਖਾਤੇ ({path}) ਤੋਂ ਐਪਲੀਕੇਸ਼ਨ ਦਾ {package} ਡਾਊਨਲੋਡ ਕਰੋ। ਇਸਨੂੰ ਐਕਸਟ੍ਰੈਕਟ ਨਾ ਕਰੋ — ਅੱਪਡੇਟਰ ਨੂੰ ZIP ਬਿਲਕੁਲ ਉਸੇ ਤਰ੍ਹਾਂ ਚਾਹੀਦੀ ਹੈ ਜਿਵੇਂ ਡਾਊਨਲੋਡ ਕੀਤੀ ਗਈ।',
'Upd_Latest_Full_Zip' => 'ਨਵੀਨਤਮ ਪੂਰਾ ZIP ਪੈਕੇਜ',
'Upd_Guide_Before_Admin' => 'ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਸੀਂ {perm} ਅਨੁਮਤੀ ਵਾਲੇ ਪ੍ਰਸ਼ਾਸਕ ਵਜੋਂ ਲੌਗਇਨ ਹੋ। ਕੋਈ ਹੋਰ ਅੱਪਡੇਟਰ ਨੂੰ ਨਾ ਦੇਖ ਸਕਦਾ ਹੈ ਨਾ ਚਲਾ ਸਕਦਾ ਹੈ।',
'Upd_Guide_Before_Quiet' => 'ਸ਼ਾਂਤ ਸਮਾਂ ਚੁਣੋ: ਅੱਪਡੇਟ ਦੌਰਾਨ ਐਪਲੀਕੇਸ਼ਨ ਥੋੜ੍ਹੇ ਸਮੇਂ ਲਈ ਮੇਨਟੇਨੈਂਸ ਮੋਡ ਵਿੱਚ ਚਲੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਹੋਰ ਵਰਤੋਂਕਾਰ ਬਾਹਰ ਹੋ ਜਾਂਦੇ ਹਨ।',
'Upd_Guide_Before_No_Manual' => 'ਤੁਹਾਨੂੰ ਹੱਥੀਂ ਬੈਕਅੱਪ ਲੈਣ, ਫ਼ਾਈਲਾਂ ਐਕਸਟ੍ਰੈਕਟ ਕਰਨ, ਕਮਾਂਡਾਂ ਚਲਾਉਣ, ਸੰਰਚਨਾ ਫ਼ਾਈਲਾਂ ਸੰਪਾਦਿਤ ਕਰਨ, ਜਾਂ ਡਾਟਾਬੇਸ ਨੂੰ ਛੂਹਣ ਦੀ ਲੋੜ {not} ਹੈ — ਅੱਪਡੇਟਰ ਇਹ ਸਭ ਆਪਣੇ ਆਪ ਕਰਦਾ ਹੈ। (ਬੇਸ਼ੱਕ, ਇੱਕ ਵਾਧੂ ਹੱਥੀਂ ਬੈਕਅੱਪ ਕਦੇ ਨੁਕਸਾਨ ਨਹੀਂ ਕਰਦਾ।)',
'Upd_Not' => 'ਨਹੀਂ',
'Upd_Guide_Code_Overwritten' => 'ਜੇ ਤੁਸੀਂ ਐਪਲੀਕੇਸ਼ਨ ਕੋਡ ਹੱਥੀਂ ਸੋਧਿਆ ਹੈ, ਤਾਂ ਤੁਹਾਡੀਆਂ ਤਬਦੀਲੀਆਂ ਅੱਪਡੇਟ ਦੁਆਰਾ ਓਵਰਰਾਈਟ ਹੋ ਜਾਣਗੀਆਂ। ਤੁਹਾਡਾ ਡਾਟਾ, ਅੱਪਲੋਡ, ਸੈਟਿੰਗਾਂ ਅਤੇ .env ਹਮੇਸ਼ਾ ਸੁਰੱਖਿਅਤ ਰਹਿੰਦੇ ਹਨ।',
'Upd_Guide_Running_Title' => '2. ਅੱਪਡੇਟ ਚਲਾਉਣਾ',
'Upd_Guide_Run_Open' => '{path} (ਇਹ ਪੰਨਾ) ਖੋਲ੍ਹੋ ਅਤੇ {tab} ਟੈਬ \'ਤੇ ਰਹੋ।',
'Upd_Guide_Run_Upload' => '{upload}: ਡਾਊਨਲੋਡ ਕੀਤੇ ਪੈਕੇਜ ਨੂੰ ਅੱਪਲੋਡ ਬਾਕਸ ਵਿੱਚ ਕਲਿੱਕ ਕਰਕੇ ਜਾਂ ਖਿੱਚ ਕੇ ਪਾਓ। ਵੱਡੀਆਂ ਫ਼ਾਈਲਾਂ ਛੋਟੇ ਟੁਕੜਿਆਂ ਵਿੱਚ ਅੱਪਲੋਡ ਹੁੰਦੀਆਂ ਹਨ, ਇਸ ਲਈ ਇਹ ਘੱਟ ਅੱਪਲੋਡ ਸੀਮਾ ਵਾਲੀ ਸ਼ੇਅਰਡ ਹੋਸਟਿੰਗ \'ਤੇ ਵੀ ਕੰਮ ਕਰਦਾ ਹੈ। ਇੱਕ ਚੈੱਕਸਮ ਖਰਾਬ ਜਾਂ ਅਧੂਰੇ ਅੱਪਲੋਡਾਂ ਤੋਂ ਬਚਾਉਂਦਾ ਹੈ।',
'Upd_Upload_The_Zip' => 'ZIP ਅੱਪਲੋਡ ਕਰੋ',
'Upd_Guide_Run_Validation' => 'ਅੱਪਲੋਡ ਤੋਂ ਬਾਅਦ {auto} (ਤੁਸੀਂ ਇਸਨੂੰ {button} ਬਟਨ ਨਾਲ ਦੁਬਾਰਾ ਚਲਾ ਸਕਦੇ ਹੋ)। ਸਿਸਟਮ ਇਹ ਜਾਂਚਦਾ ਹੈ: ZIP ਅਖੰਡਤਾ, ਪੈਕੇਜ ਢਾਂਚਾ ਅਤੇ ਸੰਪੂਰਨਤਾ, ਸੰਸਕਰਣ ਅਨੁਕੂਲਤਾ (ਡਾਊਨਗ੍ਰੇਡ ਅਸਵੀਕਾਰ ਕੀਤੇ ਜਾਂਦੇ ਹਨ), ਲੋੜੀਂਦਾ PHP ਸੰਸਕਰਣ ਅਤੇ ਐਕਸਟੈਂਸ਼ਨ, ਫ਼ਾਈਲ ਅਨੁਮਤੀਆਂ, ਖਾਲੀ ਡਿਸਕ ਸਪੇਸ, ਡਾਟਾਬੇਸ ਕਨੈਕਸ਼ਨ, ਸੰਰਚਨਾ, ਅਤੇ ਇਹ ਕਿ ਕੋਈ ਹੋਰ ਅੱਪਡੇਟ ਨਹੀਂ ਚੱਲ ਰਿਹਾ।',
'Upd_Validation_Runs_Automatically' => 'ਪ੍ਰਮਾਣਿਕਤਾ ਜਾਂਚ ਆਪਣੇ ਆਪ ਚੱਲਦੀ ਹੈ',
'Upd_Guide_Run_Review' => '{panel} ਪੈਨਲ ਦੀ ਸਮੀਖਿਆ ਕਰੋ। {button} ਬਟਨ ਸਿਰਫ਼ ਉਦੋਂ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ ਜਦੋਂ ਹਰ ਗੰਭੀਰ ਜਾਂਚ ਪਾਸ ਹੋ ਜਾਵੇ। ਜੇ ਕੋਈ ਜਾਂਚ ਅਸਫਲ ਹੁੰਦੀ ਹੈ, ਤਾਂ ਸੁਨੇਹਾ ਤੁਹਾਨੂੰ ਬਿਲਕੁਲ ਦੱਸਦਾ ਹੈ ਕਿ ਕੀ ਠੀਕ ਕਰਨਾ ਹੈ।',
'Upd_Guide_Run_Click' => '{button} \'ਤੇ ਕਲਿੱਕ ਕਰੋ ਅਤੇ ਪੁਸ਼ਟੀ ਕਰੋ। ਫਿਰ ਬੱਸ {keep} ਅਤੇ ਪ੍ਰਗਤੀ ਪੱਟੀ ਦੇਖੋ। ਸਿਸਟਮ ਕ੍ਰਮਵਾਰ ਇਹ ਕਰਦਾ ਹੈ:',
'Upd_Keep_Page_Open' => 'ਇਹ ਪੰਨਾ ਖੁੱਲ੍ਹਾ ਰੱਖੋ',
'Upd_Guide_Phase_Backup' => '{label} — ਪੂਰਾ ਡਾਟਾਬੇਸ ਡੰਪ, ਅੱਪਡੇਟ ਦੁਆਰਾ ਬਦਲੀ ਜਾ ਸਕਣ ਵਾਲੀ ਹਰ ਐਪਲੀਕੇਸ਼ਨ ਫ਼ਾਈਲ ਦੀ ZIP, ਅਤੇ {env} ਦੀ ਕਾਪੀ ਬਣਾਏ ਜਾਂਦੇ ਹਨ ਅਤੇ {verified} ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਤੁਹਾਡੇ ਅੱਪਲੋਡ ({images}) ਅਤੇ {storage} ਨੂੰ ਅੱਪਡੇਟ ਕਦੇ ਨਹੀਂ ਛੂੰਹਦਾ, ਇਸ ਲਈ ਉਹਨਾਂ ਨੂੰ ਆਰਕਾਈਵ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ। ਜੇ ਬੈਕਅੱਪ ਨਹੀਂ ਬਣ ਸਕਦਾ, ਤਾਂ ਅੱਪਡੇਟ ਇੱਥੇ ਹੀ ਰੁਕ ਜਾਂਦਾ ਹੈ ਅਤੇ ਕੁਝ ਨਹੀਂ ਬਦਲਦਾ।',
'Upd_Verified' => 'ਪ੍ਰਮਾਣਿਤ',
'Upd_Guide_Phase_Prepare' => '{label} — ਨਵਾਂ ਸੰਸਕਰਣ ਸਟੇਜਿੰਗ ਖੇਤਰ ਵਿੱਚ ਐਕਸਟ੍ਰੈਕਟ ਹੁੰਦਾ ਹੈ ਅਤੇ ਦੁਬਾਰਾ ਪ੍ਰਮਾਣਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਲਾਈਵ ਐਪਲੀਕੇਸ਼ਨ ਅਜੇ ਵੀ ਅਛੂਤੀ ਹੈ।',
'Upd_Guide_Phase_Maintenance' => '{label} — ਮੇਨਟੇਨੈਂਸ ਮੋਡ ਯੋਗ ਹੁੰਦਾ ਹੈ; ਵਿਜ਼ਿਟਰਾਂ ਨੂੰ ਇੱਕ ਦੋਸਤਾਨਾ "ਅਸੀਂ ਜਲਦੀ ਵਾਪਸ ਆਵਾਂਗੇ" ਸਕ੍ਰੀਨ ਦਿਖਾਈ ਦਿੰਦੀ ਹੈ।',
'Upd_Guide_Phase_Files' => '{label} — ਨਵੀਆਂ ਫ਼ਾਈਲਾਂ ਲਗਭਗ ਤੁਰੰਤ ਬਦਲ ਦਿੱਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ; ਪੁਰਾਣੀਆਂ ਫ਼ਾਈਲਾਂ ਰੋਲਬੈਕ ਲਈ ਵੱਖ ਰੱਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਸੁਰੱਖਿਅਤ ਪਾਥ ({env}, {storage}, {images}) ਕਦੇ ਨਹੀਂ ਬਦਲੇ ਜਾਂਦੇ।',
'Upd_Guide_Phase_Database' => '{label} — ਮਾਈਗ੍ਰੇਸ਼ਨ ਚੱਲਦੇ ਹਨ, ਫਿਰ ਅਨੁਮਤੀਆਂ, ਅਨੁਵਾਦ ਅਤੇ ਟੈਮਪਲੇਟ ਤਾਜ਼ਾ ਕੀਤੇ ਜਾਂਦੇ ਹਨ।',
'Upd_Guide_Phase_Cache' => '{label} — ਸਾਰੇ ਕੈਸ਼ ਸਾਫ਼ ਕਰਕੇ ਦੁਬਾਰਾ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।',
'Upd_Guide_Phase_Verify' => '{label} — ਸਿਹਤ ਜਾਂਚਾਂ ਪੁਸ਼ਟੀ ਕਰਦੀਆਂ ਹਨ ਕਿ ਨਵਾਂ ਸੰਸਕਰਣ ਚਾਲੂ ਹੁੰਦਾ ਹੈ, ਡਾਟਾਬੇਸ ਕੰਮ ਕਰਦਾ ਹੈ, ਸਾਰੇ ਮਾਈਗ੍ਰੇਸ਼ਨ ਚੱਲੇ, ਅਤੇ ਸੰਰਚਨਾ ਵੈਧ ਹੈ।',
'Upd_Guide_Phase_Done' => '{label} — ਮੇਨਟੇਨੈਂਸ ਮੋਡ ਹਟਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਅਸਥਾਈ ਫ਼ਾਈਲਾਂ ਸਾਫ਼ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।',
'Upd_Guide_Run_Success' => 'ਜਦੋਂ ਤੁਸੀਂ {success} ਦੇਖੋ, ਤਾਂ {reload} \'ਤੇ ਕਲਿੱਕ ਕਰੋ ਅਤੇ ਆਪਣਾ ਬ੍ਰਾਊਜ਼ਰ ਹਾਰਡ-ਰਿਫ੍ਰੈਸ਼ ਕਰੋ ({keys}) ਤਾਂ ਜੋ ਨਵੇਂ ਐਡਮਿਨ ਪੈਨਲ ਦੇ ਐਸੈੱਟ ਲੋਡ ਹੋਣ।',
'Upd_Update_Successful_Short' => 'ਅੱਪਡੇਟ ਸਫਲ',
'Upd_Guide_No_Internet' => 'ਅੱਪਡੇਟ ਦੌਰਾਨ ਇੰਟਰਨੈੱਟ ਕਨੈਕਸ਼ਨ ਦੀ ਲੋੜ ਨਹੀਂ — ਸਭ ਕੁਝ ਅੱਪਲੋਡ ਕੀਤੀ ZIP ਤੋਂ ਆਉਂਦਾ ਹੈ। ਕਨੈਕਸ਼ਨ ਟੁੱਟਣ ਜਾਂ ਬ੍ਰਾਊਜ਼ਰ ਬੰਦ ਕਰਨ ਨਾਲ ਅੱਪਡੇਟ ਖਰਾਬ ਨਹੀਂ ਹੁੰਦਾ: ਸਰਵਰ ਨੂੰ ਬਿਲਕੁਲ ਯਾਦ ਰਹਿੰਦਾ ਹੈ ਕਿ ਇਹ ਕਿੱਥੇ ਰੁਕਿਆ ਸੀ।',
'Upd_Guide_Wrong_Title' => '3. ਜੇ ਕੁਝ ਗਲਤ ਹੋ ਜਾਵੇ',
'Upd_Guide_Wrong_Rollback' => '{label} — ਜੇ ਫ਼ਾਈਲਾਂ ਬਦਲਣੀਆਂ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਬਾਅਦ ਕੁਝ ਵੀ ਅਸਫਲ ਹੁੰਦਾ ਹੈ (ਐਕਸਟ੍ਰੈਕਸ਼ਨ ਗਲਤੀ, ਮਾਈਗ੍ਰੇਸ਼ਨ ਅਸਫਲਤਾ, ਅਸਫਲ ਸਿਹਤ ਜਾਂਚ, ਡਿਸਕ ਭਰੀ, …), ਤਾਂ ਸਿਸਟਮ ਪ੍ਰਮਾਣਿਤ ਬੈਕਅੱਪ ਤੋਂ ਪਿਛਲੀਆਂ ਫ਼ਾਈਲਾਂ ਅਤੇ ਡਾਟਾਬੇਸ ਆਪਣੇ ਆਪ ਬਹਾਲ ਕਰਦਾ ਹੈ, ਮੇਨਟੇਨੈਂਸ ਮੋਡ ਹਟਾਉਂਦਾ ਹੈ, ਅਤੇ {message} ਦੀ ਰਿਪੋਰਟ ਕਰਦਾ ਹੈ। ਤੁਸੀਂ ਬਿਲਕੁਲ ਉੱਥੇ ਹੀ ਪਹੁੰਚ ਜਾਂਦੇ ਹੋ ਜਿੱਥੋਂ ਸ਼ੁਰੂ ਕੀਤਾ ਸੀ।',
'Upd_Automatic_Rollback' => 'ਆਟੋਮੈਟਿਕ ਰੋਲਬੈਕ',
'Upd_Failed_Previous_Restored' => 'ਅੱਪਡੇਟ ਅਸਫਲ — ਪਿਛਲਾ ਸੰਸਕਰਣ ਬਹਾਲ ਕੀਤਾ ਗਿਆ',
'Upd_Guide_Wrong_Interrupted' => '{label} (ਸਰਵਰ ਰੀਸਟਾਰਟ, ਟਾਈਮਆਊਟ, ਬੰਦ ਬ੍ਰਾਊਜ਼ਰ, ਬਿਜਲੀ ਬੰਦ) — ਜਦੋਂ ਤੁਸੀਂ ਇਹ ਪੰਨਾ ਦੁਬਾਰਾ ਖੋਲ੍ਹਦੇ ਹੋ, ਇੱਕ ਲਾਲ ਬੈਨਰ ਦੋ ਸੁਰੱਖਿਅਤ ਵਿਕਲਪ ਦਿੰਦਾ ਹੈ: {resume} (ਬਿਲਕੁਲ ਉਸੇ ਕਦਮ ਤੋਂ ਜਾਰੀ ਰੱਖਦਾ ਹੈ ਜਿੱਥੇ ਰੁਕਿਆ ਸੀ) ਜਾਂ {rollback} (ਬੈਕਅੱਪ ਤੋਂ ਪਿਛਲਾ ਸੰਸਕਰਣ ਬਹਾਲ ਕਰਦਾ ਹੈ)।',
'Upd_Interrupted_Update' => 'ਰੁਕਿਆ ਹੋਇਆ ਅੱਪਡੇਟ',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path} \'ਤੇ ਸਟੈਂਡਅਲੋਨ {console} ਵਰਤੋ। ਇਹ ਉਦੋਂ ਵੀ ਕੰਮ ਕਰਦਾ ਹੈ ਜਦੋਂ ਸਾਈਟ ਮੇਨਟੇਨੈਂਸ ਮੋਡ ਵਿੱਚ ਹੋਵੇ ਜਾਂ ਐਡਮਿਨ ਪੈਨਲ ਦੇ ਐਸੈੱਟ ਖਰਾਬ ਹੋਣ, ਅਤੇ ਉਹੀ ਜਾਰੀ ਰੱਖੋ / ਵਾਪਸ ਲਿਆਓ ਕਾਰਵਾਈਆਂ ਦਿੰਦਾ ਹੈ। ਮੇਨਟੇਨੈਂਸ ਸਕ੍ਰੀਨ ਦੇ ਹੇਠਾਂ ਇੱਕ ਛੋਟਾ "ਪ੍ਰਸ਼ਾਸਕ ਪਹੁੰਚ" ਲਿੰਕ ਵੀ ਹੈ।',
'Upd_Admin_Unreachable' => 'ਐਡਮਿਨ ਪੈਨਲ ਤੱਕ ਪਹੁੰਚ ਨਹੀਂ',
'Upd_Recovery_Console' => 'ਰਿਕਵਰੀ ਕੰਸੋਲ',
'Upd_Guide_Wrong_Locked_Out' => '{label} — ਜਦੋਂ ਅੱਪਡੇਟ ਚੱਲ ਰਿਹਾ ਹੁੰਦਾ ਹੈ, ਇਹ ਪੰਨਾ ਇੱਕ {link} ਦਿਖਾਉਂਦਾ ਹੈ। ਜੇ ਤੁਹਾਨੂੰ ਵਾਪਸ ਅੰਦਰ ਆਉਣ ਦੀ ਲੋੜ ਹੋਵੇ (ਉਦਾਹਰਨ ਲਈ ਤੁਹਾਡਾ ਸੈਸ਼ਨ ਖਤਮ ਹੋਣ ਤੋਂ ਬਾਅਦ) ਤਾਂ ਇਸਨੂੰ ਸੇਵ ਕਰੋ; ਇਹ ਤੁਹਾਨੂੰ ਮੇਨਟੇਨੈਂਸ ਸਕ੍ਰੀਨ ਤੋਂ ਲੰਘਣ ਦਿੰਦਾ ਹੈ ਤਾਂ ਜੋ ਤੁਸੀਂ ਦੁਬਾਰਾ ਲੌਗਇਨ ਕਰ ਸਕੋ।',
'Upd_Locked_Out_Maintenance' => 'ਮੇਨਟੇਨੈਂਸ ਮੋਡ ਕਾਰਨ ਬਾਹਰ ਹੋ ਗਏ',
'Upd_Bypass_Link' => 'ਬਾਈਪਾਸ ਲਿੰਕ',
'Upd_Guide_Wrong_Concurrent' => '{label} — ਉਹਨਾਂ ਨੂੰ {message} ਦਿਖਾਈ ਦੇਵੇਗਾ। ਇੱਕ ਸਮੇਂ ਸਿਰਫ਼ ਇੱਕ ਹੀ ਅੱਪਡੇਟ ਚੱਲ ਸਕਦਾ ਹੈ।',
'Upd_Another_Admin_Updating' => 'ਕੋਈ ਹੋਰ ਐਡਮਿਨ ਉਸੇ ਸਮੇਂ ਅੱਪਡੇਟ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦਾ ਹੈ',
'Upd_Guide_Backups_Title' => '4. ਬੈਕਅੱਪ ਅਤੇ ਬਹਾਲੀ',
'Upd_Guide_Backups_Created' => 'ਹਰ ਅੱਪਡੇਟ ਕਿਸੇ ਵੀ ਚੀਜ਼ ਨੂੰ ਛੂਹਣ ਤੋਂ {before} ਇੱਕ ਬੈਕਅੱਪ ਬਣਾਉਂਦਾ ਹੈ: ਅੱਪਡੇਟ ਦੁਆਰਾ ਬਦਲੀਆਂ ਜਾ ਸਕਣ ਵਾਲੀਆਂ ਸਾਰੀਆਂ ਐਪਲੀਕੇਸ਼ਨ ਫ਼ਾਈਲਾਂ, {env} ਦੀ ਕਾਪੀ, ਅਤੇ ਪੂਰਾ ਡਾਟਾਬੇਸ ਡੰਪ। ਅੱਪਲੋਡ ਅਤੇ {storage} ਅੱਪਡੇਟ ਦੁਆਰਾ ਕਦੇ ਨਹੀਂ ਬਦਲੇ ਜਾਂਦੇ ਅਤੇ ਇਸ ਲਈ ਇਸਦਾ ਹਿੱਸਾ ਨਹੀਂ ਹਨ — ਉਹਨਾਂ ਦੇ ਆਪਣੇ ਬੈਕਅੱਪ ਰੱਖੋ। ਬੈਕਅੱਪ {path} ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਵੈੱਬ ਤੋਂ ਕਦੇ ਪਹੁੰਚਯੋਗ ਨਹੀਂ ਹੁੰਦੇ।',
'Upd_Before' => 'ਪਹਿਲਾਂ',
'Upd_Guide_Backups_Panel' => '{tab} ਟੈਬ \'ਤੇ {panel} ਪੈਨਲ ਉਹਨਾਂ ਨੂੰ ਮਿਤੀ, ਸੰਸਕਰਣ ਅਤੇ ਆਕਾਰ ਨਾਲ ਸੂਚੀਬੱਧ ਕਰਦਾ ਹੈ। ਉੱਥੋਂ ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਪੂਰੇ ਬੈਕਅੱਪ ਨੂੰ {restore} ਕਰ ਸਕਦੇ ਹੋ (ਫ਼ਾਈਲਾਂ + ਡਾਟਾਬੇਸ — ਪਹਿਲਾਂ ਮੌਜੂਦਾ ਡਾਟਾਬੇਸ ਦੀ ਸੁਰੱਖਿਆ ਕਾਪੀ ਲਈ ਜਾਂਦੀ ਹੈ) ਜਾਂ ਪੁਰਾਣੇ ਬੈਕਅੱਪ {delete} ਸਕਦੇ ਹੋ।',
'Upd_Restore_Verb' => 'ਬਹਾਲ',
'Upd_Delete_Verb' => 'ਮਿਟਾ',
'Upd_Guide_Backups_Retention' => 'ਕਿੰਨੇ ਬੈਕਅੱਪ ਰੱਖਣੇ ਹਨ ਇਹ ਚੁਣਨ ਲਈ {keep} ਵਰਤੋ; ਹਰ ਸਫਲ ਅੱਪਡੇਟ ਤੋਂ ਬਾਅਦ ਪੁਰਾਣੇ ਆਪਣੇ ਆਪ ਹਟਾ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ। ਆਖਰੀ ਬਚਿਆ ਪੂਰਾ ਬੈਕਅੱਪ ਕਦੇ ਮਿਟਾਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ — ਤੁਹਾਡੇ ਕੋਲ ਹਮੇਸ਼ਾ ਵਾਪਸੀ ਦਾ ਰਾਹ ਰਹਿੰਦਾ ਹੈ।',
'Upd_Guide_Manual_Title' => '5. ਹੱਥੀਂ ਅੱਪਡੇਟ (ਬਦਲਵਾਂ ਤਰੀਕਾ)',
'Upd_Guide_Manual_Text' => 'ਜੇ ਤੁਸੀਂ ਹੱਥੀਂ ਅੱਪਡੇਟ ਕਰਨਾ ਪਸੰਦ ਕਰਦੇ ਹੋ, ਜਾਂ ਤੁਹਾਡੇ ਸਰਵਰ \'ਤੇ ਅੱਪਲੋਡਰ ਨਹੀਂ ਵਰਤਿਆ ਜਾ ਸਕਦਾ, ਤਾਂ ਇਸ ਪੰਨੇ ਦੀ {tab} ਟੈਬ \'ਤੇ ਕਦਮ-ਦਰ-ਕਦਮ ਹਦਾਇਤਾਂ ਦੀ ਪਾਲਣਾ ਕਰੋ।',
'Upd_Guide_Clear_Cache_First' => 'ਜੇ ਕਿਸੇ ਅੱਪਡੇਟ ਤੋਂ ਬਾਅਦ ਪੰਨੇ ਖਰਾਬ ਜਾਂ ਖਾਲੀ ਦਿਖਾਈ ਦੇਣ, ਤਾਂ ਪਹਿਲਾਂ ਆਪਣੇ ਬ੍ਰਾਊਜ਼ਰ ਦਾ ਕੈਸ਼ ਸਾਫ਼ ਕਰੋ — ਲਗਭਗ ਹਮੇਸ਼ਾ ਇਹੀ ਕਾਰਨ ਹੁੰਦਾ ਹੈ।',
'Upd_Restore_Backup_Confirm' => 'ਇਹ ਬੈਕਅੱਪ ਬਹਾਲ ਕਰਨਾ ਹੈ? ਮੌਜੂਦਾ ਫ਼ਾਈਲਾਂ ਅਤੇ ਮੌਜੂਦਾ ਡਾਟਾਬੇਸ ਬੈਕਅੱਪ ਨਾਲ ਬਦਲ ਦਿੱਤੇ ਜਾਣਗੇ। ਪਹਿਲਾਂ ਮੌਜੂਦਾ ਡਾਟਾਬੇਸ ਦੀ ਸੁਰੱਖਿਆ ਕਾਪੀ ਲਈ ਜਾਂਦੀ ਹੈ। (v{version} — {date})',
'Woo_Guide_Lead' => 'WooCommerce ਦੁਕਾਨ ਆਪਣੇ ਆਪ ਨੂੰ ERP ਨਾਲ ਕਿਵੇਂ ਤਾਲਮੇਲ ਵਿੱਚ ਰੱਖਦੀ ਹੈ। ਹੇਠਾਂ ਦਿੱਤੀਆਂ cron ਲਾਈਨਾਂ ਇਸ ਸਰਵਰ ਲਈ ਬਣਾਈਆਂ ਗਈਆਂ ਹਨ, ਇਸ ਲਈ ਇਹਨਾਂ ਨੂੰ ਸਿੱਧਾ ਇਸ \'ਤੇ ਕਾਪੀ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।',
'Woo_Guide_Ways_Note' => 'Shopify ਦੇ ਉਲਟ, WooCommerce ਆਪਣੇ ਆਪ ERP ਨੂੰ ਕੁਝ ਨਹੀਂ ਭੇਜਦਾ — ਇੱਥੇ ਕੋਈ webhook ਰਿਸੀਵਰ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ {in} ਆਉਣ ਵਾਲੀ ਹਰ ਚੀਜ਼ ਸ਼ਡਿਊਲ \'ਤੇ ਪਹੁੰਚਦੀ ਹੈ। ਸਿਰਫ਼ {out} ਜਾਣ ਵਾਲਾ ਸਟਾਕ ਹੀ ਤੁਰੰਤ ਹੋ ਸਕਦਾ ਹੈ।',
'Woo_In' => 'ਅੰਦਰ',
'Woo_Out' => 'ਬਾਹਰ',
'Woo_Guide_Both_Ways_Title' => 'ਦੋਵਾਂ ਦਿਸ਼ਾਵਾਂ ਲਈ ਪਹਿਲਾਂ ਇਹ ਚਾਹੀਦਾ ਹੈ',
'Woo_Api_Keys' => 'API ਕੀਆਂ',
'Woo_Guide_Api_Keys_Text' => '{path}, ਅਨੁਮਤੀ {perm}। ਕੰਜ਼ਿਊਮਰ ਕੀ ਅਤੇ ਸੀਕ੍ਰੇਟ ਨੂੰ ਸਟੋਰ URL ਦੇ ਨਾਲ {settings} ਟੈਬ ਵਿੱਚ ਕਾਪੀ ਕਰੋ — ਤੁਹਾਡੀ ਸਾਈਟ ਦਾ ਪਤਾ ਬਿਨਾਂ ਅੰਤਲੇ ਸਲੈਸ਼ ਦੇ, ਜਿਵੇਂ {example}।',
'Woo_Credentials_Saved' => 'ਕ੍ਰੈਡੈਂਸ਼ੀਅਲ ਸੇਵ ਕੀਤੇ',
'Woo_Not_Configured_Yet' => 'ਅਜੇ ਸੰਰਚਿਤ ਨਹੀਂ',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress ਐਪਲੀਕੇਸ਼ਨ ਪਾਸਵਰਡ (ਵਿਕਲਪਿਕ)',
'Woo_Guide_Wp_App_Password_Text' => 'ਸਿਰਫ਼ ਉਤਪਾਦ ਚਿੱਤਰਾਂ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ। WooCommerce API ਉਤਪਾਦ, ਸਟਾਕ, ਸ਼੍ਰੇਣੀਆਂ, ਬ੍ਰਾਂਡ, ਗਾਹਕ ਅਤੇ ਆਰਡਰ ਭੇਜਦਾ ਹੈ; WordPress API ਉਹ ਹੈ ਜੋ Media Library ਵਿੱਚ ਖੋਜਦਾ ਹੈ ਅਤੇ ਉਹ ਚਿੱਤਰ ਅੱਪਲੋਡ ਕਰਦਾ ਹੈ ਜੋ ਅਜੇ ਉੱਥੇ ਨਹੀਂ ਹੈ।',
'Woo_Guide_Wp_App_Password_Note' => 'ਅਜਿਹਾ WordPress ਵਰਤੋਂਕਾਰ ਵਰਤੋ ਜੋ ਮੀਡੀਆ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰ ਸਕੇ, ਅਤੇ ਪਾਸਵਰਡ {path} ਹੇਠ ਬਣਾਓ। ਦੋਵੇਂ ਖੇਤਰ ਖਾਲੀ ਛੱਡੋ ਅਤੇ ਸਭ ਕੁਝ ਫਿਰ ਵੀ ਸਿੰਕ ਹੁੰਦਾ ਹੈ — ਸਿਰਫ਼ ਚਿੱਤਰ ਜੋੜਨਾ ਛੱਡਿਆ ਜਾਂਦਾ ਹੈ।',
'Woo_Guide_Pick_Way_Title' => 'ਫਿਰ ਚੁਣੋ ਕਿ ਇਹ ਤਾਲਮੇਲ ਕਿਵੇਂ ਰੱਖੇ',
'Woo_Right_Away' => 'ਤੁਰੰਤ',
'Woo_Stock_Live' => 'ਸਟਾਕ ਲਾਈਵ',
'Woo_Stock_Not_Live' => 'ਸਟਾਕ ਲਾਈਵ ਨਹੀਂ',
'Woo_Guide_Realtime_Lead' => 'ਸਿਰਫ਼ ਇੱਕ ਦਿਸ਼ਾ: ERP ਤੋਂ ਬਾਹਰ ਜਾਣ ਵਾਲਾ ਸਟਾਕ ਅਤੇ ਉਤਪਾਦ। WooCommerce ਵਿੱਚ ਕੀਤੇ ਆਰਡਰ ਅਤੇ ਉਤਪਾਦ ਸੰਪਾਦਨ ਫਿਰ ਵੀ ਸ਼ਡਿਊਲ \'ਤੇ ਆਉਂਦੇ ਹਨ — ਦੂਜੀ ਟੈਬ ਦੇਖੋ।',
'Woo_Push_Stock_On_Change' => 'ਸਟਾਕ ਬਦਲਦੇ ਹੀ ਪੁਸ਼ ਕਰੋ',
'Woo_Setting_People_Miss' => 'ਇਹ ਉਹ ਸੈਟਿੰਗ ਹੈ ਜੋ ਲੋਕ ਭੁੱਲ ਜਾਂਦੇ ਹਨ',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS ਵਿਕਰੀ ਆਪਣੇ ਆਪ WooCommerce ਤੱਕ {not}। ਬੰਦ ਰਹਿਣ \'ਤੇ, ਦੁਕਾਨ ਨੂੰ ਸਿਰਫ਼ ਅਗਲੇ ਸਟਾਕ ਸਿੰਕ \'ਤੇ ਪਤਾ ਲੱਗਦਾ ਹੈ — ਡਿਫੌਲਟ ਤੌਰ \'ਤੇ ਇੱਕ ਘੰਟਾ — ਅਤੇ ਉਸ ਸਮੇਂ ਵਿੱਚ ਇਹ ਉਹ ਯੂਨਿਟ ਵੇਚ ਸਕਦੀ ਹੈ ਜੋ ਤੁਸੀਂ ਪਹਿਲਾਂ ਹੀ ਕਾਊਂਟਰ \'ਤੇ ਵੇਚ ਚੁੱਕੇ ਹੋ।',
'Woo_Does_Not' => 'ਨਹੀਂ ਪਹੁੰਚਦੀ',
'Woo_Guide_Tick_Instant' => '{settings} ਟੈਬ \'ਤੇ {option} ਟਿੱਕ ਕਰੋ। ਬੱਸ ਇਹੀ ਪੂਰਾ ਸੈੱਟਅੱਪ ਹੈ — ਕੋਈ ਵਰਕਰ ਨਹੀਂ, ਕੋਈ cron ਨਹੀਂ। ਫਿਰ ਹਰ ਵਿਕਰੀ, ਵਾਪਸੀ, ਸਮਾਯੋਜਨ, ਟ੍ਰਾਂਸਫਰ ਅਤੇ ਪ੍ਰਾਪਤ ਖਰੀਦ ਸਿਰਫ਼ ਉਹਨਾਂ ਉਤਪਾਦਾਂ ਦਾ ਪੁਸ਼ ਭੇਜਦੀ ਹੈ, ਵਿਕਰੀ ਸੇਵ ਹੋਣ ਤੋਂ ਤੁਰੰਤ ਬਾਅਦ, ਅਤੇ ਵੀਹ ਲਾਈਨਾਂ ਵਾਲੀ ਵਿਕਰੀ ਇੱਕ ਪੁਸ਼ ਲੈਂਦੀ ਹੈ, ਵੀਹ ਨਹੀਂ। ਕਾਊਂਟਰ ਕਦੇ ਇਸਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਦਾ।',
'Woo_Currently' => 'ਇਸ ਵੇਲੇ:',
'Woo_Instant_On_Text' => 'ਚਾਲੂ — ਬਦਲਣ \'ਤੇ ਸਟਾਕ ਪੁਸ਼ ਹੁੰਦਾ ਹੈ',
'Woo_Instant_Off_Text' => 'ਬੰਦ — ਸਟਾਕ ਸਿਰਫ਼ ਸ਼ਡਿਊਲ \'ਤੇ',
'Woo_Guide_Instant_Note' => 'ਸਿਰਫ਼ ਪਹਿਲਾਂ ਤੋਂ WooCommerce ਨਾਲ ਲਿੰਕ ਉਤਪਾਦ ਹੀ ਪੁਸ਼ ਹੁੰਦੇ ਹਨ — ਜੋ ਕਦੇ ਸਿੰਕ ਨਹੀਂ ਹੋਇਆ ਉਸਦਾ ਦੁਕਾਨ ਵਿੱਚ ਠੀਕ ਕਰਨ ਲਈ ਕੁਝ ਨਹੀਂ ਹੈ। ਵੇਰੀਏਬਲ ਉਤਪਾਦ ਆਪਣੇ ਮੂਲ ਉਤਪਾਦ ਰਾਹੀਂ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਕੰਬੋ ਉਦੋਂ ਦੁਬਾਰਾ ਪੁਸ਼ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਇਸਦਾ ਕੋਈ ਭਾਗ ਹਿੱਲਦਾ ਹੈ। ਬਲਕ ਕਾਰਵਾਈਆਂ (ਉਤਪਾਦ ਮਿਟਾਉਣਾ, ਵੇਅਰਹਾਊਸ ਰੀਸੈੱਟ ਕਰਨਾ) ਬਿਨਾਂ ਇਵੈਂਟ ਚਲਾਏ ਸਟਾਕ ਲਿਖਦੀਆਂ ਹਨ, ਜੋ ਘੰਟਾਵਾਰ ਸਟਾਕ ਸਿੰਕ ਵੀ ਰੱਖਣ ਦਾ ਇੱਕ ਕਾਰਨ ਹੈ।',
'Woo_Push_Products_On_Save' => 'ਉਤਪਾਦ ਸੇਵ ਹੁੰਦੇ ਹੀ ਪੁਸ਼ ਕਰੋ',
'Woo_Guide_Tick_Auto_Products' => '{settings} ਟੈਬ \'ਤੇ {option} ਟਿੱਕ ਕਰੋ ਅਤੇ Stocky ਵਿੱਚ ਬਣਾਇਆ, ਸੰਪਾਦਿਤ ਜਾਂ ਡੁਪਲੀਕੇਟ ਕੀਤਾ ਉਤਪਾਦ ਸੇਵ ਹੋਣ ਤੋਂ ਤੁਰੰਤ ਬਾਅਦ WooCommerce ਨੂੰ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ — ਵੇਰਵੇ, ਕੀਮਤ, ਵੇਰੀਐਂਟ ਅਤੇ ਚਿੱਤਰ, ਫਿਰ ਇਸਦਾ ਸਟਾਕ। ਨਵਾਂ ਉਤਪਾਦ ਰਾਤ ਦੇ ਉਤਪਾਦ ਸਿੰਕ ਦੀ ਉਡੀਕ ਕਰਨ ਦੀ ਬਜਾਏ ਤੁਰੰਤ ਦੁਕਾਨ ਵਿੱਚ ਬਣ ਜਾਂਦਾ ਹੈ।',
'Woo_On' => 'ਚਾਲੂ',
'Woo_Off' => 'ਬੰਦ',
'Woo_Guide_Bulk_Imports_Note' => 'ਬਲਕ ਆਯਾਤ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਪੁਸ਼ ਨਹੀਂ ਹੁੰਦੇ — ਆਯਾਤ ਤੋਂ ਬਾਅਦ ਉਤਪਾਦ ਸਿੰਕ ਚਲਾਓ। ਪਹਿਲਾਂ ਸ਼੍ਰੇਣੀਆਂ ਅਤੇ ਬ੍ਰਾਂਡ ਸਿੰਕ ਕਰੋ, ਤਾਂ ਜੋ ਪੁਸ਼ ਕੀਤਾ ਉਤਪਾਦ ਸਹੀ ਸ਼੍ਰੇਣੀ ਵਿੱਚ ਜਾਵੇ।',
'Woo_Nothing_Else_To_Install' => 'ਹੋਰ ਕੁਝ ਇੰਸਟਾਲ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ',
'Woo_Guide_Same_Process' => 'ਕੋਈ ਕਤਾਰ ਵਰਕਰ ਨਹੀਂ, ਕੋਈ cron ਐਂਟਰੀ ਨਹੀਂ। ਪੁਸ਼ ਉਸੇ ਪ੍ਰਕਿਰਿਆ ਵਿੱਚ ਚੱਲਦਾ ਹੈ ਜਿਸਨੇ ਵਿਕਰੀ ਸੰਭਾਲੀ, ਜਵਾਬ ਵਾਪਸ ਜਾਣ ਤੋਂ {after}, ਇਸ ਲਈ ਕਾਊਂਟਰ ਕਦੇ WooCommerce ਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਦਾ। ਪੁਸ਼ ਕਦੇ ਆਪਸ ਵਿੱਚ ਨਹੀਂ ਟਕਰਾਉਂਦੇ: ਇੱਕ ਦੇ ਚੱਲਦੇ ਸਮੇਂ ਕੀਤੀਆਂ ਤਬਦੀਲੀਆਂ ਉਸਦੀ ਉਡੀਕ ਕਰਦੀਆਂ ਹਨ ਅਤੇ ਤੁਰੰਤ ਬਾਅਦ ਜਾਂਦੀਆਂ ਹਨ।',
'Woo_After' => 'ਬਾਅਦ',
'Woo_Guide_Shop_Stops_Answering' => 'ਜਵਾਬ ਦੇਣਾ ਬੰਦ ਕਰਨ ਵਾਲੀ ਦੁਕਾਨ ਨੂੰ ਅੱਠ ਸਕਿੰਟਾਂ ਬਾਅਦ ਛੱਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਪੁਸ਼ ਪੰਜ ਮਿੰਟਾਂ ਲਈ ਰੁਕ ਜਾਂਦੇ ਹਨ ਤਾਂ ਜੋ ਹਰ ਵਿਕਰੀ ਦੁਬਾਰਾ ਇਸਦੀ ਉਡੀਕ ਨਾ ਕਰੇ; ਇਸ ਦੌਰਾਨ ਆਈਆਂ ਤਬਦੀਲੀਆਂ ਵਿਰਾਮ ਤੋਂ ਬਾਅਦ ਪਹਿਲੇ ਪੁਸ਼ ਨਾਲ ਜਾਂਦੀਆਂ ਹਨ, ਅਤੇ ਘੰਟਾਵਾਰ ਸਟਾਕ ਸਿੰਕ ਹਰ ਹਾਲ ਵਿੱਚ ਪੂਰਤੀ ਕਰ ਲੈਂਦਾ ਹੈ। ਹਰ ਵਿਰਾਮ ਲੌਗ ਟੈਬ ਵਿੱਚ ਦਰਜ ਹੁੰਦਾ ਹੈ।',
'Woo_Guide_Artisan_Exception' => 'ਇੱਕ ਅਪਵਾਦ: artisan ਕਮਾਂਡ ਦੁਆਰਾ ਕੀਤੀ ਸਟਾਕ ਤਬਦੀਲੀ ਦਾ ਕੋਈ ਜਵਾਬ ਨਹੀਂ ਹੁੰਦਾ ਜਿਸ ਤੋਂ ਬਾਅਦ ਇਹ ਜਾਵੇ, ਇਸ ਲਈ ਇਸਦੀ ਬਜਾਏ ਇਹ {queue} \'ਤੇ ਕਤਾਰ ਵਿੱਚ ਪਾਈ ਜਾਂਦੀ ਹੈ। ਉਹਨਾਂ ਨੂੰ ਵੀ ਜਲਦੀ ਭੇਜਣ ਲਈ, ਉਸ ਕਤਾਰ ਨੂੰ ਖਾਲੀ ਕਰੋ:',
'Woo_Cron_Line_Copied' => 'Cron ਲਾਈਨ ਕਾਪੀ ਕੀਤੀ',
'Woo_Command_Copied' => 'ਕਮਾਂਡ ਕਾਪੀ ਕੀਤੀ',
'Woo_Guide_Not_Woo_Queue' => 'ਜਾਣਬੁੱਝ ਕੇ {queue} ਕਤਾਰ ਨਹੀਂ: ਉਹ ਘੰਟਿਆਂ-ਲੰਬੇ ਕੈਟਾਲਾਗ ਬੈਚ ਲੈ ਕੇ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਉਹਨਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਦੇ ਪਿੱਛੇ ਕਤਾਰ ਵਿੱਚ ਪਿਆ ਤੁਰੰਤ ਪੁਸ਼ ਤੁਰੰਤ ਨਹੀਂ ਰਹੇਗਾ।',
'Woo_On_A_Schedule' => 'ਸ਼ਡਿਊਲ \'ਤੇ',
'Woo_Guide_Scheduled_Lead' => 'ਹਰ ਚੀਜ਼ ਸਮੇਂ-ਸਮੇਂ \'ਤੇ ਦੋਵਾਂ ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਦੁਬਾਰਾ ਜਾਂਚੀ ਜਾਂਦੀ ਹੈ। ਇਸੇ ਤਰ੍ਹਾਂ ਆਰਡਰ ERP ਤੱਕ ਪਹੁੰਚਦੇ ਹਨ, ਕੈਟਾਲਾਗ ਪ੍ਰਕਾਸ਼ਿਤ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਤੇਜ਼ ਰਾਹ ਤੋਂ ਛੁੱਟੀ ਕੋਈ ਵੀ ਚੀਜ਼ ਠੀਕ ਹੁੰਦੀ ਹੈ। ਹਰ ਕੰਮ ਦੀ ਆਪਣੀ cron ਐਂਟਰੀ ਹੁੰਦੀ ਹੈ, ਇਸ ਲਈ ਤੁਸੀਂ ਸਿਰਫ਼ ਉਹੀ ਚਲਾਉਂਦੇ ਹੋ ਜੋ ਤੁਸੀਂ ਚਾਹੁੰਦੇ ਹੋ।',
'Woo_Guide_Sync_Drains_Queue' => '{command} ਚੱਲਦੇ ਸਮੇਂ ਆਪਣੀ ਕਤਾਰ ਖਾਲੀ ਕਰਦਾ ਹੈ, ਇਸ ਲਈ ਇਹਨਾਂ ਲਾਈਨਾਂ ਨੂੰ ਵੱਖਰੇ ਵਰਕਰ ਦੀ ਲੋੜ ਨਹੀਂ। Windows \'ਤੇ, ਪ੍ਰੋਗਰਾਮ {program} ਅਤੇ ਉਹੀ ਆਰਗੂਮੈਂਟਾਂ ਨਾਲ Task Scheduler ਵਰਤੋ, {path} ਵਿੱਚ ਸ਼ੁਰੂ ਕੀਤਾ।',
'Woo_Or_No_Cron' => 'ਜਾਂ ਬਿਲਕੁਲ ਕੋਈ cron ਨਹੀਂ',
'Woo_Guide_No_Cron_Text' => 'ਇੱਥੇ ਹਰ ਟੈਬ ਮੰਗ \'ਤੇ ਸਿੰਕ ਕਰਦੀ ਹੈ, ਅਤੇ ਹੱਥੀਂ ਸਿੰਕ ਪੰਨਾ ਖੁੱਲ੍ਹਾ ਹੋਣ ਦੌਰਾਨ ਆਪਣੇ ਬੈਚ ਖਾਲੀ ਕਰਦਾ ਹੈ — ਇਸ ਲਈ ਇੱਕ ਛੋਟੀ ਦੁਕਾਨ ਬਿਨਾਂ ਕਿਸੇ cron ਐਂਟਰੀ ਦੇ ਚੱਲ ਸਕਦੀ ਹੈ। ਤੁਸੀਂ ਉਹ ਸਭ ਗੁਆਉਂਦੇ ਹੋ ਜੋ ਕੋਈ ਨਾ ਦੇਖ ਰਿਹਾ ਹੋਵੇ ਤਾਂ ਹੁੰਦਾ ਹੈ: ਆਰਡਰ ਸਿਰਫ਼ ਉਦੋਂ ਆਉਂਦੇ ਹਨ ਜਦੋਂ ਕੋਈ ਬਟਨ ਦਬਾਉਂਦਾ ਹੈ।',
'Woo_Commands_Worth_Knowing' => 'ਜਾਣਨਯੋਗ ਕਮਾਂਡਾਂ',
'Woo_Worth_Knowing' => 'ਜਾਣਨਯੋਗ',
'Woo_Guide_Changing_Url_Clears' => 'ਸਟੋਰ URL ਜਾਂ API ਕੀਆਂ ਬਦਲਣ ਨਾਲ ਹਰ ਮੈਪਿੰਗ ਸਾਫ਼ ਹੋ ਜਾਂਦੀ ਹੈ — ਉਤਪਾਦ, ਸ਼੍ਰੇਣੀਆਂ, ਬ੍ਰਾਂਡ ਅਤੇ ਗਾਹਕ ਸਭ ਨਵੇਂ ਸਟੋਰ ਨਾਲ ਦੁਬਾਰਾ ਸਿੰਕ ਹੁੰਦੇ ਹਨ।',
'Woo_Guide_Keep_Skus' => 'Stocky ਅਤੇ WooCommerce ਵਿਚਕਾਰ SKU ਇਕਸਾਰ ਰੱਖੋ: ਇਹੀ ਡੁਪਲੀਕੇਟਾਂ ਨੂੰ ਰੋਕਦਾ ਹੈ ਅਤੇ ਦੁਬਾਰਾ ਲਿੰਕ ਕਰਨਾ ਸੁਰੱਖਿਅਤ ਬਣਾਉਂਦਾ ਹੈ।',
'Woo_Guide_Stock_Total' => 'Woo \'ਤੇ ਪ੍ਰਕਾਸ਼ਿਤ ਸਟਾਕ {total} ਹੈ, ਕਿਸੇ ਇੱਕ ਵੇਅਰਹਾਊਸ ਦਾ ਅੰਕੜਾ ਨਹੀਂ।',
'Woo_Total_Across_Warehouses' => 'ਸਾਰੇ ਵੇਅਰਹਾਊਸਾਂ ਦਾ ਕੁੱਲ',
'Woo_Guide_Full_Reference' => 'ਪੂਰਾ ਹਵਾਲਾ — ਹਰ ਦਾਇਰਾ, ਕਤਾਰ ਕਿਵੇਂ ਵਿਵਹਾਰ ਕਰਦੀ ਹੈ, ਅਤੇ ਸਮੱਸਿਆ-ਨਿਵਾਰਨ ਸੂਚੀ — {file} ਵਿੱਚ ਹੈ।',
'Woo_Way_Covers' => 'ਕਵਰ ਕਰਦਾ ਹੈ',
