'Woo_Way_Covers_Scheduled' => 'ਸਭ ਕੁਝ, ਦੋਵੇਂ ਦਿਸ਼ਾਵਾਂ: ਆਰਡਰ ਅਤੇ ਉਤਪਾਦ ਤਬਦੀਲੀਆਂ ਅੰਦਰ, ਕੈਟਾਲਾਗ ਅਤੇ ਸਟਾਕ ਬਾਹਰ',
'Woo_Way_Speed' => 'ਗਤੀ',
