'Woo_Way_Needs_Scheduled' => 'ਹਰ ਕੰਮ ਲਈ ਇੱਕ cron ਐਂਟਰੀ — ਜਾਂ ਕੁਝ ਨਹੀਂ, ਜੇ ਤੁਸੀਂ ਹੱਥੀਂ ਸਿੰਕ ਕਰਦੇ ਹੋ',
'Woo_Way_Switched_On_At' => 'ਇੱਥੇ ਚਾਲੂ ਕਰੋ',
'Woo_Way_Cron_Entries_Below' => 'ਹੇਠਾਂ ਦਿੱਤੀਆਂ cron ਐਂਟਰੀਆਂ',
'Woo_Cron_Orders' => 'ਹਰ 15 ਮਿੰਟ ਆਰਡਰ — ਸਿਰਫ਼ ਪਿਛਲੀ ਵਾਰ ਤੋਂ ਬਾਅਦ ਬਦਲੇ ਹੋਏ।',
'Woo_Cron_Products_Pull' => 'ਦੁਕਾਨ ਤੋਂ ਉਤਪਾਦ ਤਬਦੀਲੀਆਂ, ਹਰ ਰਾਤ 03:00 ਵਜੇ।',
