'Woo_Cron_Products_Push' => 'ਅਜੇ ਲਿੰਕ ਨਾ ਹੋਏ ਉਤਪਾਦ, ਹਰ ਰਾਤ 02:00 ਵਜੇ। ਮੌਜੂਦਾ ਉਤਪਾਦ ਦੁਬਾਰਾ ਨਹੀਂ ਲਿਖੇ ਜਾਂਦੇ।',
'Woo_Cmd_Stock' => 'ਹੁਣੇ ਹਰ ਲਿੰਕ ਕੀਤੇ ਉਤਪਾਦ ਦਾ ਸਟਾਕ ਪੁਸ਼ ਕਰੋ।',
'Woo_Cmd_Products_Unsynced' => 'ਉਹ ਉਤਪਾਦ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ ਜਿਨ੍ਹਾਂ ਦਾ ਅਜੇ WooCommerce id ਨਹੀਂ ਹੈ।',
'Woo_Cmd_Orders' => 'ਪਿਛਲੀ ਵਾਰ ਤੋਂ ਬਾਅਦ ਬਦਲੇ ਆਰਡਰ ਆਯਾਤ ਕਰੋ।',
'Woo_Cmd_Orders_Full' => 'ਸਿਰਫ਼ ਤਾਜ਼ਾ ਤਬਦੀਲੀਆਂ ਦੀ ਬਜਾਏ ਹਰ ਆਰਡਰ ਦੁਬਾਰਾ ਸਕੈਨ ਕਰੋ।',
'Woo_Cmd_Pull' => 'ਆਉਣ ਵਾਲਾ ਸਭ ਕੁਝ ਇੱਕੋ ਵਾਰ: ਉਤਪਾਦ, ਆਰਡਰ, ਗਾਹਕ।',
'Woo_Guide_Page_Title' => 'WooCommerce ਗਾਈਡ',
'Woo_Guide_Page_Subtitle' => 'ਦੁਕਾਨ ਨੂੰ ਜੋੜਨਾ, ਆਪਣੇ ਆਪ ਕੀ ਚੱਲਦਾ ਹੈ, ਅਤੇ ਇਸ ਸਰਵਰ ਲਈ cron ਐਂਟਰੀਆਂ',
'Woo_Settings_Button' => 'WooCommerce ਸੈਟਿੰਗਾਂ',
'Woo_No_Shop_Connected' => 'ਅਜੇ ਕੋਈ ਦੁਕਾਨ ਕਨੈਕਟ ਨਹੀਂ',
'Woo_No_Shop_Connected_Desc' => 'ਹੇਠਾਂ ਦਿੱਤਾ ਸਭ ਕੁਝ ਫਿਰ ਵੀ ਲਾਗੂ ਹੁੰਦਾ ਹੈ — WooCommerce ਸੈਟਿੰਗਾਂ ਪੰਨੇ \'ਤੇ ਸਟੋਰ URL ਅਤੇ API ਕੀਆਂ ਦਰਜ ਕਰੋ, ਫਿਰ ਵਾਪਸ ਆਓ।',
'Woo_Wp_Username' => 'WordPress ਵਰਤੋਂਕਾਰ ਨਾਮ',
'Woo_Wp_App_Password' => 'WordPress ਐਪਲੀਕੇਸ਼ਨ ਪਾਸਵਰਡ',
'Woo_Settings_Instant_Hint' => 'ਵਿਕਰੀ, ਵਾਪਸੀ ਜਾਂ ਸਮਾਯੋਜਨ ਸੇਵ ਹੁੰਦੇ ਹੀ ਸਿਰਫ਼ ਉਹਨਾਂ ਉਤਪਾਦਾਂ ਦਾ ਸਟਾਕ ਪੁਸ਼ ਭੇਜਦਾ ਹੈ, ਇਸ ਲਈ ਦੁਕਾਨ ਅਗਲੇ ਘੰਟਾਵਾਰ ਸਟਾਕ ਸਿੰਕ ਦੀ ਬਜਾਏ ਸਕਿੰਟਾਂ ਵਿੱਚ ਸਹੀ ਹੋ ਜਾਂਦੀ ਹੈ। ਹੋਰ ਕੁਝ ਇੰਸਟਾਲ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ — ਪੁਸ਼ ਵਿਕਰੀ ਦਾ ਜਵਾਬ ਦੇਣ ਤੋਂ ਬਾਅਦ ਚੱਲਦਾ ਹੈ, ਇਸ ਲਈ ਕਾਊਂਟਰ ਕਦੇ WooCommerce ਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਦਾ। {guide} ਟੈਬ \'ਤੇ ਹੋਰ ਜਾਣਕਾਰੀ।',
'Woo_Settings_Instant_Off_Alert' => 'ਇਸਨੂੰ ਬੰਦ ਛੱਡੋ ਤਾਂ POS ਵਿਕਰੀ WooCommerce ਤੱਕ ਸਿਰਫ਼ ਅਗਲੇ ਸਟਾਕ ਸਿੰਕ \'ਤੇ ਪਹੁੰਚਦੀ ਹੈ — ਇੱਕ ਘੰਟੇ ਤੱਕ ਬਾਅਦ।',
'Woo_Settings_Auto_Products_Hint' => 'Stocky ਵਿੱਚ ਬਣਾਇਆ, ਸੰਪਾਦਿਤ ਜਾਂ ਡੁਪਲੀਕੇਟ ਕੀਤਾ ਉਤਪਾਦ ਉਤਪਾਦ ਸਿੰਕ ਦੀ ਉਡੀਕ ਕਰਨ ਦੀ ਬਜਾਏ ਸੇਵ ਹੋਣ ਤੋਂ ਤੁਰੰਤ ਬਾਅਦ WooCommerce ਨੂੰ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ — ਵੇਰਵੇ, ਕੀਮਤ, ਵੇਰੀਐਂਟ, ਚਿੱਤਰ, ਫਿਰ ਇਸਦਾ ਸਟਾਕ। ਬਲਕ ਆਯਾਤ ਪੁਸ਼ ਨਹੀਂ ਹੁੰਦੇ; ਆਯਾਤ ਤੋਂ ਬਾਅਦ ਉਤਪਾਦ ਸਿੰਕ ਚਲਾਓ।',
'Woo_Sync_Tuning' => 'ਸਿੰਕ ਟਿਊਨਿੰਗ',
'Woo_Sync_Tuning_Intro' => 'ਡਿਫੌਲਟ ਜ਼ਿਆਦਾਤਰ ਸਟੋਰਾਂ ਲਈ ਢੁਕਵੇਂ ਹਨ। ਇਹਨਾਂ ਨੂੰ ਸਿਰਫ਼ ਉਦੋਂ ਬਦਲੋ ਜੇ ਤੁਹਾਡੀ ਹੋਸਟਿੰਗ \'ਤੇ ਸਿੰਕ ਹੌਲੀ ਹੋਵੇ ਜਾਂ ਟਾਈਮ ਆਊਟ ਹੋਵੇ। ਹਰ ਮੁੱਲ ਇੱਕ ਸੁਰੱਖਿਅਤ ਸੀਮਾ ਤੱਕ ਸੀਮਿਤ ਹੈ, ਅਤੇ ਖੇਤਰ ਖਾਲੀ ਕਰਨ ਨਾਲ ਇਸਦਾ ਡਿਫੌਲਟ ਬਹਾਲ ਹੋ ਜਾਂਦਾ ਹੈ।',
'Woo_Setting_This_Up' => 'ਇਸਨੂੰ ਸੈੱਟ ਕਰਨਾ',
'Woo_Setting_This_Up_Text' => 'API ਕੀਆਂ ਪ੍ਰਾਪਤ ਕਰਨਾ, WordPress ਐਪਲੀਕੇਸ਼ਨ ਪਾਸਵਰਡ ਕਿਸ ਲਈ ਹੈ, ਸ਼ਡਿਊਲ ਕੀਤੇ ਸਿੰਕਾਂ ਲਈ cron ਐਂਟਰੀਆਂ, ਅਤੇ ਸਟਾਕ ਬਦਲਦੇ ਹੀ ਦੁਕਾਨ ਤੱਕ ਕਿਵੇਂ ਪਹੁੰਚਾਉਣਾ ਹੈ — ਇਹ ਸਭ, ਇਸ ਸਰਵਰ ਦੀਆਂ ਆਪਣੀਆਂ ਕਾਪੀ ਲਈ ਤਿਆਰ cron ਲਾਈਨਾਂ ਸਮੇਤ, ਗਾਈਡ ਟੈਬ \'ਤੇ ਹੈ। ਇੱਕੋ ਕਾਪੀ, ਤਾਂ ਜੋ ਇਹ ਮੋਡੀਊਲ ਦੇ ਅਸਲ ਕੰਮ ਤੋਂ ਵੱਖਰੀ ਨਾ ਹੋਵੇ।',
