'Telegram_G_How_Sent' => 'ਸੁਨੇਹੇ ਕਿਵੇਂ ਭੇਜੇ ਜਾਂਦੇ ਹਨ',
'Telegram_G_A_Title' => 'ਤੁਰੰਤ — ਕੁਝ ਵੀ ਇੰਸਟਾਲ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ',
'Telegram_G_A_Body' => 'Stocky ਵਿੱਚ ਸੇਵ ਕੀਤੀ ਵਿਕਰੀ, ਖਰੀਦ, ਭੁਗਤਾਨ ਜਾਂ ਖਰਚਾ — POS ਵਿੱਚ ਜਾਂ ਐਡਮਿਨ ਵਿੱਚ — ਸੇਵ ਹੋਣ ਦੇ {after} ਉਸੇ ਬੇਨਤੀ ਵਿੱਚ Telegram ਨੂੰ ਭੇਜੀ ਜਾਂਦੀ ਹੈ। ਕੋਈ cron ਐਂਟਰੀ ਨਹੀਂ, ਕੋਈ ਕਿਊ ਵਰਕਰ ਨਹੀਂ, ਅਤੇ ਕੈਸ਼ੀਅਰ ਨੂੰ ਕਦੇ Telegram ਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਨੀ ਪੈਂਦੀ: ਸੁਨੇਹਾ ਜਾਣ ਤੱਕ ਵਿਕਰੀ ਦਾ ਜਵਾਬ ਪਹਿਲਾਂ ਹੀ ਦਿੱਤਾ ਜਾ ਚੁੱਕਾ ਹੁੰਦਾ ਹੈ।',
'Telegram_G_Right_After' => 'ਤੁਰੰਤ ਬਾਅਦ',
'Telegram_G_B_Title' => 'cron ਐਂਟਰੀ — ਮੁੜ-ਕੋਸ਼ਿਸ਼ਾਂ ਅਤੇ ਬੈਕਗ੍ਰਾਊਂਡ ਇਵੈਂਟਾਂ ਲਈ',
'Telegram_G_B_Body' => 'ਦੋ ਤਰ੍ਹਾਂ ਦੇ ਸੁਨੇਹੇ ਇਸਦੀ ਬਜਾਏ Telegram ਦੀ ਆਪਣੀ ਕਿਊ ਵਿੱਚ ਉਡੀਕ ਕਰਦੇ ਹਨ: ਅਸਫਲ ਭੇਜਣਾ (Telegram ਕੁਝ ਪਲ ਲਈ ਪਹੁੰਚ ਤੋਂ ਬਾਹਰ), ਜਿਸਨੂੰ ਅਗਲੇ ਕੁਝ ਮਿੰਟਾਂ ਵਿੱਚ ਤਿੰਨ ਵਾਰ ਤੱਕ ਹੋਰ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ; ਅਤੇ ਐਡਮਿਨ ਤੋਂ ਬਾਹਰ ਪੈਦਾ ਹੋਏ ਇਵੈਂਟ — WooCommerce ਜਾਂ Shopify ਤੋਂ ਇੰਪੋਰਟ ਕੀਤੇ ਆਰਡਰ, artisan ਕਮਾਂਡਾਂ। ਇਹ cron ਐਂਟਰੀ ਉਹਨਾਂ ਨੂੰ ਭੇਜਦੀ ਹੈ, ਹੋਰ ਕੁਝ ਨਹੀਂ:',
'Telegram_G_Cron_Note' => 'ਹਰ ਮਿੰਟ ਠੀਕ ਹੈ: ਜਿਸ ਰਨ ਵਿੱਚ ਕੁਝ ਉਡੀਕ ਨਹੀਂ ਕਰ ਰਿਹਾ ਉਹ ਤੁਰੰਤ ਖਤਮ ਹੋ ਜਾਂਦਾ ਹੈ। cPanel \'ਤੇ ਇਹ {cronJobs} ਵਿੱਚ ਜਾਂਦਾ ਹੈ — ਜੇ {php} ਪੁਰਾਣਾ ਹੈ ਤਾਂ PHP 8.2+ ਦਾ ਪੂਰਾ ਪਾਥ ਵਰਤੋ। Windows \'ਤੇ Task Scheduler ਵਰਤੋ, ਪ੍ਰੋਗਰਾਮ {program}, ਆਰਗੂਮੈਂਟ {args}, {path} ਵਿੱਚ ਸ਼ੁਰੂ।',
'Telegram_G_Waiting' => '{n} ਭੇਜੇ ਜਾਣ ਦੀ ਉਡੀਕ ਵਿੱਚ',
'Telegram_G_Nothing_Waiting' => 'ਕੁਝ ਵੀ ਉਡੀਕ ਵਿੱਚ ਨਹੀਂ',
'Telegram_G_Gave_Up' => '{n} ਮੁੜ-ਕੋਸ਼ਿਸ਼ਾਂ ਤੋਂ ਬਾਅਦ ਛੱਡ ਦਿੱਤੇ',
'Telegram_G_Growing_Note' => '— ਜੇ ਇਹ ਗਿਣਤੀ ਵਧਦੀ ਰਹਿੰਦੀ ਹੈ, ਤਾਂ cron ਐਂਟਰੀ ਨਹੀਂ ਚੱਲ ਰਹੀ।',
'Telegram_G_Without_Cron' => 'cron ਐਂਟਰੀ ਤੋਂ ਬਿਨਾਂ ਵੀ, Stocky ਵਿੱਚ ਸੇਵ ਕੀਤੀ ਹਰ ਚੀਜ਼ ਤੁਰੰਤ ਪਹੁੰਚਦੀ ਹੈ; ਤੁਸੀਂ ਸਿਰਫ਼ ਮੁੜ-ਕੋਸ਼ਿਸ਼ਾਂ ਅਤੇ ਇੰਪੋਰਟ ਕੀਤੇ ਆਰਡਰ ਗੁਆਉਂਦੇ ਹੋ।',
'Telegram_G_Everything_Else' => 'ਬਾਕੀ ਸਭ ਕੁਝ',
'Telegram_G_Platform_Delivers' => 'ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਪੈਦਾ ਹੋਏ ਇਵੈਂਟਾਂ ਦੇ ਸੁਨੇਹੇ ਪਲੇਟਫਾਰਮ ਦੁਆਰਾ ਪਹੁੰਚਾਏ ਜਾਂਦੇ ਹਨ — ਕੁਝ ਵੀ ਸੈੱਟ ਅੱਪ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।',
