'WhatsApp_G7' => '{title} ਕਦਮ 3 ਤੋਂ ਆਪਣੇ ਨੰਬਰ \'ਤੇ। ਡਿਵੈਲਪਮੈਂਟ ਮੋਡ ਵਿੱਚ ਨੰਬਰ ਪਹਿਲਾਂ API Setup → "To" ਹੇਠਾਂ ਸ਼ਾਮਲ ਕਰਨਾ ਲਾਜ਼ਮੀ ਹੈ। ਡਿਲੀਵਰੀ ਟਿੱਕ (ਭੇਜਿਆ → ਪਹੁੰਚਿਆ → ਪੜ੍ਹਿਆ) ਲੌਗ ਵਿੱਚ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ।',
