'Salla_Push_Products_Desc' => 'SKU ਰਾਹੀਂ Salla \'ਤੇ ਸਧਾਰਨ ਉਤਪਾਦ ਬਣਾਉਂਦਾ ਜਾਂ ਅੱਪਡੇਟ ਕਰਦਾ ਹੈ। ਇਸ ਵਰਜਨ ਵਿੱਚ ਵੇਰੀਐਂਟ ਉਤਪਾਦ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ — ਉਹਨਾਂ ਨੂੰ Salla ਤੋਂ ਪੁੱਲ ਕਰੋ, ਜਾਂ SKU ਰਾਹੀਂ ਮਿਲਾਓ।',
