'Salla_Pull_Products_From' => '{name} ਤੋਂ ਉਤਪਾਦ ਪੁੱਲ ਕਰੋ',
'Salla_Pull_Products_Desc' => 'Salla ਉਤਪਾਦ (ਵੇਰੀਐਂਟਾਂ ਸਮੇਤ) ਇੰਪੋਰਟ ਕਰਦਾ ਹੈ, ਮੌਜੂਦਾ ਉਤਪਾਦਾਂ ਨੂੰ SKU ਰਾਹੀਂ ਮਿਲਾਉਂਦਾ ਹੈ ਅਤੇ ਬਾਕੀ ਬਣਾਉਂਦਾ ਹੈ।',
