'Salla_Reset_Product_Links' => 'ਉਤਪਾਦ ਲਿੰਕ ਰੀਸੈੱਟ ਕਰੋ',
'Salla_Push_Stock_To' => '{name} ਨੂੰ ਸਟਾਕ ਪੱਧਰ ਪੁਸ਼ ਕਰੋ',
'Salla_Push_Stock_Desc' => 'ਹਰ ਲਿੰਕ ਕੀਤੇ ਉਤਪਾਦ (SKU ਰਾਹੀਂ) ਅਤੇ ਲਿੰਕ ਕੀਤੇ ਵੇਰੀਐਂਟ ਲਈ ਮੌਜੂਦਾ ਮਾਤਰਾਵਾਂ ਭੇਜਦਾ ਹੈ।',
'Salla_Counting_Selected_Warehouse' => 'ਸਿਰਫ਼ ਚੁਣੇ ਹੋਏ ਗੋਦਾਮ ਤੋਂ ਸਟਾਕ ਗਿਣਿਆ ਜਾ ਰਿਹਾ ਹੈ।',
'Salla_Counting_All_Warehouses' => 'ਸਾਰੇ ਗੋਦਾਮਾਂ ਵਿੱਚ ਸਟਾਕ ਗਿਣਿਆ ਜਾ ਰਿਹਾ ਹੈ।',
'Salla_Push_Stock' => 'ਸਟਾਕ ਪੁਸ਼ ਕਰੋ',
'Salla_Orders_Imported' => 'ਇੰਪੋਰਟ ਕੀਤੇ ਆਰਡਰ',
'Salla_Customers_Linked' => 'ਲਿੰਕ ਕੀਤੇ ਗਾਹਕ',
'Salla_Pull_Orders_From' => '{name} ਤੋਂ ਆਰਡਰ ਪੁੱਲ ਕਰੋ',
'Salla_Pull_Orders_Desc' => 'ਨਵੇਂ Salla ਆਰਡਰ ਆਮ ਤੌਰ \'ਤੇ ਵੈੱਬਹੁੱਕਾਂ ਰਾਹੀਂ ਆਪਣੇ ਆਪ ਆਉਂਦੇ ਹਨ ਅਤੇ ਵਿਕਰੀਆਂ ਬਣ ਜਾਂਦੇ ਹਨ। ਵੈੱਬਹੁੱਕ ਸੈੱਟ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਦਿੱਤੇ ਆਰਡਰ ਭਰਨ ਲਈ ਇਹ ਪੁੱਲ ਵਰਤੋ — ਪਹਿਲਾਂ ਹੀ ਇੰਪੋਰਟ ਕੀਤੇ ਆਰਡਰ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ।',
'Salla_Import_Into_Warehouse' => 'ਗੋਦਾਮ ਵਿੱਚ ਇੰਪੋਰਟ ਕਰੋ',
'Salla_Default_Warehouse_Option' => 'ਡਿਫਾਲਟ (ਸੈਟਿੰਗਾਂ / ਪਹਿਲਾ ਗੋਦਾਮ)',
'Salla_Pull_Orders' => 'ਆਰਡਰ ਪੁੱਲ ਕਰੋ',
'Salla_All_Levels' => 'ਸਾਰੇ ਪੱਧਰ',
'Salla_Error' => 'ਗਲਤੀ',
'Salla_Clear_Logs_Confirm' => 'ਸਾਰੇ {name} ਲੌਗ ਸਾਫ਼ ਕਰਨੇ ਹਨ?',
'Salla_Clear_Logs' => 'ਲੌਗ ਸਾਫ਼ ਕਰੋ',
'Salla_Guide_1' => '{link} \'ਤੇ ਇੱਕ (ਨਿੱਜੀ) ਐਪ ਬਣਾਓ ਅਤੇ {mode} ਪ੍ਰਮਾਣੀਕਰਨ ਫਲੋ ਚੁਣੋ।',
'Salla_Guide_2' => 'ਐਪ ਦਾ {clientId} ਅਤੇ {clientSecret} Connection ਟੈਬ ਵਿੱਚ ਕਾਪੀ ਕਰੋ ਅਤੇ ਸੇਵ ਕਰੋ।',
'Salla_Guide_3' => 'ਐਪ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ, Connection ਟੈਬ \'ਤੇ ਦਿਖਾਇਆ OAuth ਕਾਲਬੈਕ URL ਸੈੱਟ ਕਰੋ।',
'Salla_Guide_4' => 'ਐਪ ਦੇ Webhooks ਪੰਨੇ \'ਤੇ: {signature} ਸੁਰੱਖਿਆ ਰਣਨੀਤੀ ਚੁਣੋ, ਇਸਦਾ ਸੀਕ੍ਰੇਟ ਇੱਥੇ ਵੈੱਬਹੁੱਕ ਸੀਕ੍ਰੇਟ ਫੀਲਡ ਵਿੱਚ ਕਾਪੀ ਕਰੋ, Connection ਟੈਬ \'ਤੇ ਦਿਖਾਇਆ ਵੈੱਬਹੁੱਕ URL ਸੈੱਟ ਕਰੋ, ਅਤੇ ਘੱਟੋ-ਘੱਟ {e1}, {e2}, {e3}, {e4}, {e5} ਅਤੇ {e6} ਨੂੰ ਸਬਸਕ੍ਰਾਈਬ ਕਰੋ।',
'Salla_Guide_5' => '{connect} \'ਤੇ ਕਲਿੱਕ ਕਰੋ ਅਤੇ ਆਪਣੇ ਸਟੋਰ \'ਤੇ ਐਪ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦਿਓ। (Easy Mode ਵਾਲੀਆਂ ਐਪਾਂ ਇਸਦੀ ਬਜਾਏ {webhook} ਵੈੱਬਹੁੱਕ ਰਾਹੀਂ ਆਪਣੇ ਆਪ ਕਨੈਕਟ ਹੁੰਦੀਆਂ ਹਨ।)',
'Salla_Guide_6' => 'ਉਤਪਾਦ ਪੁੱਲ ਜਾਂ ਪੁਸ਼ ਕਰੋ, ਫਿਰ ਸਟਾਕ ਪੁਸ਼ ਕਰੋ। ਨਵੇਂ ਆਰਡਰ ਆਪਣੇ ਆਪ ਆਉਂਦੇ ਹਨ ਅਤੇ ਵਿਕਰੀਆਂ ਹੇਠਾਂ {ref} ਵਰਗੇ ਹਵਾਲਿਆਂ ਨਾਲ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ।',
'Salla_Identity_Sku_Title' => 'ਉਤਪਾਦ ਦੀ ਪਛਾਣ SKU ਹੈ',
'Salla_Identity_Sku_Desc' => 'Stocky ਦਾ ਉਤਪਾਦ ਕੋਡ Salla ਦੇ SKU ਨਾਲ ਮਿਲਾਇਆ ਜਾਂਦਾ ਹੈ। ਦੋਵੇਂ ਪਾਸੇ SKU ਇਕਸਾਰ ਰੱਖੋ; ਵੇਰੀਐਂਟ ਉਤਪਾਦ ਪੁੱਲ ਅਤੇ ਆਰਡਰਾਂ ਵਿੱਚ ਮਿਲਾਏ ਜਾਂਦੇ ਹਨ, ਪਰ ਇਸ ਵਰਜਨ ਵਿੱਚ ਪੁਸ਼ ਨਹੀਂ ਕੀਤੇ ਜਾਂਦੇ।',
'Salla_Connected_To' => '{name} ਨਾਲ ਕਨੈਕਟ ਹੈ',
'Salla_Connection_Test_Failed' => 'ਕਨੈਕਸ਼ਨ ਟੈਸਟ ਅਸਫਲ',
'Salla_Removed_Links' => '{n} ਲਿੰਕ ਹਟਾਏ ਗਏ',
'Salla_Store_Connected' => 'Salla ਸਟੋਰ ਕਨੈਕਟ ਹੋ ਗਿਆ।',
'Presta_Not_Configured' => 'ਕੌਂਫਿਗਰ ਨਹੀਂ ਕੀਤਾ',
'Presta_Hero_Desc' => 'ਆਪਣੇ PrestaShop ਸਟੋਰ ਨਾਲ ਇਸਦੇ webservice API ਰਾਹੀਂ ਉਤਪਾਦ, ਸਟਾਕ ਅਤੇ ਆਰਡਰ ਸਿੰਕ ਕਰੋ।',
'Presta_Webservice_Key' => 'Webservice ਕੁੰਜੀ',
'Presta_Saved_Paste_New_Key' => 'ਸੇਵ ਕੀਤੀ — ਬਦਲਣ ਲਈ ਨਵੀਂ ਕੁੰਜੀ ਪੇਸਟ ਕਰੋ',
'Presta_From_Menu' => '{menu} ਤੋਂ',
'Presta_Webservice_Key_Help' => 'PrestaShop ਵਿੱਚ webservice ਚਾਲੂ ਕਰੋ ({menu}), products, stock_availables, orders ਅਤੇ customers \'ਤੇ ਅਨੁਮਤੀਆਂ ਵਾਲੀ ਕੁੰਜੀ ਬਣਾਓ, ਅਤੇ ਇਸਨੂੰ ਇੱਥੇ ਪੇਸਟ ਕਰੋ। ਸਿਰਫ਼-ਲਿਖਣ ਲਈ ਸਟੋਰ ਹੁੰਦੀ ਹੈ।',
'Presta_Shop_Language_Id' => 'ਦੁਕਾਨ ਭਾਸ਼ਾ ID',
'Presta_Shop_Language_Help' => 'ਪੁਸ਼ ਕਰਦੇ ਸਮੇਂ ਉਤਪਾਦ ਨਾਵਾਂ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਭਾਸ਼ਾ id (1 = ਦੁਕਾਨ ਦੀ ਪਹਿਲੀ ਭਾਸ਼ਾ)।',
'Presta_Push_Products_Desc' => 'PrestaShop \'ਤੇ ਗੁੰਮ ਸਧਾਰਨ ਉਤਪਾਦ (ਉਹਨਾਂ ਦੇ ਮੌਜੂਦਾ ਸਟਾਕ ਸਮੇਤ) ਬਣਾਉਂਦਾ ਹੈ। ਪਹਿਲਾਂ ਤੋਂ ਲਿੰਕ ਕੀਤੇ ਉਤਪਾਦ ਅਤੇ ਵੇਰੀਐਂਟ ਉਤਪਾਦ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ — ਉਤਪਾਦ ਵੇਰਵੇ PrestaShop ਵਿੱਚ ਹੀ ਸੋਧਦੇ ਰਹੋ, ਜਾਂ ਲੋਕਲ ਕਾਪੀ ਤਾਜ਼ਾ ਕਰਨ ਲਈ ਪੁੱਲ ਕਰੋ।',
'Presta_Pull_Products_Desc' => 'PrestaShop ਉਤਪਾਦ ਇੰਪੋਰਟ ਕਰਦਾ ਹੈ, ਮੌਜੂਦਾ ਉਤਪਾਦਾਂ ਨੂੰ ਰੈਫਰੈਂਸ (SKU) ਰਾਹੀਂ ਮਿਲਾਉਂਦਾ ਹੈ ਅਤੇ ਬਾਕੀ ਬਣਾਉਂਦਾ ਹੈ। ਕੰਬੀਨੇਸ਼ਨ ਆਪਣੇ ਮੂਲ ਉਤਪਾਦ ਵਜੋਂ ਇੰਪੋਰਟ ਹੁੰਦੇ ਹਨ।',
'Presta_Reset_Product_Confirm' => 'ਉਤਪਾਦ ਲਿੰਕ ਰੀਸੈੱਟ ਕਰਨੇ ਹਨ? ਆਰਡਰ ਇਤਿਹਾਸ ਆਪਣੇ ਲਿੰਕ ਰੱਖਦਾ ਹੈ।',
'Presta_Push_Stock_Desc' => 'ਹਰ ਲਿੰਕ ਕੀਤੇ ਉਤਪਾਦ ਲਈ ਦੁਕਾਨ ਦਾ ਸਟਾਕ (stock_availables) ਅੱਪਡੇਟ ਕਰਦਾ ਹੈ।',
'Presta_Pull_Orders_Desc' => 'ਦੁਕਾਨ ਦੇ ਆਰਡਰਾਂ ਨੂੰ ਵਿਕਰੀਆਂ ਵਜੋਂ ਇੰਪੋਰਟ ਕਰਦਾ ਹੈ ({ref} ਵਰਗੇ ਹਵਾਲੇ), ਨਵੇਂ ਪਹਿਲਾਂ। ਪਹਿਲਾਂ ਹੀ ਇੰਪੋਰਟ ਕੀਤੇ ਅਤੇ ਰੱਦ ਕੀਤੇ ਆਰਡਰ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ, ਇਸ ਲਈ ਨਿਯਮਿਤ ਪੁੱਲ ਕਰਨਾ ਸੁਰੱਖਿਅਤ ਹੈ। PrestaShop ਵਿੱਚ ਵੈੱਬਹੁੱਕ ਨਹੀਂ ਹਨ — ਰੁਝੇਵੇਂ ਵਾਲੇ ਸਮੇਂ ਤੋਂ ਬਾਅਦ ਇਸਨੂੰ ਚਲਾਓ।',
'Presta_Guide_1' => 'ਆਪਣੇ PrestaShop ਬੈਕ ਆਫਿਸ ਵਿੱਚ {menu} ਖੋਲ੍ਹੋ ਅਤੇ webservice ਚਾਲੂ ਕਰੋ।',
'Presta_Guide_2' => 'ਇੱਕ ਨਵੀਂ ਕੁੰਜੀ ਸ਼ਾਮਲ ਕਰੋ, {products} ਅਤੇ {stock} \'ਤੇ {rw}, ਅਤੇ {orders} ਅਤੇ {customers} \'ਤੇ {view} ਦਿੰਦੇ ਹੋਏ।',
'Presta_Guide_3' => 'Connection ਟੈਬ \'ਤੇ ਸਟੋਰ URL ਅਤੇ ਕੁੰਜੀ ਪੇਸਟ ਕਰੋ, ਸੇਵ ਕਰੋ, ਅਤੇ {test} ਚਲਾਓ।',
'Presta_Guide_4' => 'ਜੇ ਦੁਕਾਨ ਵਿੱਚ ਪਹਿਲਾਂ ਹੀ ਕੈਟਾਲਾਗ ਹੈ ਤਾਂ ਪਹਿਲਾਂ ਉਤਪਾਦ ਪੁੱਲ ਕਰੋ (ਰੈਫਰੈਂਸ/SKU ਰਾਹੀਂ ਮਿਲਾਉਂਦਾ ਹੈ); ਗੁੰਮ ਸਧਾਰਨ ਉਤਪਾਦ ਬਣਾਉਣ ਲਈ ਪੁਸ਼ ਕਰੋ।',
'Presta_Guide_5' => 'ਜਦੋਂ ਵੀ ਮਾਤਰਾਵਾਂ ਬਦਲਣ ਸਟਾਕ ਪੁਸ਼ ਕਰੋ, ਅਤੇ ਨਿਯਮਿਤ ਤੌਰ \'ਤੇ ਆਰਡਰ ਪੁੱਲ ਕਰੋ — PrestaShop ਵਿੱਚ ਵੈੱਬਹੁੱਕ ਨਹੀਂ ਹਨ, ਇਸ ਲਈ ਆਰਡਰ ਸਿਰਫ਼ ਪੁੱਲ ਕਰਨ \'ਤੇ ਹੀ ਆਉਂਦੇ ਹਨ।',
'Presta_Identity_Title' => 'ਉਤਪਾਦ ਦੀ ਪਛਾਣ ਰੈਫਰੈਂਸ (SKU) ਹੈ',
'Presta_Identity_Desc' => 'Stocky ਦਾ ਉਤਪਾਦ ਕੋਡ PrestaShop ਦੇ ਰੈਫਰੈਂਸ ਨਾਲ ਮਿਲਾਇਆ ਜਾਂਦਾ ਹੈ। ਦੋਵੇਂ ਪਾਸੇ ਰੈਫਰੈਂਸ ਇਕਸਾਰ ਰੱਖੋ; ਕੰਬੀਨੇਸ਼ਨ (ਵੇਰੀਐਂਟ) ਆਰਡਰਾਂ ਵਿੱਚ ਰੈਫਰੈਂਸ ਰਾਹੀਂ ਮਿਲਾਏ ਜਾਂਦੇ ਹਨ ਪਰ ਇਸ ਵਰਜਨ ਵਿੱਚ ਪੁਸ਼ ਨਹੀਂ ਕੀਤੇ ਜਾਂਦੇ।',
'Xero_Hero_Title' => 'Xero ਲੇਖਾ ਸਿੰਕ',
'Xero_Hero_Desc' => 'ਆਪਣੇ ਗਾਹਕਾਂ ਨੂੰ Xero ਸੰਪਰਕਾਂ ਵਜੋਂ ਅਤੇ ਵਿਕਰੀਆਂ ਨੂੰ ਇਨਵੌਇਸਾਂ ਵਜੋਂ ਪੁਸ਼ ਕਰੋ — ਬੈਂਕ ਖਾਤਾ ਕੌਂਫਿਗਰ ਹੋਣ \'ਤੇ ਭੁਗਤਾਨਾਂ ਸਮੇਤ।',
'Xero_App_Credentials_Accounts' => 'ਐਪ ਕ੍ਰੈਡੈਂਸ਼ੀਅਲ ਅਤੇ ਖਾਤੇ',
'Xero_From_Dev_App' => 'developer.xero.com \'ਤੇ ਤੁਹਾਡੀ ਐਪ ਤੋਂ',
'Xero_Sales_Account_Code' => 'ਵਿਕਰੀ ਖਾਤਾ ਕੋਡ',
'Xero_Sales_Account_Help' => 'ਇਨਵੌਇਸ ਲਾਈਨਾਂ ਲਈ ਆਮਦਨ ਖਾਤਾ (\'200\' Xero ਦਾ ਡਿਫਾਲਟ Sales ਖਾਤਾ ਹੈ)।',
'Xero_Payment_Account_Code' => 'ਭੁਗਤਾਨ ਖਾਤਾ ਕੋਡ (ਵਿਕਲਪਿਕ)',
'Xero_Payment_Account_Ph' => 'ਜਿਵੇਂ 090',
'Xero_Payment_Account_Help' => 'ਇੱਕ ਬੈਂਕ ਖਾਤਾ ਕੋਡ। ਸੈੱਟ ਹੋਣ \'ਤੇ, ਭੁਗਤਾਨ ਕੀਤੀਆਂ ਵਿਕਰੀਆਂ ਇਨਵੌਇਸ \'ਤੇ ਭੁਗਤਾਨ ਵੀ ਦਰਜ ਕਰਦੀਆਂ ਹਨ; ਸਿਰਫ਼ ਇਨਵੌਇਸ ਸਿੰਕ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ।',
'Xero_Auto_Sync_Sales' => 'ਨਵੀਆਂ ਵਿਕਰੀਆਂ ਨੂੰ ਇਨਵੌਇਸਾਂ ਵਜੋਂ ਆਟੋ-ਸਿੰਕ ਕਰੋ',
'Xero_Auto_Sync_Sales_Hint' => '(ਵਿਕਰੀਆਂ ਬਣਨ \'ਤੇ ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਕਿਊ ਹੁੰਦਾ ਹੈ)',
'Xero_Org_Connection' => 'ਸੰਸਥਾ ਕਨੈਕਸ਼ਨ',
'Xero_Organisation' => 'ਸੰਸਥਾ',
'Xero_Disconnect_Confirm' => 'Xero ਸੰਸਥਾ ਡਿਸਕਨੈਕਟ ਕਰਨੀ ਹੈ? ਦੁਬਾਰਾ ਕਨੈਕਟ ਕਰਨ ਤੱਕ ਸਿੰਕ ਰੁਕ ਜਾਂਦਾ ਹੈ।',
'Xero_Redirect_Uri_Title' => 'Xero ਐਪ ਲਈ ਰੀਡਾਇਰੈਕਟ URI',
'Xero_Redirect_Uri_Help' => '{link} \'ਤੇ ਇੱਕ "Web app" ਬਣਾਓ ਅਤੇ ਇਹ ਰੀਡਾਇਰੈਕਟ URI ਰਜਿਸਟਰ ਕਰੋ। ਨੋਟ: Xero ਐਕਸੈਸ ਟੋਕਨ ਆਪਣੇ ਆਪ ਰਿਫ੍ਰੈਸ਼ ਹੁੰਦੇ ਹਨ, ਪਰ 60 ਦਿਨਾਂ ਤੋਂ ਵੱਧ ਬੇਕਾਰ ਪਿਆ ਕਨੈਕਸ਼ਨ ਦੁਬਾਰਾ ਕਨੈਕਟ ਕਰਨਾ ਪਵੇਗਾ।',
'Xero_Total_Customers' => 'ਕੁੱਲ ਗਾਹਕ',
'Xero_Contacts_In_Xero' => 'Xero ਵਿੱਚ ਸੰਪਰਕ',
'Xero_Total_Sales' => 'ਕੁੱਲ ਵਿਕਰੀਆਂ',
'Xero_Invoices_In_Xero' => 'Xero ਵਿੱਚ ਇਨਵੌਇਸ',
'Xero_Payments_Recorded' => 'ਦਰਜ ਭੁਗਤਾਨ',
'Xero_Push_Customers_To' => '{name} ਨੂੰ ਗਾਹਕ ਪੁਸ਼ ਕਰੋ',
'Xero_Push_Customers_Desc' => 'ਹਰ ਗਾਹਕ ਲਈ Xero ਸੰਪਰਕ ਬਣਾਉਂਦਾ ਜਾਂ ਅੱਪਡੇਟ ਕਰਦਾ ਹੈ। ਜਿਸ ਗਾਹਕ ਦਾ ਨਾਂ Xero ਵਿੱਚ ਪਹਿਲਾਂ ਹੀ ਮੌਜੂਦ ਹੈ, ਉਹ ਉਸ ਸੰਪਰਕ ਨਾਲ ਲਿੰਕ ਹੋ ਜਾਂਦਾ ਹੈ।',
'Xero_Push_Customers' => 'ਗਾਹਕ ਪੁਸ਼ ਕਰੋ',
'Xero_Push_Sales_Invoices' => 'ਵਿਕਰੀਆਂ ਨੂੰ ਇਨਵੌਇਸਾਂ ਵਜੋਂ ਪੁਸ਼ ਕਰੋ',
'Xero_Push_Invoices_Desc' => 'ਹਰ ਵਿਕਰੀ ਲਈ ਇੱਕ AUTHORISED ਇਨਵੌਇਸ ਬਣਾਉਂਦਾ ਹੈ (ਇਨਵੌਇਸ ਨੰਬਰ = ਵਿਕਰੀ Ref), ਵਿਕਰੀ ਦੀਆਂ ਆਈਟਮ ਲਾਈਨਾਂ ਨਾਲ ਸ਼ਿਪਿੰਗ, ਛੋਟ ਅਤੇ ਟੈਕਸ ਲਾਈਨਾਂ ਸਮੇਤ ਤਾਂ ਜੋ Xero ਦਾ ਕੁੱਲ ਵਿਕਰੀ ਦੇ ਕੁੱਲ ਨਾਲ ਮੇਲ ਖਾਵੇ। Xero ਵਿੱਚ ਪਹਿਲਾਂ ਤੋਂ ਮੌਜੂਦ ਵਿਕਰੀਆਂ ਛੱਡ ਦਿੱਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ — ਇਨਵੌਇਸ ਕਦੇ ਸੋਧੇ ਨਹੀਂ ਜਾਂਦੇ। ਗੁੰਮ ਸੰਪਰਕ ਨਾਲੋ-ਨਾਲ ਬਣਾਏ ਜਾਂਦੇ ਹਨ।',
'Xero_Push_Invoices' => 'ਇਨਵੌਇਸ ਪੁਸ਼ ਕਰੋ',
'Xero_Reset_Contact_Confirm' => 'ਸੰਪਰਕ ਲਿੰਕ ਰੀਸੈੱਟ ਕਰਨੇ ਹਨ? ਅਗਲਾ ਪੁਸ਼ ਉਹਨਾਂ ਨੂੰ ਦੁਬਾਰਾ ਲਿੰਕ ਕਰਦਾ ਜਾਂ ਦੁਬਾਰਾ ਬਣਾਉਂਦਾ ਹੈ।',
'Xero_Reset_Contact_Links' => 'ਸੰਪਰਕ ਲਿੰਕ ਰੀਸੈੱਟ ਕਰੋ',
'Xero_Guide_1' => '{link} ({menu}) \'ਤੇ ਇੱਕ {webApp} ਬਣਾਓ।',
'Xero_Guide_2' => 'Connection ਟੈਬ \'ਤੇ ਦਿਖਾਇਆ ਰੀਡਾਇਰੈਕਟ URI ਰਜਿਸਟਰ ਕਰੋ।',
'Xero_Guide_3' => 'ਐਪ ਦਾ {clientId} ਕਾਪੀ ਕਰੋ ਅਤੇ ਇੱਕ {clientSecret} ਬਣਾਓ; ਦੋਵੇਂ ਇੱਥੇ ਪੇਸਟ ਕਰੋ ਅਤੇ ਸੇਵ ਕਰੋ।',
'Xero_Guide_4' => '{connect} \'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਸਾਈਨ ਇਨ ਕਰੋ ਅਤੇ ਕਨੈਕਟ ਕਰਨ ਲਈ ਸੰਸਥਾ ਚੁਣੋ।',
'Xero_Guide_5' => 'ਖਾਤਾ ਕੋਡ ਜਾਂਚੋ: ਵਿਕਰੀ ਖਾਤਾ ਇਨਵੌਇਸ ਲਾਈਨਾਂ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ; ਜੇ ਭੁਗਤਾਨ ਕੀਤੀਆਂ ਵਿਕਰੀਆਂ ਨੂੰ ਭੁਗਤਾਨ ਵੀ ਦਰਜ ਕਰਨੇ ਚਾਹੀਦੇ ਹਨ ਤਾਂ ਬੈਂਕ ਖਾਤਾ ਕੋਡ ਸੈੱਟ ਕਰੋ।',
'Xero_Guide_6' => 'ਪਹਿਲਾਂ ਗਾਹਕ ਪੁਸ਼ ਕਰੋ, ਫਿਰ ਇਨਵੌਇਸ। ਇਨਵੌਇਸ ਨੰਬਰ ਵਿਕਰੀ Refs ਹਨ, ਇਸ ਲਈ ਲਿੰਕ ਰੀਸੈੱਟ ਹੋਣ \'ਤੇ ਵੀ Xero ਡੁਪਲੀਕੇਟ ਰੱਦ ਕਰ ਦਿੰਦਾ ਹੈ।',
'Xero_Amounts_Title' => 'ਰਕਮਾਂ ਜਿਵੇਂ ਹਨ ਟੈਕਸ-ਸਮੇਤ ਪੁਸ਼ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ',
'Xero_Amounts_Desc' => 'ਇਨਵੌਇਸ NoTax ਲਾਈਨਾਂ ਵਰਤਦੇ ਹਨ ਜੋ ਵਿਕਰੀ ਨੂੰ ਬਿਲਕੁਲ ਦਰਸਾਉਂਦੀਆਂ ਹਨ (ਆਈਟਮਾਂ + ਸ਼ਿਪਿੰਗ − ਛੋਟ + ਟੈਕਸ), ਇਸ ਲਈ Xero ਦੇ ਕੁੱਲ ਹਮੇਸ਼ਾ Stocky ਦੇ ਕੁੱਲ ਦੇ ਬਰਾਬਰ ਹੁੰਦੇ ਹਨ। ਤੁਹਾਡਾ ਲੇਖਾਕਾਰ Xero ਦੇ ਅੰਦਰ ਟੈਕਸ ਅਤੇ ਸ਼ਿਪਿੰਗ ਲਾਈਨਾਂ ਨੂੰ ਸਹੀ ਖਾਤਿਆਂ ਵਿੱਚ ਦੁਬਾਰਾ ਮੈਪ ਕਰ ਸਕਦਾ ਹੈ।',
'Xero_Org_Connected' => 'Xero ਸੰਸਥਾ ਕਨੈਕਟ ਹੋ ਗਈ।',
'Jumia_Hero_Title' => 'Jumia ਮਾਰਕੀਟਪਲੇਸ ਸਿੰਕ',
'Jumia_Hero_Desc' => 'ਆਪਣੀਆਂ Jumia Seller Center ਲਿਸਟਿੰਗਾਂ ਨੂੰ ਕੀਮਤਾਂ ਅਤੇ ਸਟਾਕ ਪੁਸ਼ ਕਰੋ ਅਤੇ ਮਾਰਕੀਟਪਲੇਸ ਆਰਡਰਾਂ ਨੂੰ ਵਿਕਰੀਆਂ ਵਜੋਂ ਇੰਪੋਰਟ ਕਰੋ।',
'Jumia_Api_Url_Label' => 'API URL (ਤੁਹਾਡੇ ਦੇਸ਼ ਦਾ Seller Center ਐਂਡਪੁਆਇੰਟ)',
'Jumia_Account_Email' => 'ਖਾਤਾ ਈਮੇਲ (User ID)',
'Jumia_Api_Key' => 'API ਕੁੰਜੀ',
'Jumia_Prices_Stock' => 'ਕੀਮਤਾਂ ਅਤੇ ਸਟਾਕ',
'Jumia_Push_Prices_Stock_Title' => 'Jumia ਨੂੰ ਕੀਮਤਾਂ ਅਤੇ ਸਟਾਕ ਪੁਸ਼ ਕਰੋ',
'Jumia_Push_Prices_Stock_Desc' => 'ਹਰ ਉਸ ਉਤਪਾਦ (ਅਤੇ ਵੇਰੀਐਂਟ) ਲਈ ਮੌਜੂਦਾ ਕੀਮਤ ਅਤੇ ਮਾਤਰਾ ਭੇਜਦਾ ਹੈ ਜਿਸਦਾ SKU Jumia ਲਿਸਟਿੰਗ ਦੇ {sku} ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ। ਅੱਪਡੇਟ Seller Center ਫੀਡਾਂ ਵਜੋਂ ਭੇਜੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਅਸਿੰਕ੍ਰੋਨਸ ਤੌਰ \'ਤੇ ਲਾਗੂ ਹੁੰਦੇ ਹਨ — ਫੀਡ ID Logs ਟੈਬ ਵਿੱਚ ਦਰਜ ਹੁੰਦੀ ਹੈ, ਅਤੇ ਪ੍ਰਤੀ-ਆਈਟਮ ਅਸਵੀਕਾਰ Seller Center ਦੀ ਫੀਡ ਸਥਿਤੀ ਸਕ੍ਰੀਨ \'ਤੇ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ।',
'Jumia_Push_Prices_Stock' => 'ਕੀਮਤਾਂ ਅਤੇ ਸਟਾਕ ਪੁਸ਼ ਕਰੋ',
'Jumia_Pull_Orders_Desc' => 'ਮਾਰਕੀਟਪਲੇਸ ਆਰਡਰਾਂ ਨੂੰ ਵਿਕਰੀਆਂ ਵਜੋਂ ਇੰਪੋਰਟ ਕਰਦਾ ਹੈ ({ref} ਵਰਗੇ ਹਵਾਲੇ), Seller SKU ਰਾਹੀਂ ਤੁਹਾਡੇ ਉਤਪਾਦਾਂ ਨਾਲ ਮਿਲਾ ਕੇ। ਪਹਿਲਾਂ ਹੀ ਇੰਪੋਰਟ ਕੀਤੇ ਅਤੇ ਰੱਦ ਕੀਤੇ ਆਰਡਰ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ, ਇਸ ਲਈ ਨਿਯਮਿਤ ਪੁੱਲ ਕਰਨਾ ਸੁਰੱਖਿਅਤ ਹੈ। ਭੁਗਤਾਨ ਸਿਰਫ਼ ਡਿਲੀਵਰ ਹੋਏ ਆਰਡਰਾਂ ਲਈ ਭੁਗਤਾਨ ਕੀਤੇ ਵਜੋਂ ਨਿਸ਼ਾਨਬੱਧ ਹੁੰਦੇ ਹਨ (Jumia ਵਿੱਚ ਜ਼ਿਆਦਾਤਰ COD ਹੁੰਦਾ ਹੈ)।',
'Jumia_Guide_1' => 'Jumia {sellerCenter} ਵਿੱਚ {menu} ਖੋਲ੍ਹੋ ਅਤੇ ਇੱਕ API ਕੁੰਜੀ ਬਣਾਓ।',
'Jumia_Guide_2' => 'ਆਪਣੇ ਦੇਸ਼ ਦਾ API URL (ਜਿਵੇਂ ਨਾਈਜੀਰੀਆ ਲਈ {ng}, ਕੀਨੀਆ ਲਈ {ke}, ਮਿਸਰ ਲਈ {eg}), ਆਪਣੀ Seller Center ਖਾਤਾ ਈਮੇਲ, ਅਤੇ ਕੁੰਜੀ ਦਰਜ ਕਰੋ — ਫਿਰ {test} ਚਲਾਓ।',
'Jumia_Guide_3' => 'ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਹਰ Jumia ਲਿਸਟਿੰਗ ਦਾ {sku} Stocky ਉਤਪਾਦ ਕੋਡ ਦੇ ਬਰਾਬਰ ਹੈ — ਇਹੀ ਪਛਾਣ ਸਟਾਕ ਪੁਸ਼ ਅਤੇ ਆਰਡਰ ਮਿਲਾਨ ਦੋਵਾਂ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਹੈ।',
'Jumia_Guide_4' => 'ਇਨਵੈਂਟਰੀ ਬਦਲਣ ਤੋਂ ਬਾਅਦ ਕੀਮਤਾਂ ਅਤੇ ਸਟਾਕ ਪੁਸ਼ ਕਰੋ; ਨਿਯਮਿਤ ਤੌਰ \'ਤੇ ਆਰਡਰ ਪੁੱਲ ਕਰੋ (ਇਸ API ਵਿੱਚ Jumia ਦੇ ਵੈੱਬਹੁੱਕ ਨਹੀਂ ਹਨ)।',
'Jumia_Guide_5' => 'ਨਵੀਆਂ ਲਿਸਟਿੰਗਾਂ ਬਣਾਉਣਾ Seller Center ਵਿੱਚ ਹੀ ਰਹਿੰਦਾ ਹੈ — Jumia ਨੂੰ ਸ਼੍ਰੇਣੀ-ਵਿਸ਼ੇਸ਼ ਗੁਣ ਅਤੇ ਤਸਵੀਰ ਸਮੀਖਿਆ ਚਾਹੀਦੀ ਹੈ ਜੋ ਸਿਰਫ਼ ਉਹਨਾਂ ਦਾ ਪੋਰਟਲ ਚੰਗੀ ਤਰ੍ਹਾਂ ਸੰਭਾਲਦਾ ਹੈ।',
'Mailchimp_Hero_Title' => 'Mailchimp ਦਰਸ਼ਕ ਸਿੰਕ',
'Mailchimp_Hero_Desc' => 'Mailchimp ਦਰਸ਼ਕਾਂ ਨੂੰ ਆਪਣੇ ਗਾਹਕਾਂ ਨਾਲ ਭਰਿਆ ਰੱਖੋ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਆਪਣੇ ਅਸਲ ਗਾਹਕ ਅਧਾਰ \'ਤੇ ਈਮੇਲ ਮੁਹਿੰਮਾਂ ਚਲਾ ਸਕੋ।',
'Mailchimp_Account_Audience' => 'ਖਾਤਾ ਅਤੇ ਦਰਸ਼ਕ',
'Mailchimp_Api_Key_Ph' => 'ਜਿਵੇਂ {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} ਮੈਂਬਰ)',
'Mailchimp_Load_Audiences_Ph' => 'ਇੱਕ ਚੁਣਨ ਲਈ ਦਰਸ਼ਕ ਲੋਡ ਕਰੋ',
'Mailchimp_Load_Audiences' => 'ਦਰਸ਼ਕ ਲੋਡ ਕਰੋ',
'Mailchimp_Double_Optin_Label' => 'ਡਬਲ ਔਪਟ-ਇਨ — ਨਵੇਂ ਮੈਂਬਰਾਂ ਨੂੰ ਜੁੜਨ ਤੋਂ ਪਹਿਲਾਂ ਪੁਸ਼ਟੀ ਈਮੇਲ ਮਿਲਦੀ ਹੈ',
'Mailchimp_Double_Optin_Hint' => '(GDPR ਲਈ ਸਿਫ਼ਾਰਸ਼ੀ)',
'Mailchimp_Auto_Sync_Customers' => 'ਨਵੇਂ ਗਾਹਕ ਬਣਦੇ ਹੀ ਆਟੋ-ਸਿੰਕ ਕਰੋ',
'Mailchimp_With_Email' => 'ਈਮੇਲ ਵਾਲੇ',
'Mailchimp_Push_Desc' => 'ਈਮੇਲ ਪਤੇ ਵਾਲੇ ਹਰ ਗਾਹਕ ਨੂੰ ਚੁਣੇ ਹੋਏ ਦਰਸ਼ਕਾਂ ਵਿੱਚ ਜੋੜਦਾ ਜਾਂ ਅੱਪਡੇਟ ਕਰਦਾ ਹੈ (ਨਾਂ ਅਤੇ ਫ਼ੋਨ ਸਮੇਤ)। ਮੌਜੂਦਾ ਮੈਂਬਰ ਆਪਣੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸਥਿਤੀ ਰੱਖਦੇ ਹਨ — ਅਨਸਬਸਕ੍ਰਾਈਬ ਕਰਨ ਵਾਲੇ ਕਿਸੇ ਨੂੰ ਵੀ ਦੁਬਾਰਾ ਸਬਸਕ੍ਰਾਈਬ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ। ਬਿਨਾਂ ਈਮੇਲ ਵਾਲੇ ਗਾਹਕ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ।',
'Mailchimp_Double_Optin_Off_Title' => 'ਡਬਲ ਔਪਟ-ਇਨ ਬੰਦ ਹੈ',
'Mailchimp_Double_Optin_Off_Desc' => 'ਨਵੇਂ ਮੈਂਬਰ ਪੁਸ਼ਟੀ ਈਮੇਲ ਤੋਂ ਬਿਨਾਂ ਸਬਸਕ੍ਰਾਈਬ ਵਜੋਂ ਜੋੜੇ ਜਾਣਗੇ। ਇਹ ਸਿਰਫ਼ ਉਹਨਾਂ ਗਾਹਕਾਂ ਲਈ ਕਰੋ ਜੋ ਪਹਿਲਾਂ ਹੀ ਮਾਰਕੀਟਿੰਗ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਸਹਿਮਤ ਹਨ।',
'Mailchimp_Guide_1' => 'Mailchimp ਵਿੱਚ {menu} ਖੋਲ੍ਹੋ ਅਤੇ ਇੱਕ ਕੁੰਜੀ ਬਣਾਓ (ਇਹ {suffix} ਨਾਲ ਖਤਮ ਹੁੰਦੀ ਹੈ — ਉਹ ਪਿਛੇਤਰ ਤੁਹਾਡਾ ਡਾਟਾਸੈਂਟਰ ਹੈ)।',
'Mailchimp_Guide_2' => 'ਕੁੰਜੀ ਇੱਥੇ ਪੇਸਟ ਕਰੋ, ਸੇਵ ਕਰੋ, ਫਿਰ {load} \'ਤੇ ਕਲਿੱਕ ਕਰੋ ਅਤੇ ਭਰਨ ਲਈ ਦਰਸ਼ਕ ਚੁਣੋ।',
'Mailchimp_Guide_3' => '{doubleOptIn} ਚਾਲੂ ਰੱਖੋ ਜਦੋਂ ਤੱਕ ਤੁਹਾਡੇ ਗਾਹਕ ਪਹਿਲਾਂ ਹੀ ਮਾਰਕੀਟਿੰਗ ਈਮੇਲਾਂ ਲਈ ਸਹਿਮਤੀ ਨਹੀਂ ਦੇ ਚੁੱਕੇ।',
'Mailchimp_Double_Optin_Term' => 'ਡਬਲ ਔਪਟ-ਇਨ',
'Mailchimp_Guide_4' => 'ਸ਼ੁਰੂਆਤੀ ਭਰਾਈ ਲਈ {push} ਚਲਾਓ; {autoSync} ਚਾਲੂ ਕਰੋ ਤਾਂ ਜੋ ਨਵੇਂ ਗਾਹਕ ਆਪਣੇ ਆਪ ਜੁੜ ਜਾਣ।',
'Mailchimp_Auto_Sync_Term' => 'ਆਟੋ-ਸਿੰਕ',
'Mailchimp_Consent_Title' => 'ਸਹਿਮਤੀ ਮਹੱਤਵਪੂਰਨ ਹੈ',
