'GSheets_Guide_1' => '{link} \'ਤੇ ਇੱਕ ਪ੍ਰੋਜੈਕਟ ਬਣਾਓ ਅਤੇ {api} ਚਾਲੂ ਕਰੋ ({menu})।',
'GSheets_Guide_2' => '{consent} (External) ਕੌਂਫਿਗਰ ਕਰੋ। ਜਦੋਂ ਤੱਕ ਇਹ "Testing" ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ, ਆਪਣਾ Google ਖਾਤਾ ਟੈਸਟ ਯੂਜ਼ਰ ਵਜੋਂ ਸ਼ਾਮਲ ਕਰੋ — ਧਿਆਨ ਦਿਓ ਕਿ ਟੈਸਟਿੰਗ-ਮੋਡ ਰਿਫ੍ਰੈਸ਼ ਟੋਕਨ 7 ਦਿਨਾਂ ਬਾਅਦ ਖਤਮ ਹੋ ਜਾਂਦੇ ਹਨ, ਇਸ ਲਈ ਸਥਾਈ ਕਨੈਕਸ਼ਨ ਲਈ ਐਪ ਨੂੰ {publish} ਕਰੋ।',
