'Shopify_Create_Missing_Customers' => 'ਜਿਹੜੇ Shopify ਗਾਹਕ ਕਿਸੇ ਈਮੇਲ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ ਉਹਨਾਂ ਲਈ ERP ਗਾਹਕ ਬਣਾਓ',
'Shopify_Unknown_Customer_Hint' => 'ਇਹ ਬੰਦ ਹੋਣ \'ਤੇ, ਅਣਜਾਣ ਗਾਹਕ ਦਾ ਆਰਡਰ ਅੰਦਾਜ਼ਾ ਲਗਾਉਣ ਦੀ ਬਜਾਏ ਛੱਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।',
'Shopify_Entities_Lead' => 'ਸਿਰਫ਼ ਇੱਥੇ ਚਾਲੂ ਕੀਤੀਆਂ ਇਕਾਈਆਂ ਹੀ ਸਿੰਕ ਹੋ ਸਕਦੀਆਂ ਹਨ — ਜਿਸ ਦੁਕਾਨ ਤੋਂ ਤੁਸੀਂ ਸਿਰਫ਼ ਆਰਡਰ ਪੁੱਲ ਕਰਦੇ ਹੋ, ਉਸਦਾ ਕੈਟਾਲਾਗ ਕਿਸੇ ਭਟਕੇ ਉਤਪਾਦ ਪੁਸ਼ ਨਾਲ ਦੁਬਾਰਾ ਨਹੀਂ ਲਿਖਿਆ ਜਾਣਾ ਚਾਹੀਦਾ।',
'Shopify_Auto_Schedule' => 'ਸ਼ੈਡਿਊਲ \'ਤੇ ਆਪਣੇ ਆਪ ਸਿੰਕ ਕਰੋ',
'Shopify_Auto_Schedule_Hint' => 'ਸਰਵਰ \'ਤੇ {cmd} ਚਲਾਉਣ ਵਾਲੀ cron ਐਂਟਰੀ ਲੋੜੀਂਦੀ ਹੈ (ਹਰ 5 ਮਿੰਟ ਸਭ ਤੋਂ ਬਾਰੀਕ ਹੈ ਜੋ ਹੇਠਾਂ ਦਿੱਤੇ ਅੰਤਰਾਲ ਵਰਤ ਸਕਦੇ ਹਨ)। ਸਿੰਕ ਹਮੇਸ਼ਾ ਹੱਥੀਂ ਸ਼ੁਰੂ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ।',
'Shopify_Push_Stock_On_Change' => 'ਸਟਾਕ ਬਦਲਦੇ ਹੀ ਪੁਸ਼ ਕਰੋ',
'Shopify_Push_Stock_Hint' => 'ਵਿਕਰੀ, ਵਾਪਸੀ ਜਾਂ ਐਡਜਸਟਮੈਂਟ ਸੇਵ ਹੁੰਦੇ ਹੀ ਸਿਰਫ਼ ਉਹਨਾਂ ਉਤਪਾਦਾਂ ਲਈ ਸਟਾਕ ਪੁਸ਼ ਭੇਜਦਾ ਹੈ, ਤਾਂ ਜੋ ਦੁਕਾਨ ਅਗਲੇ ਸ਼ੈਡਿਊਲ ਕੀਤੇ ਰਨ ਦੀ ਬਜਾਏ ਸਕਿੰਟਾਂ ਵਿੱਚ ਸਹੀ ਹੋ ਜਾਵੇ। ਹੋਰ ਕੁਝ ਇੰਸਟਾਲ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ — ਪੁਸ਼ ਵਿਕਰੀ ਦਾ ਜਵਾਬ ਦੇਣ ਤੋਂ ਬਾਅਦ ਚੱਲਦਾ ਹੈ, ਇਸ ਲਈ ਕਾਊਂਟਰ ਕਦੇ Shopify ਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਦਾ।',
'Shopify_Switch_Inventory_First' => 'ਪਹਿਲਾਂ {tab} ਹੇਠਾਂ Inventory ਚਾਲੂ ਕਰੋ।',
'Shopify_Leave_Off_Lag' => 'ਇਸਨੂੰ ਬੰਦ ਛੱਡੋ ਤਾਂ POS ਵਿਕਰੀ Shopify ਤੱਕ ਸਿਰਫ਼ ਅਗਲੇ Inventory ਪੁਸ਼ \'ਤੇ ਪਹੁੰਚਦੀ ਹੈ — {n} ਮਿੰਟ ਤੱਕ ਬਾਅਦ।',
'Shopify_Default_Interval' => 'ਡਿਫਾਲਟ ਅੰਤਰਾਲ (ਮਿੰਟ)',
'Shopify_Default_Interval_Hint' => 'ਹਰ ਉਸ ਸਟੈਪ ਦੁਆਰਾ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ ਜੋ ਆਪਣਾ ਸੈੱਟ ਨਹੀਂ ਕਰਦਾ।',
'Shopify_What_Runs_Auto' => 'ਕੀ ਆਪਣੇ ਆਪ ਚੱਲਦਾ ਹੈ',
'Shopify_Step_Hint' => 'ਹਰ ਸਟੈਪ ਇੱਕ ਦਿਸ਼ਾ ਵਿੱਚ ਇੱਕ ਇਕਾਈ ਹੈ। ਆਰਡਰ ਹਮੇਸ਼ਾ ਸਿਰਫ਼ Shopify {from} ਆਉਂਦੇ ਹਨ।',
