'Shopify_Add_Step' => 'ਸਟੈਪ ਸ਼ਾਮਲ ਕਰੋ',
'Shopify_Using_Default_Plan' => 'ਡਿਫਾਲਟ ਯੋਜਨਾ ਵਰਤੀ ਜਾ ਰਹੀ ਹੈ',
'Shopify_Default_Plan_Desc' => 'ਹਰ {n} ਮਿੰਟਾਂ ਵਿੱਚ ਆਰਡਰ ਅੰਦਰ ਪੁੱਲ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਸਟਾਕ ਬਾਹਰ ਪੁਸ਼ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਆਪਣੀ ਚੋਣ ਕਰਨ ਲਈ ਸਟੈਪ ਸ਼ਾਮਲ ਕਰੋ — ਸੂਚੀ ਦੁਬਾਰਾ ਖਾਲੀ ਕਰਨ ਨਾਲ ਇਹ ਡਿਫਾਲਟ ਬਹਾਲ ਹੋ ਜਾਂਦਾ ਹੈ।',
