'Shopify_Every_N_Min' => 'ਹਰ {n} ਮਿੰਟ',
'Shopify_Never_Lower' => 'ਕਦੇ ਨਹੀਂ',
'Shopify_Manual' => 'ਮੈਨੁਅਲ',
'Shopify_Due_Now' => 'ਹੁਣ ਬਕਾਇਆ',
'Shopify_Auto_Off_Note' => 'ਬੰਦ — ਇਹ ਸਟੈਪ ਸਿਰਫ਼ ਉਦੋਂ ਚੱਲਦੇ ਹਨ ਜਦੋਂ ਕੋਈ Sync ਦਬਾਉਂਦਾ ਹੈ।',
'Shopify_Auto_On_Note' => '{cmd} ਚਲਾਉਣ ਵਾਲੀ cron ਐਂਟਰੀ ਦੁਆਰਾ ਚਲਾਇਆ ਜਾਂਦਾ ਹੈ — ਇਸ ਤੋਂ ਬਿਨਾਂ, ਇੱਥੇ ਕੁਝ ਵੀ ਆਪਣੇ ਆਪ ਨਹੀਂ ਚੱਲਦਾ। ਮੈਨੁਅਲ ਸਿੰਕ ਵੀ ਇੱਕ ਰਨ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ: ਇਹ ਅਗਲੇ ਨੂੰ ਸਟੈਪ ਦੇ ਅੰਤਰਾਲ ਜਿੰਨਾ ਅੱਗੇ ਕਰ ਦਿੰਦਾ ਹੈ।',
'Shopify_Stock_Lag_Title' => 'ਸਟਾਕ Shopify ਤੱਕ ਸਿਰਫ਼ ਉਦੋਂ ਪਹੁੰਚਦਾ ਹੈ ਜਦੋਂ Inventory ਪੁਸ਼ ਸਟੈਪ ਚੱਲਦਾ ਹੈ',
'Shopify_Stock_Lag_Desc' => 'ਕਾਊਂਟਰ \'ਤੇ ਹੋਈ ਵਿਕਰੀ ਉਦੋਂ ਤੱਕ ਦੁਕਾਨ ਨੂੰ ਦਿਖਾਈ ਨਹੀਂ ਦਿੰਦੀ — {n} ਮਿੰਟ ਤੱਕ, ਇਸ ਲਈ ਆਖਰੀ ਯੂਨਿਟ ਔਨਲਾਈਨ ਦੋ ਵਾਰ ਵਿਕ ਸਕਦੀ ਹੈ। {setting} ਚਾਲੂ ਕਰੋ ਅਤੇ ਹਰ ਵਿਕਰੀ, ਵਾਪਸੀ ਅਤੇ ਐਡਜਸਟਮੈਂਟ ਇਸਦੀ ਬਜਾਏ ਸਕਿੰਟਾਂ ਵਿੱਚ ਭੇਜੀ ਜਾਂਦੀ ਹੈ।',
'Shopify_Turn_It_On' => 'ਇਸਨੂੰ ਚਾਲੂ ਕਰੋ',
'Shopify_Stock_Also_Pushed' => 'ਕਿਸੇ ਵੀ ਵਿਕਰੀ, ਵਾਪਸੀ ਜਾਂ ਐਡਜਸਟਮੈਂਟ ਦੇ ਸਕਿੰਟਾਂ ਵਿੱਚ ਸਟਾਕ ਵੀ ਪੁਸ਼ ਹੁੰਦਾ ਹੈ, ਉੱਪਰਲੇ ਸਟੈਪ ਦੀ ਉਡੀਕ ਕੀਤੇ ਬਿਨਾਂ।',
'Shopify_Sync_History' => 'ਸਿੰਕ ਇਤਿਹਾਸ',
'Shopify_Nothing_Run_Store' => 'ਇਸ ਸਟੋਰ ਲਈ ਕੁਝ ਨਹੀਂ ਚੱਲਿਆ',
'Shopify_Hook_Msg_Client' => 'ਹੇਠਾਂ “Register webhooks” \'ਤੇ ਕਲਿੱਕ ਕਰੋ — Shopify ਵਿੱਚ ਕੁਝ ਵੀ ਦਰਜ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।',
'Shopify_Hook_Msg_Token' => 'ਹੇਠਾਂ “Register webhooks” \'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਅਤੇ ਐਪ ਦੀ API secret key ਨੂੰ ਸਟੋਰ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਾਈਨਿੰਗ ਸੀਕ੍ਰੇਟ ਵਜੋਂ ਪੇਸਟ ਕਰੋ।',
'Shopify_Hook_Note_Register' => 'ਰਜਿਸਟਰ ਕਰਨ ਨਾਲ Shopify ਵਿੱਚ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਬਣ ਜਾਂਦੀਆਂ ਹਨ ਅਤੇ ਆਪਣੇ ਆਪ ਇਸ ਪਤੇ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦੀਆਂ ਹਨ। ਇਸਨੂੰ Shopify → Settings → Notifications → Webhooks ਹੇਠਾਂ ਹੱਥੀਂ ਸ਼ਾਮਲ ਨਾ ਕਰੋ: ਉਹ ਵੱਖਰੇ ਸੀਕ੍ਰੇਟ ਨਾਲ ਸਾਈਨ ਹੁੰਦੇ ਹਨ ਅਤੇ ਹਰ ਡਿਲੀਵਰੀ ਰੱਦ ਹੋ ਜਾਵੇਗੀ।',
'Shopify_Hook_Verified_Client' => 'ਡਿਲੀਵਰੀਆਂ ਐਪ ਦੇ client secret ਨਾਲ ਪ੍ਰਮਾਣਿਤ ਹੁੰਦੀਆਂ ਹਨ, ਜੋ ਪਹਿਲਾਂ ਹੀ ਸਟੋਰ ਹੈ।',
'Shopify_Hook_Signature_Required' => 'ਵੈਧ ਸਿਗਨੇਚਰ ਤੋਂ ਬਿਨਾਂ ਡਿਲੀਵਰੀਆਂ ਰੱਦ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ, ਇਸ ਲਈ ਵੈੱਬਹੁੱਕਾਂ ਦੇ ਕੁਝ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਸੀਕ੍ਰੇਟ ਸੈੱਟ ਹੋਣਾ ਲਾਜ਼ਮੀ ਹੈ।',
'Shopify_Hook_Retries' => 'Shopify 2xx ਮਿਲਣ ਤੱਕ ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰਦਾ ਹੈ, ਅਤੇ ਹਰ ਡਿਲੀਵਰੀ ਇੱਕ ਵਾਰ ਦਰਜ ਹੁੰਦੀ ਹੈ — ਦੁਹਰਾਇਆ ਇਵੈਂਟ ਕੁਝ ਨਹੀਂ ਕਰਦਾ, ਡੁਪਲੀਕੇਟ ਆਰਡਰ ਨਹੀਂ ਬਣਦਾ।',
'Shopify_No_Signing_Secret' => 'ਕੋਈ ਸਾਈਨਿੰਗ ਸੀਕ੍ਰੇਟ ਸਟੋਰ ਨਹੀਂ',
'Shopify_No_Signing_Secret_Desc' => 'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਇਸ ਤੋਂ ਬਿਨਾਂ ਵੀ ਬਣ ਸਕਦੀਆਂ ਹਨ, ਪਰ ਜਦੋਂ ਤੱਕ ਐਪ ਦੀ API secret key ਇਸ ਸਟੋਰ \'ਤੇ ਸੇਵ ਨਹੀਂ ਹੁੰਦੀ, ਹਰ ਡਿਲੀਵਰੀ ਰੱਦ ਹੋਵੇਗੀ (Dev Dashboard ਐਪ ਦਾ client secret ਪਹਿਲਾਂ ਹੀ ਇਹ ਕੰਮ ਕਰਦਾ ਹੈ)।',
'Shopify_Register_In_Shopify' => 'Shopify ਵਿੱਚ ਰਜਿਸਟਰ ਕਰੋ',
