'Shopify_Already_Subscribed' => 'ਇਸ ਸਟੋਰ ਨੂੰ ਲੋੜੀਂਦੀ ਹਰ ਚੀਜ਼ ਲਈ ਪਹਿਲਾਂ ਹੀ ਸਬਸਕ੍ਰਾਈਬ ਹੈ',
'Shopify_Could_Not_Register' => 'ਵੈੱਬਹੁੱਕ ਰਜਿਸਟਰ ਨਹੀਂ ਹੋ ਸਕੇ',
'Shopify_Sub_Removed' => 'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਹਟਾਈ ਗਈ',
'Shopify_Could_Not_Remove_Sub' => 'ਉਹ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਹਟਾਈ ਨਹੀਂ ਜਾ ਸਕੀ',
'Shopify_Could_Not_Load_Store' => 'ਇਹ ਸਟੋਰ ਲੋਡ ਨਹੀਂ ਹੋ ਸਕਿਆ',
'Shopify_G_Lead_Store' => 'ਇਸ ਦੁਕਾਨ ਨੂੰ ਤਾਲਮੇਲ ਵਿੱਚ ਰਹਿਣ ਲਈ ਕੀ ਚਾਹੀਦਾ ਹੈ। ਇੱਥੇ ਸਭ ਕੁਝ ਇਸ ਸਟੋਰ ਲਈ ਖਾਸ ਹੈ — ਪਾਥ ਅਤੇ ids ਅਸਲੀ ਹਨ, ਇਸ ਲਈ ਕਮਾਂਡਾਂ ਸਿੱਧੀਆਂ ਸਰਵਰ \'ਤੇ ਕਾਪੀ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ।',
'Shopify_G_Lead_Generic' => 'ਇੱਕ Shopify ਦੁਕਾਨ ERP ਨਾਲ ਤਾਲਮੇਲ ਕਿਵੇਂ ਰੱਖਦੀ ਹੈ। ਉਸਦੀ ਆਪਣੀ ਸਥਿਤੀ ਦੇਖਣ ਲਈ ਉੱਪਰ ਇੱਕ ਸਟੋਰ ਚੁਣੋ, ਜਾਂ ਜਿਵੇਂ ਹੈ ਪੜ੍ਹੋ — cron ਲਾਈਨ ਅਤੇ ਵੈੱਬਹੁੱਕ URL ਇੱਕੋ ਜਿਹੇ ਹਨ ਭਾਵੇਂ ਤੁਸੀਂ ਕੋਈ ਵੀ ਸਟੋਰ ਕਨੈਕਟ ਕਰੋ।',
'Shopify_G_Ways_Note' => 'ਜ਼ਿਆਦਾਤਰ ਦੁਕਾਨਾਂ ਦੋਵੇਂ ਚਲਾਉਂਦੀਆਂ ਹਨ: ਪਹਿਲਾ ਦੁਕਾਨ ਨੂੰ ਮਿੰਟ-ਦਰ-ਮਿੰਟ ਤਾਜ਼ਾ ਰੱਖਦਾ ਹੈ, ਦੂਜਾ ਉਹ ਸਭ ਫੜਦਾ ਹੈ ਜੋ ਪਹਿਲੇ ਤੋਂ ਛੁੱਟ ਗਿਆ — ਕਦੇ ਨਾ ਪਹੁੰਚਿਆ ਵੈੱਬਹੁੱਕ, Shopify ਐਡਮਿਨ ਵਿੱਚ ਸਿੱਧਾ ਕੀਤਾ ਸੋਧ, ਉਹ ਰਾਤ ਜਦੋਂ ਸਾਈਟ ਬੰਦ ਸੀ।',
'Shopify_G_Both_Need' => 'ਦੋਵਾਂ ਦਿਸ਼ਾਵਾਂ ਲਈ ਪਹਿਲਾਂ ਇਹ ਚਾਹੀਦਾ ਹੈ',
'Shopify_G_Credentials' => 'Shopify ਕ੍ਰੈਡੈਂਸ਼ੀਅਲ',
'Shopify_G_Cred_Intro' => 'ਜਨਵਰੀ 2026 ਤੋਂ Shopify ਐਡਮਿਨ ਦੇ ਅੰਦਰ ਕਸਟਮ ਐਪਾਂ ਨਹੀਂ ਬਣਾਉਂਦਾ, ਇਸ ਲਈ ਦੋ ਤਰ੍ਹਾਂ ਦੇ ਕਨੈਕਸ਼ਨ ਹਨ:',
'Shopify_G_Cred_DevDash' => '{app} (ਹੁਣ ਕਨੈਕਟ ਕੀਤੀ ਕੋਈ ਵੀ ਦੁਕਾਨ) — {path}। ਇਹ ਸਟੋਰ ਜੋ ਸਿੰਕ ਕਰਦਾ ਹੈ ਉਸ ਲਈ Admin API ਸਕੋਪ ਦਿਓ, ਐਪ ਨੂੰ ਦੁਕਾਨ \'ਤੇ ਇੰਸਟਾਲ ਕਰੋ, ਫਿਰ ਐਪ ਦੇ Settings ਪੰਨੇ ਤੋਂ {clientId} ਅਤੇ {clientSecret} ਨੂੰ {where} ਵਿੱਚ ਕਾਪੀ ਕਰੋ। ERP ਉਹਨਾਂ ਦੇ ਬਦਲੇ ਆਪ ਐਕਸੈਸ ਟੋਕਨ ਲੈਂਦਾ ਹੈ ਅਤੇ ਹਰ 24 ਘੰਟਿਆਂ ਵਿੱਚ ਮਿਆਦ ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਇਸਨੂੰ ਨਵਿਆਉਂਦਾ ਹੈ। client secret ਵੈੱਬਹੁੱਕਾਂ \'ਤੇ ਵੀ ਸਾਈਨ ਕਰਦਾ ਹੈ, ਇਸ ਲਈ ਹੋਰ ਕੁਝ ਨਹੀਂ ਚਾਹੀਦਾ। ਐਪ ਅਤੇ ਦੁਕਾਨ ਇੱਕੋ Shopify ਸੰਸਥਾ ਵਿੱਚ ਹੋਣੀਆਂ ਲਾਜ਼ਮੀ ਹਨ।',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard ਐਪ',
'Shopify_G_Cred_Legacy' => '{app} (2026 ਤੋਂ ਪਹਿਲਾਂ ਐਡਮਿਨ ਵਿੱਚ ਬਣੀ) — ਆਪਣੇ {token} ({prefix}) ਅਤੇ ਵੈੱਬਹੁੱਕ ਸਾਈਨਿੰਗ ਸੀਕ੍ਰੇਟ ਵਜੋਂ ਆਪਣੀ {secret} ਨਾਲ ਬਿਨਾਂ ਬਦਲਾਅ ਕੰਮ ਕਰਦੀ ਰਹਿੰਦੀ ਹੈ। ਇਹ ਟੋਕਨ ਵਾਲਾ ਮੁੱਲ ਨਹੀਂ ਹੈ, ਅਤੇ ਇਹਨਾਂ ਨੂੰ ਉਲਟਾ ਲਗਾਉਣਾ ਵੈੱਬਹੁੱਕ ਰੱਦ ਹੋਣ ਦਾ ਆਮ ਕਾਰਨ ਹੈ।',
'Shopify_G_Legacy_App' => 'ਪੁਰਾਣੀ ਕਸਟਮ ਐਪ',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'ਸਟੋਰ ਹੈ',
'Shopify_G_Missing_Refused' => 'ਗੁੰਮ — ਡਿਲੀਵਰੀਆਂ ਰੱਦ ਹੋਣਗੀਆਂ',
'Shopify_G_Where_Data_Desc' => '{path} ERP ਗੋਦਾਮ ਜਿਸਦਾ ਸਟਾਕ ਇਹ ਦੁਕਾਨ ਵੇਚਦੀ ਹੈ, ਅਤੇ Shopify ਟਿਕਾਣਾ ਜਿੱਥੇ ਉਹ ਸਟਾਕ ਲਿਖਿਆ ਜਾਂਦਾ ਹੈ। ਇਨਵੈਂਟਰੀ ਸਿੰਕ ਅਤੇ ਆਰਡਰ ਇੰਪੋਰਟ ਦੋਵੇਂ ਇਹਨਾਂ ਤੋਂ ਬਿਨਾਂ ਨਹੀਂ ਚੱਲਦੇ।',
'Shopify_G_Currently' => 'ਮੌਜੂਦਾ: ਗੋਦਾਮ {warehouse}, ਟਿਕਾਣਾ {location}',
'Shopify_G_Not_Set_Lower' => 'ਸੈੱਟ ਨਹੀਂ',
'Shopify_G_Ready' => 'ਤਿਆਰ',
'Shopify_G_Incomplete' => 'ਅਧੂਰਾ',
'Shopify_G_Manual_Syncs' => 'ਹੱਥੀਂ ਸ਼ੁਰੂ ਕੀਤੇ ਸਿੰਕ',
'Shopify_G_Manual_Desc' => '{centre} ਤੋਂ ਸ਼ੁਰੂ ਕੀਤਾ ਸਿੰਕ ਤੁਰੰਤ ਜਵਾਬ ਦਿੰਦਾ ਹੈ ਅਤੇ ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਛੋਟੇ ਹਿੱਸਿਆਂ ਵਿੱਚ ਚੱਲਦਾ ਹੈ, ਹਰ ਹਿੱਸਾ ਉੱਥੋਂ ਜਾਰੀ ਰਹਿੰਦਾ ਹੈ ਜਿੱਥੇ ਪਿਛਲਾ ਰੁਕਿਆ ਸੀ। ਲੰਬੀਆਂ ਵੈੱਬ ਬੇਨਤੀਆਂ ਖਤਮ ਕਰਨ ਵਾਲੀ ਹੋਸਟਿੰਗ (LiteSpeed, nginx, load balancer) ਕਦੇ ਵੀ ਵੱਡੇ ਕੈਟਾਲਾਗ ਨੂੰ ਅੱਧ ਵਿਚਾਲੇ ਨਹੀਂ ਕੱਟਦੀ, ਅਤੇ ਪੰਨਾ ਬੰਦ ਕਰਨ ਨਾਲ ਇਹ ਨਹੀਂ ਰੁਕਦਾ। ਇਸਦਾ ਵਰਕਰ ਇੱਕ ਹੋਰ cron ਲਾਈਨ ਹੈ:',
'Shopify_G_Cron_Copied' => 'Cron ਲਾਈਨ ਕਾਪੀ ਕੀਤੀ',
'Shopify_G_Manual_Note' => 'ਇਸ ਤੋਂ ਬਿਨਾਂ ਵੀ ਸਿੰਕ ਪੂਰਾ ਹੁੰਦਾ ਹੈ, ਪਰ ਸਿਰਫ਼ ਉਦੋਂ ਤੱਕ ਜਦੋਂ ਤੱਕ Sync Centre ਪੰਨਾ ਖੁੱਲ੍ਹਾ ਰਹਿੰਦਾ ਹੈ: ਜਦੋਂ ਕੁਝ ਸਕਿੰਟਾਂ ਵਿੱਚ ਕੋਈ ਵਰਕਰ ਰਨ ਨਹੀਂ ਚੁੱਕਦਾ, ਪੰਨਾ ਖੁਦ ਇਸਨੂੰ ਜਾਰੀ ਰੱਖਦਾ ਹੈ, ਇੱਕ ਵਾਰ ਵਿੱਚ ਇੱਕ ਛੋਟੀ ਬੇਨਤੀ। Windows \'ਤੇ ਹਰ ਮਿੰਟ Task Scheduler ਵਰਤੋ: ਪ੍ਰੋਗਰਾਮ {program}, ਆਰਗੂਮੈਂਟ {args}, {dir} ਵਿੱਚ ਸ਼ੁਰੂ।',
'Shopify_G_Then_Pick' => 'ਫਿਰ ਚੁਣੋ ਕਿ ਇਹ ਤਾਲਮੇਲ ਕਿਵੇਂ ਰੱਖੇ',
'Shopify_G_Right_Away' => 'ਤੁਰੰਤ',
'Shopify_G_Stock_Live' => 'ਸਟਾਕ ਲਾਈਵ',
'Shopify_G_Stock_Not_Live' => 'ਸਟਾਕ ਲਾਈਵ ਨਹੀਂ',
'Shopify_G_Realtime_Lead' => 'ਹਰ ਬਦਲਾਅ ਹੁੰਦੇ ਹੀ, ਸਕਿੰਟਾਂ ਵਿੱਚ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ। ਦੋ ਹਿੱਸੇ, ਅਤੇ ਉਹਨਾਂ ਦੇ ਵੱਖਰੇ ਸਵਿੱਚ ਹਨ: {webhooks} ਦੁਕਾਨ ਦੇ ਆਪਣੇ ਇਵੈਂਟ ਅੰਦਰ ਲਿਆਉਂਦੇ ਹਨ, ਅਤੇ {push} ਸਟਾਕ ਬਾਹਰ ਭੇਜਦਾ ਹੈ।',
'Shopify_G_Webhooks_Lower' => 'ਵੈੱਬਹੁੱਕ',
'Shopify_G_Instant_Push_Lower' => 'ਤੁਰੰਤ ਸਟਾਕ ਪੁਸ਼',
'Shopify_G_Webhooks_In' => 'ਵੈੱਬਹੁੱਕ — ਦੁਕਾਨ → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify ਵਿੱਚ ਕੀਤੇ ਆਰਡਰ, ਆਰਡਰ ਸਥਿਤੀ ਬਦਲਾਅ, ਅਤੇ ਉਤਪਾਦ, ਗਾਹਕ ਅਤੇ ਸਟਾਕ ਸੋਧ। ਸਟੋਰ ਖੋਲ੍ਹੋ ਅਤੇ ਉਸਦੀ {tab} \'ਤੇ {button} ਦਬਾਓ — ਦੋ ਵਾਰ ਦਬਾਉਣਾ ਸੁਰੱਖਿਅਤ ਹੈ। Shopify ਇੱਥੇ ਪੋਸਟ ਕਰਦਾ ਹੈ:',
'Shopify_G_Webhooks_Tab' => 'ਵੈੱਬਹੁੱਕ ਟੈਬ',
'Shopify_G_Webhooks_Note' => 'ਪਤਾ ਇੰਟਰਨੈੱਟ ਤੋਂ HTTPS \'ਤੇ ਪਹੁੰਚਯੋਗ ਹੋਣਾ ਲਾਜ਼ਮੀ ਹੈ — Shopify {localhost} ਜਾਂ {test} ਡੋਮੇਨ \'ਤੇ ਨਹੀਂ ਪਹੁੰਚਾਏਗਾ। ਹਰ ਡਿਲੀਵਰੀ ਇੱਕ ਵਾਰ ਦਰਜ ਹੁੰਦੀ ਹੈ, ਇਸ ਲਈ Shopify ਦੀਆਂ ਮੁੜ-ਕੋਸ਼ਿਸ਼ਾਂ ਡੁਪਲੀਕੇਟ ਆਰਡਰ ਨਹੀਂ ਬਣਾ ਸਕਦੀਆਂ, ਅਤੇ ਅਸਫਲ ਡਿਲੀਵਰੀ ਦੁਬਾਰਾ ਚਲਾਈ ਜਾ ਸਕਦੀ ਹੈ। ਕਦਮ 1 ਵਾਲਾ ਸਾਈਨਿੰਗ ਸੀਕ੍ਰੇਟ ਸਟੋਰ ਹੋਣ ਤੱਕ ਡਿਲੀਵਰੀਆਂ ਰੱਦ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।',
'Shopify_G_Instant_Out' => 'ਤੁਰੰਤ ਸਟਾਕ ਪੁਸ਼ — ERP → ਦੁਕਾਨ',
'Shopify_G_Setting_Missed' => 'ਇਹ ਉਹ ਸੈਟਿੰਗ ਹੈ ਜੋ ਲੋਕ ਭੁੱਲ ਜਾਂਦੇ ਹਨ',
'Shopify_G_Pos_Not_Auto' => 'POS ਵਿਕਰੀ ਆਪਣੇ ਆਪ Shopify ਤੱਕ {not} ਪਹੁੰਚਦੀ। ਬੰਦ ਛੱਡਣ \'ਤੇ, ਦੁਕਾਨ ਨੂੰ ਸਿਰਫ਼ ਅਗਲੇ Inventory ਪੁਸ਼ ਸਟੈਪ \'ਤੇ ਪਤਾ ਲੱਗਦਾ ਹੈ — ਅਤੇ ਉਸ ਸਮੇਂ ਦੌਰਾਨ ਇਹ ਉਹ ਯੂਨਿਟ ਵੇਚ ਸਕਦੀ ਹੈ ਜੋ ਤੁਸੀਂ ਪਹਿਲਾਂ ਹੀ ਕਾਊਂਟਰ \'ਤੇ ਵੇਚ ਚੁੱਕੇ ਹੋ।',
'Shopify_G_Not' => 'ਨਹੀਂ',
'Shopify_G_Tick_Push' => '{where} \'ਤੇ {setting} \'ਤੇ ਟਿੱਕ ਕਰੋ। ਬੱਸ ਇਹੀ ਸੈੱਟਅੱਪ ਹੈ — ਕੋਈ ਵਰਕਰ ਨਹੀਂ, ਕੋਈ cron ਨਹੀਂ। ਫਿਰ ਹਰ ਵਿਕਰੀ, ਵਾਪਸੀ ਅਤੇ ਐਡਜਸਟਮੈਂਟ ਵਿਕਰੀ ਸੇਵ ਹੋਣ ਦੇ ਤੁਰੰਤ ਬਾਅਦ ਸਿਰਫ਼ ਉਹਨਾਂ ਉਤਪਾਦਾਂ ਦਾ ਪੁਸ਼ ਭੇਜਦੀ ਹੈ, ਅਤੇ ਵੀਹ ਲਾਈਨਾਂ ਵਾਲੀ ਵਿਕਰੀ ਦਾ ਇੱਕ ਪੁਸ਼ ਹੁੰਦਾ ਹੈ, ਵੀਹ ਨਹੀਂ। ਕਾਊਂਟਰ ਕਦੇ ਇਸਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਦਾ।',
'Shopify_G_This_Store' => 'ਇਹ ਸਟੋਰ:',
'Shopify_G_Push_On' => 'ਚਾਲੂ — ਬਦਲਣ \'ਤੇ ਸਟਾਕ ਪੁਸ਼ ਹੁੰਦਾ ਹੈ',
'Shopify_G_Push_Off' => 'ਬੰਦ — ਸਟਾਕ ਸਿਰਫ਼ ਸ਼ਡਿਊਲ \'ਤੇ',
'Shopify_G_Push_Note' => 'ਸਿਰਫ਼ ਉਹ ਉਤਪਾਦ ਜਿਨ੍ਹਾਂ ਦੀ ਪਹਿਲਾਂ ਹੀ Shopify ਮੈਪਿੰਗ ਹੈ, ਅਤੇ ਸਿਰਫ਼ ਇਸ ਸਟੋਰ ਦੇ ਗੋਦਾਮ ਦੀਆਂ ਹਿਲਜੁਲਾਂ ਪੁਸ਼ ਹੁੰਦੀਆਂ ਹਨ। ਥੋਕ ਕਾਰਵਾਈਆਂ — ਉਤਪਾਦ ਮਿਟਾਉਣਾ, ਗੋਦਾਮ ਰੀਸੈੱਟ ਕਰਨਾ — ਬਿਨਾਂ ਇਵੈਂਟ ਚਲਾਏ ਸਟਾਕ ਲਿਖਦੀਆਂ ਹਨ, ਜੋ ਸ਼ੈਡਿਊਲ ਕੀਤਾ ਇਨਵੈਂਟਰੀ ਸਟੈਪ ਵੀ ਰੱਖਣ ਦਾ ਇੱਕ ਕਾਰਨ ਹੈ।',
'Shopify_G_Nothing_Install' => 'ਹੋਰ ਕੁਝ ਇੰਸਟਾਲ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ',
'Shopify_G_No_Worker_Note' => 'ਕਿਸੇ ਵੀ ਹਿੱਸੇ ਨੂੰ ਕਿਊ ਵਰਕਰ ਜਾਂ cron ਐਂਟਰੀ ਦੀ ਲੋੜ ਨਹੀਂ। ਅੰਦਰ ਆਉਣ ਵਾਲਾ ਵੈੱਬਹੁੱਕ Shopify ਦੀ ਬੇਨਤੀ ਵਿੱਚ ਹੀ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ; ਬਾਹਰ ਜਾਣ ਵਾਲਾ ਸਟਾਕ ਪੁਸ਼ ਉਸੇ ਪ੍ਰੋਸੈਸ ਵਿੱਚ ਚੱਲਦਾ ਹੈ ਜਿਸਨੇ ਵਿਕਰੀ ਸੰਭਾਲੀ, ਜਵਾਬ ਵਾਪਸ ਜਾਣ ਦੇ {after} — ਇਸ ਲਈ ਕਾਊਂਟਰ ਕਦੇ Shopify ਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਦਾ, ਅਤੇ ਜਵਾਬ ਦੇਣਾ ਬੰਦ ਕਰਨ ਵਾਲੀ ਦੁਕਾਨ ਨੂੰ ਦਸ ਸਕਿੰਟਾਂ ਬਾਅਦ ਛੱਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਅਗਲੇ ਸ਼ੈਡਿਊਲ ਕੀਤੇ ਇਨਵੈਂਟਰੀ ਪੁਸ਼ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।',
'Shopify_G_After' => 'ਬਾਅਦ',
'Shopify_G_Artisan_Note' => 'ਇੱਕ ਅਪਵਾਦ: artisan ਕਮਾਂਡ ਦੁਆਰਾ ਕੀਤੇ ਸਟਾਕ ਬਦਲਾਅ ਦੇ ਬਾਅਦ ਕੋਈ ਜਵਾਬ ਨਹੀਂ ਹੁੰਦਾ, ਇਸ ਲਈ ਇਸਦੀ ਬਜਾਏ ਇਹ {queue} \'ਤੇ ਕਿਊ ਹੁੰਦਾ ਹੈ। ਜੇ ਤੁਸੀਂ ਚਾਹੁੰਦੇ ਹੋ ਕਿ ਉਹ ਵੀ ਜਲਦੀ ਜਾਣ, ਤਾਂ ਉਸ ਕਿਊ ਨੂੰ ਖਾਲੀ ਕਰੋ:',
'Shopify_G_On_Schedule' => 'ਸ਼ਡਿਊਲ \'ਤੇ',
'Shopify_G_On_Lower' => 'ਚਾਲੂ',
'Shopify_G_Off_Lower' => 'ਬੰਦ',
'Shopify_G_Scheduled_Lead' => 'ਹਰ ਚੀਜ਼ ਸਮੇਂ-ਸਮੇਂ \'ਤੇ ਦੋਵੇਂ ਪਾਸੇ ਦੁਬਾਰਾ ਜਾਂਚੀ ਜਾਂਦੀ ਹੈ। ਰੀਅਲ ਟਾਈਮ ਨਾਲੋਂ ਹੌਲੀ, ਪਰ ਇਹੀ ਉਹਨਾਂ ਦੁਕਾਨਾਂ \'ਤੇ ਸਟਾਕ ਪੁਸ਼ ਕਰਦਾ ਹੈ ਜੋ ਤੁਰੰਤ ਪੁਸ਼ ਨਹੀਂ ਵਰਤਦੀਆਂ, ਛੁੱਟਿਆ ਵੈੱਬਹੁੱਕ ਫੜਦਾ ਹੈ, ਅਤੇ ਪੂਰਾ ਕੈਟਾਲਾਗ ਭੇਜਣ ਦਾ ਇੱਕੋ-ਇੱਕ ਤਰੀਕਾ ਹੈ।',
'Shopify_G_Cron_Entry' => 'cron ਐਂਟਰੀ',
'Shopify_G_Cron_Entry_Desc' => 'ਇਸ ਤੋਂ ਬਿਨਾਂ ਕੁਝ ਵੀ ਸ਼ੈਡਿਊਲ ਕੀਤਾ ਨਹੀਂ ਚੱਲਦਾ। ਇੱਕ ਲਾਈਨ, ਸਿਰਫ਼ ਇਸ ਮੋਡੀਊਲ ਲਈ — ਇਸਨੂੰ ਉਸ ਨਾਲ ਜੋੜੋ ਜੋ ਵੀ ਤੁਸੀਂ ਸ਼ੈਡਿਊਲ ਕਰਨ ਲਈ ਚੁਣਿਆ ਹੈ:',
'Shopify_G_Cron_Note' => 'ਹਰ ਪੰਜ ਮਿੰਟ ਸਭ ਤੋਂ ਬਾਰੀਕ ਸਮਾਂ ਹੈ ਜੋ ਯੋਜਨਾ ਵਰਤ ਸਕਦੀ ਹੈ, ਕਿਉਂਕਿ ਪੰਜ ਮਿੰਟ ਸਭ ਤੋਂ ਛੋਟਾ ਸਟੈਪ ਅੰਤਰਾਲ ਹੈ। ਮੋਟੀ ਐਂਟਰੀ ਬਸ ਹੇਠਲੀ ਹੱਦ ਬਣ ਜਾਂਦੀ ਹੈ — {example} ਨਾਲ, 5 ਮਿੰਟ \'ਤੇ ਸੈੱਟ ਸਟੈਪ ਹਰ 15 \'ਤੇ ਚੱਲਦਾ ਹੈ। Windows \'ਤੇ Task Scheduler ਵਰਤੋ: ਪ੍ਰੋਗਰਾਮ {program}, ਆਰਗੂਮੈਂਟ {args}, {dir} ਵਿੱਚ ਸ਼ੁਰੂ।',
'Shopify_G_Switch_On_Plan' => 'ਇਸਨੂੰ ਚਾਲੂ ਕਰੋ, ਅਤੇ ਯੋਜਨਾ ਚੁਣੋ',
'Shopify_G_Plan_Desc' => '{where} ਸਵਿੱਚ ਤੈਅ ਕਰਦਾ ਹੈ ਕਿ cron ਕੁਝ ਕਰ ਸਕਦਾ ਹੈ ਜਾਂ ਨਹੀਂ; ਯੋਜਨਾ ਤੈਅ ਕਰਦੀ ਹੈ ਕਿ ਇਹ ਕੀ ਕਰਦਾ ਹੈ। ਇੱਕ {step} ਇੱਕ ਦਿਸ਼ਾ ਵਿੱਚ ਇੱਕ ਇਕਾਈ ਹੈ ਜਿਸਦਾ ਆਪਣਾ ਅੰਤਰਾਲ ਹੁੰਦਾ ਹੈ — {first}, {second}। ਡਿਫਾਲਟ ਅੰਤਰਾਲ ਹਰ ਉਸ ਸਟੈਪ ਦੁਆਰਾ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ ਜੋ ਆਪਣਾ ਬਾਕਸ ਖਾਲੀ ਛੱਡਦਾ ਹੈ।',
'Shopify_G_Step_Lower' => 'ਸਟੈਪ',
'Shopify_G_Plan_Note' => 'ਯੋਜਨਾ ਖਾਲੀ ਛੱਡੋ ਤਾਂ ਸਟੋਰ ਡਿਫਾਲਟ ਅੰਤਰਾਲ \'ਤੇ ਆਰਡਰ ਪੁੱਲ ਕਰਦਾ ਹੈ ਅਤੇ ਸਟਾਕ ਪੁਸ਼ ਕਰਦਾ ਹੈ, ਜੋ ਜ਼ਿਆਦਾਤਰ ਦੁਕਾਨਾਂ ਚਾਹੁੰਦੀਆਂ ਹਨ। ਆਰਡਰ ਸਿਰਫ਼-ਪੁੱਲ ਹਨ: ਗਾਹਕ ਆਰਡਰ Shopify \'ਤੇ ਹੀ ਦਿੰਦਾ ਹੈ।',
'Shopify_G_Schedule_On' => 'ਸ਼ੈਡਿਊਲ ਚਾਲੂ',
'Shopify_G_Schedule_Off' => 'ਸ਼ੈਡਿਊਲ ਬੰਦ — ਸਿਰਫ਼ ਮੈਨੁਅਲ',
'Shopify_G_When_Step_Runs' => 'ਸਟੈਪ ਅਸਲ ਵਿੱਚ ਕਦੋਂ ਚੱਲਦਾ ਹੈ',
'Shopify_G_When_Note' => 'ਸਟੈਪ ਉਦੋਂ ਬਕਾਇਆ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਉਸੇ ਸਟੈਪ ਨੂੰ ਆਖਰੀ ਵਾਰ {started} ਉਸਦੇ ਅੰਤਰਾਲ ਤੋਂ ਵੱਧ ਸਮਾਂ ਹੋ ਗਿਆ ਹੋਵੇ, ਜੋ ਰਨ ਇਤਿਹਾਸ ਤੋਂ ਪੜ੍ਹਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਲਈ ਹੱਥੀਂ ਸ਼ੁਰੂ ਕੀਤਾ ਸਿੰਕ ਅਗਲੇ ਆਟੋਮੈਟਿਕ ਨੂੰ ਅੱਗੇ ਪਾ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਵਾਰ-ਵਾਰ ਅਸਫਲ ਹੋਣ ਵਾਲਾ ਸਟੈਪ ਹਰ ਟਿੱਕ ਦੀ ਬਜਾਏ ਆਪਣੇ ਅੰਤਰਾਲ \'ਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਸਟੋਰ ਦਾ Overview ਹਰ ਸਟੈਪ ਦਾ ਆਖਰੀ ਰਨ, ਅਗਲਾ ਬਕਾਇਆ ਸਮਾਂ, ਅਤੇ ਰੁਕੇ ਹੋਣ \'ਤੇ ਕਾਰਨ ਦਿਖਾਉਂਦਾ ਹੈ। ਸ਼ੈਡਿਊਲ \'ਤੇ ਲਗਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਪਹਿਲਾ ਕੈਟਾਲਾਗ ਪੁਸ਼ ਹੱਥੀਂ ਚਲਾਓ — ਪਹਿਲਾਂ {dryRun} ਨਾਲ।',
'Shopify_G_Started_Lower' => 'ਸ਼ੁਰੂ ਹੋਇਆਂ',
'Shopify_G_Where_Setting' => 'ਹਰ ਸੈਟਿੰਗ ਕਿੱਥੇ ਹੈ',
'Shopify_G_Where_Setting_Note' => 'ਇਹ ਸਾਰੀਆਂ ਮੌਜੂਦਾ ਸਟੋਰ \'ਤੇ ਹਨ: {path}, ਫਿਰ ਪੈਨਸਿਲ (ਜਾਂ ਸਟੋਰ ਦੇ ਆਪਣੇ ਪੰਨੇ \'ਤੇ {edit})।',
'Shopify_G_Product_Images' => 'ਉਤਪਾਦ ਤਸਵੀਰਾਂ',
'Shopify_G_Img_1' => 'ਤਸਵੀਰਾਂ {push} ਦੌਰਾਨ ਉਤਪਾਦ ਨਾਲ ਜਾਂਦੀਆਂ ਹਨ — ਪਹਿਲਾਂ ਮੁੱਖ ਤਸਵੀਰ, ਫਿਰ ਗੈਲਰੀ, ਫਿਰ ਆਪਣੀ ਤਸਵੀਰ ਵਾਲੇ ਹਰ ਵੇਰੀਐਂਟ ਲਈ ਇੱਕ, ਪੰਜਾਹ ਤੱਕ।',
'Shopify_G_Products_Push' => 'ਉਤਪਾਦ ਪੁਸ਼',
'Shopify_G_Img_2' => 'ਵੇਰੀਐਂਟ ਦੀ ਤਸਵੀਰ ਉਤਪਾਦ ਨਾਲ ਅੱਪਲੋਡ ਹੁੰਦੀ ਹੈ ਅਤੇ ਫਿਰ {assigned}, ਜੋ Shopify ਦਾ ਤਰੀਕਾ ਹੈ: ਵੇਰੀਐਂਟ ਉਤਪਾਦ ਦੀਆਂ ਤਸਵੀਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦਾ ਹੈ। ਮੁੱਖ ਤਸਵੀਰ ਦੁਬਾਰਾ ਵਰਤਣ ਵਾਲਾ ਵੇਰੀਐਂਟ ਉਸਨੂੰ ਦੋ ਵਾਰ ਅੱਪਲੋਡ ਨਹੀਂ ਕਰਦਾ।',
'Shopify_G_Assigned' => 'ਉਸ ਵੇਰੀਐਂਟ ਨੂੰ ਸੌਂਪੀ ਜਾਂਦੀ ਹੈ',
'Shopify_G_Img_3' => 'ਫਾਈਲ ਵਜੋਂ ਸਟੋਰ ਕੀਤੀ ਤਸਵੀਰ Shopify \'ਤੇ {uploaded} ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਲਿੰਕ ਨਹੀਂ, ਇਸ ਲਈ ਇਹ ਉਦੋਂ ਵੀ ਕੰਮ ਕਰਦੀ ਹੈ ਜਦੋਂ ਇਹ ਇੰਸਟਾਲੇਸ਼ਨ ਇੰਟਰਨੈੱਟ ਤੋਂ ਪਹੁੰਚਯੋਗ ਨਹੀਂ ਹੁੰਦੀ। ਪੇਸਟ ਕੀਤੇ ਲਿੰਕ ਵਜੋਂ ਜੋੜੀ ਤਸਵੀਰ Shopify ਨੂੰ ਉਸੇ URL ਵਜੋਂ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ, ਜੋ ਜਨਤਕ ਤੌਰ \'ਤੇ ਪਹੁੰਚਯੋਗ ਹੋਣਾ ਲਾਜ਼ਮੀ ਹੈ।',
'Shopify_G_Uploaded' => 'ਅੱਪਲੋਡ',
'Shopify_G_Img_4' => 'ਇਹ ਸਿਰਫ਼ ਉਦੋਂ ਦੁਬਾਰਾ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਜਦੋਂ ਇਹ ਅਸਲ ਵਿੱਚ ਬਦਲਦੀਆਂ ਹਨ — ਸਿਰਫ਼ ਕੀਮਤ ਬਦਲਣ ਵਾਲਾ ਪੁਸ਼ ਦੁਕਾਨ ਦੀਆਂ ਤਸਵੀਰਾਂ ਨੂੰ ਨਹੀਂ ਛੇੜਦਾ, ਕਿਉਂਕਿ ਉਹਨਾਂ ਨੂੰ ਭੇਜਣ ਨਾਲ ਪੂਰਾ ਸੈੱਟ ਬਦਲ ਜਾਂਦਾ ਹੈ।',
'Shopify_G_Img_5' => 'ERP ਵਿੱਚ ਤਸਵੀਰ ਹਟਾਉਣ ਨਾਲ ਉਹ Shopify ਵਿੱਚ {not} ਮਿਟਦੀ। ਉੱਥੇ ਵੀ ਮਿਟਾਓ, ਨਹੀਂ ਤਾਂ ਦੁਕਾਨ ਇਸਨੂੰ ਦਿਖਾਉਂਦੀ ਰਹੇਗੀ।',
'Shopify_G_Commands' => 'ਜਾਣਨਯੋਗ ਕਮਾਂਡਾਂ',
'Shopify_G_Command_Copied' => 'ਕਮਾਂਡ ਕਾਪੀ ਕੀਤੀ',
'Shopify_G_Foot' => 'ਹਰ ਸਿੰਕ {logs} ਵਿੱਚ ਲਿਖਦਾ ਹੈ, ਅਤੇ ਹਰ ਸਟੋਰ ਦਾ Overview ਦਿਖਾਉਂਦਾ ਹੈ ਕਿ ਹਰ ਸਟੈਪ ਆਖਰੀ ਵਾਰ ਕਦੋਂ ਚੱਲਿਆ, ਅਗਲਾ ਕਦੋਂ ਬਕਾਇਆ ਹੈ, ਅਤੇ ਜੇ ਕੁਝ ਰੋਕ ਰਿਹਾ ਹੈ ਤਾਂ ਕੀ। ਜਦੋਂ ਸਿੰਕ ਨੇ ਉਮੀਦ ਮੁਤਾਬਕ ਕੰਮ ਨਾ ਕੀਤਾ ਹੋਵੇ ਤਾਂ ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਇੱਥੇ ਦੇਖੋ।',
