'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash ਅਤੇ SSLCommerz ਸਿਰਫ਼ ਔਨਲਾਈਨ ਸਟੋਰ ਚੈੱਕਆਉਟ ਦੁਆਰਾ ਵਰਤੇ ਜਾਂਦੇ ਹਨ।',
'StoreAdm_PG_Intro_Desc' => 'Stripe ਕੁੰਜੀਆਂ ਗਲੋਬਲ ਤੌਰ \'ਤੇ ਸਾਂਝੀਆਂ ਹਨ (ਐਡਮਿਨ ਅਤੇ ਔਨਲਾਈਨ ਸਟੋਰ ਇੱਕੋ Stripe ਇੰਟੀਗ੍ਰੇਸ਼ਨ ਵਰਤਦੇ ਹਨ)। ਹਰ ਟੈਬ ਔਨਲਾਈਨ-ਸਟੋਰ ਚੈੱਕਆਉਟ ਲਈ ਆਪਣਾ ਤਰੀਕਾ ਚਾਲੂ ਜਾਂ ਬੰਦ ਕਰਦੀ ਹੈ; ਔਫਲਾਈਨ ਭੁਗਤਾਨਾਂ ਵਿੱਚ ਸਿਸਟਮ ਤੋਂ ਬਾਹਰ ਭੁਗਤਾਨ ਕੀਤੇ ਤਰੀਕੇ ਹੁੰਦੇ ਹਨ।',
'StoreAdm_PG_Used_By_Store_Only' => 'ਸਿਰਫ਼ ਔਨਲਾਈਨ ਸਟੋਰ ਚੈੱਕਆਉਟ ਦੁਆਰਾ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ',
'StoreAdm_PG_Gw_Key' => '{gw} ਕੁੰਜੀ',
'StoreAdm_PG_Gw_Secret' => '{gw} ਸੀਕ੍ਰੇਟ',
'StoreAdm_PG_Cards_Off' => 'ਕਾਰਡ ਭੁਗਤਾਨ ਬੰਦ ਹਨ',
'StoreAdm_PG_Cards_Off_Desc' => 'ਤੁਹਾਡੀਆਂ ਕੁੰਜੀਆਂ ਰੱਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ — ਔਨਲਾਈਨ-ਸਟੋਰ ਚੈੱਕਆਉਟ ਬਸ ਕਾਰਡ ਵਿਕਲਪ ਦੇਣਾ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਸਨੂੰ ਦੁਬਾਰਾ ਚਾਲੂ ਨਹੀਂ ਕਰਦੇ।',
'StoreAdm_PG_No_Stripe_Key' => 'ਕੋਈ Stripe ਕੁੰਜੀ ਸਟੋਰ ਨਹੀਂ',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'ਔਨਲਾਈਨ ਸਟੋਰ ਵਿੱਚ ਕਾਰਡ ਭੁਗਤਾਨ ਸਵੀਕਾਰ ਕਰਨਾ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਆਪਣੀ Stripe ਕੁੰਜੀ ਅਤੇ ਸੀਕ੍ਰੇਟ ਦਰਜ ਕਰੋ।',
'StoreAdm_PG_Gw_Client_Id' => '{gw} Client ID',
'StoreAdm_PG_Gw_Client_Secret' => '{gw} Client Secret',
'StoreAdm_PG_Sandbox' => 'Sandbox (ਟੈਸਟ ਮੋਡ)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'ਚਾਲੂ ਹੋਣ \'ਤੇ sandbox ਕ੍ਰੈਡੈਂਸ਼ੀਅਲ ਨਾਲ {sandbox} ਵਰਤਦਾ ਹੈ; {live} \'ਤੇ ਅਸਲ ਖਾਤਿਆਂ ਤੋਂ ਚਾਰਜ ਕਰਨ ਲਈ ਬੰਦ ਕਰੋ।',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => '{gw} Webhook ID (ਵਿਕਲਪਿਕ)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'ਉਹਨਾਂ ਭੁਗਤਾਨਾਂ ਲਈ ਬੈਕਅੱਪ ਜਿਨ੍ਹਾਂ ਦਾ ਬ੍ਰਾਊਜ਼ਰ ਰੀਡਾਇਰੈਕਟ ਕਦੇ ਨਹੀਂ ਪਹੁੰਚਦਾ, ਨਾਲ ਹੀ ਰਿਫੰਡ/ਚਾਰਜਬੈਕ। {site} \'ਤੇ ਹੇਠਾਂ ਦਿੱਤੇ URL ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦਾ ਵੈੱਬਹੁੱਕ ਰਜਿਸਟਰ ਕਰੋ (ਇਵੈਂਟ: {events}) ਅਤੇ ਉਸਦੀ Webhook ID ਇੱਥੇ ਪੇਸਟ ਕਰੋ।',
'StoreAdm_PG_Webhook_Url' => 'ਵੈੱਬਹੁੱਕ URL:',
'StoreAdm_PG_Gw_Disabled' => '{gw} ਬੰਦ ਹੈ',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'ਗਾਹਕਾਂ ਨੂੰ ਔਨਲਾਈਨ-ਸਟੋਰ ਚੈੱਕਆਉਟ \'ਤੇ PayPal ਨਾਲ ਭੁਗਤਾਨ ਕਰਨ ਦੇਣ ਲਈ PayPal ਚਾਲੂ ਕਰੋ ਅਤੇ ਆਪਣੀ REST ਐਪ ਦਾ Client ID ਅਤੇ Secret ({site} ਤੋਂ) ਦਰਜ ਕਰੋ।',
'StoreAdm_PG_Gw_Public_Key' => '{gw} Public Key',
'StoreAdm_PG_Gw_Secret_Key' => '{gw} Secret Key',
'StoreAdm_PG_Paystack_Test_Live' => 'ਟੈਸਟ ਜਾਂ ਲਾਈਵ ਕੁੰਜੀ ਜੋੜੀ ਤੋਂ ਤੈਅ ਹੁੰਦਾ ਹੈ: {test} ਕੁੰਜੀਆਂ ਟੈਸਟ ਮੋਡ ਵਿੱਚ ਚੱਲਦੀਆਂ ਹਨ, {live} ਕੁੰਜੀਆਂ ਅਸਲ ਕਾਰਡਾਂ ਤੋਂ ਚਾਰਜ ਕਰਦੀਆਂ ਹਨ — ਕੋਈ ਵੱਖਰਾ sandbox ਸਵਿੱਚ ਨਹੀਂ।',
'StoreAdm_PG_Paystack_Webhook_Url' => 'ਵੈੱਬਹੁੱਕ URL (ਵਿਕਲਪਿਕ ਬੈਕਅੱਪ — Paystack ਡੈਸ਼ਬੋਰਡ \'ਤੇ Settings → API Keys & Webhooks ਹੇਠਾਂ ਸੈੱਟ ਕਰੋ; ਬੇਨਤੀਆਂ ਤੁਹਾਡੀ secret key ਨਾਲ HMAC-ਪ੍ਰਮਾਣਿਤ ਹੁੰਦੀਆਂ ਹਨ):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'ਔਨਲਾਈਨ-ਸਟੋਰ ਚੈੱਕਆਉਟ \'ਤੇ ਕਾਰਡ, ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਅਤੇ ਮੋਬਾਈਲ ਮਨੀ ਸਵੀਕਾਰ ਕਰਨ ਲਈ Paystack ਚਾਲੂ ਕਰੋ ਅਤੇ ਆਪਣੀਆਂ Public ਅਤੇ Secret ਕੁੰਜੀਆਂ ({site} → Settings → API Keys ਤੋਂ) ਦਰਜ ਕਰੋ।',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (ਵੈੱਬਹੁੱਕ, ਵਿਕਲਪਿਕ)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Flutterwave ਡੈਸ਼ਬੋਰਡ \'ਤੇ Settings → Webhooks ਹੇਠਾਂ ਤੁਹਾਡੇ ਦੁਆਰਾ ਸੈੱਟ ਕੀਤਾ Secret Hash; ਅੰਦਰ ਆਉਣ ਵਾਲੇ ਵੈੱਬਹੁੱਕ ਰੱਦ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਜਦੋਂ ਤੱਕ ਉਹਨਾਂ ਦਾ {header} ਹੈਡਰ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ।',
'StoreAdm_PG_Flutterwave_Info' => 'ਕਲਾਸਿਕ ਕੁੰਜੀਆਂ ਨਾਲ Flutterwave v3 API ਵਰਤਦਾ ਹੈ। ਟੈਸਟ ਜਾਂ ਲਾਈਵ ਕੁੰਜੀ ਜੋੜੀ ਤੋਂ ਤੈਅ ਹੁੰਦਾ ਹੈ ({keys} ਬਨਾਮ ਲਾਈਵ ਕੁੰਜੀਆਂ) — ਕੋਈ ਵੱਖਰਾ sandbox ਸਵਿੱਚ ਨਹੀਂ। ਸਟੋਰ ਦੀ ਮੁਦਰਾ ਤੁਹਾਡੇ Flutterwave ਖਾਤੇ \'ਤੇ ਚਾਲੂ ਹੋਣੀ ਲਾਜ਼ਮੀ ਹੈ।',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'ਵੈੱਬਹੁੱਕ URL (ਵਿਕਲਪਿਕ ਬੈਕਅੱਪ — Flutterwave ਡੈਸ਼ਬੋਰਡ \'ਤੇ ਉੱਪਰ ਦਿੱਤੇ Secret Hash ਨਾਲ ਸੈੱਟ ਕਰੋ):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'ਔਨਲਾਈਨ-ਸਟੋਰ ਚੈੱਕਆਉਟ \'ਤੇ ਕਾਰਡ, ਮੋਬਾਈਲ ਮਨੀ ਅਤੇ ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਸਵੀਕਾਰ ਕਰਨ ਲਈ Flutterwave ਚਾਲੂ ਕਰੋ ਅਤੇ ਆਪਣੀਆਂ v3 Public ਅਤੇ Secret ਕੁੰਜੀਆਂ ({site} → Settings → API ਤੋਂ) ਦਰਜ ਕਰੋ।',
'StoreAdm_PG_Gw_Key_Id' => '{gw} Key ID',
'StoreAdm_PG_Gw_Key_Secret' => '{gw} Key Secret',
'StoreAdm_PG_Webhook_Secret_Opt' => 'ਵੈੱਬਹੁੱਕ ਸੀਕ੍ਰੇਟ (ਵਿਕਲਪਿਕ)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'Razorpay ਡੈਸ਼ਬੋਰਡ \'ਤੇ ਵੈੱਬਹੁੱਕ ਬਣਾਉਂਦੇ ਸਮੇਂ ਤੁਹਾਡੇ ਦੁਆਰਾ ਨਿਰਧਾਰਤ ਸੀਕ੍ਰੇਟ; ਅੰਦਰ ਆਉਣ ਵਾਲੇ ਇਵੈਂਟ ਇਸਦੇ ਵਿਰੁੱਧ HMAC-ਪ੍ਰਮਾਣਿਤ ਹੁੰਦੇ ਹਨ ਅਤੇ ਨਹੀਂ ਤਾਂ ਰੱਦ ਕੀਤੇ ਜਾਂਦੇ ਹਨ।',
'StoreAdm_PG_Razorpay_Info' => 'Razorpay Payment Links ਵਰਤਦਾ ਹੈ (ਕਾਰਡ, UPI, ਨੈੱਟਬੈਂਕਿੰਗ, ਵਾਲੇਟ)। ਟੈਸਟ ਜਾਂ ਲਾਈਵ ਕੁੰਜੀ ਜੋੜੀ ਤੋਂ ਤੈਅ ਹੁੰਦਾ ਹੈ ({keys}) — ਕੋਈ ਵੱਖਰਾ sandbox ਸਵਿੱਚ ਨਹੀਂ।',
'StoreAdm_PG_Razorpay_Webhook_Url' => 'ਵੈੱਬਹੁੱਕ URL (ਵਿਕਲਪਿਕ ਬੈਕਅੱਪ — Settings → Webhooks ਹੇਠਾਂ ਉੱਪਰ ਦਿੱਤੇ ਸੀਕ੍ਰੇਟ ਨਾਲ ਰਜਿਸਟਰ ਕਰੋ; ਇਵੈਂਟ: {events}):',
'StoreAdm_PG_Razorpay_Disabled_Desc' => 'ਔਨਲਾਈਨ-ਸਟੋਰ ਚੈੱਕਆਉਟ \'ਤੇ ਕਾਰਡ, UPI, ਨੈੱਟਬੈਂਕਿੰਗ ਅਤੇ ਵਾਲੇਟ ਸਵੀਕਾਰ ਕਰਨ ਲਈ Razorpay ਚਾਲੂ ਕਰੋ ਅਤੇ ਆਪਣੀ Key ID ਅਤੇ Key Secret ({site} → Settings → API Keys ਤੋਂ) ਦਰਜ ਕਰੋ।',
'StoreAdm_PG_Gw_App_Key' => '{gw} App Key',
'StoreAdm_PG_Gw_App_Secret' => '{gw} App Secret',
'StoreAdm_PG_Gw_Username' => '{gw} ਯੂਜ਼ਰਨੇਮ',
'StoreAdm_PG_Gw_Password' => '{gw} ਪਾਸਵਰਡ',
'StoreAdm_PG_Sandbox_Bkash_Hint' => 'ਚਾਲੂ ਹੋਣ \'ਤੇ ਤੁਹਾਡੇ sandbox ਕ੍ਰੈਡੈਂਸ਼ੀਅਲ ਨਾਲ {sandbox} ਵਰਤਦਾ ਹੈ; {live} \'ਤੇ ਅਸਲ bKash ਖਾਤਿਆਂ ਤੋਂ ਚਾਰਜ ਕਰਨ ਲਈ ਬੰਦ ਕਰੋ।',
'StoreAdm_PG_Bkash_Info' => 'bKash Tokenized Checkout ਵਰਤਦਾ ਹੈ (bKash ਮਰਚੈਂਟ ਪੋਰਟਲ ਤੋਂ ਮਰਚੈਂਟ ਕ੍ਰੈਡੈਂਸ਼ੀਅਲ)। bKash ਸਿਰਫ਼ BDT ਵਿੱਚ ਚਾਰਜ ਕਰਦਾ ਹੈ — ਇਹ ਵਿਕਲਪ ਚੈੱਕਆਉਟ \'ਤੇ ਸਿਰਫ਼ ਉਦੋਂ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਜਦੋਂ ਸਟੋਰ ਦੀ ਸਰਗਰਮ ਮੁਦਰਾ BDT ਹੋਵੇ।',
'StoreAdm_PG_Bkash_Disabled_Desc' => 'ਗਾਹਕਾਂ ਨੂੰ ਔਨਲਾਈਨ-ਸਟੋਰ ਚੈੱਕਆਉਟ \'ਤੇ bKash ਨਾਲ ਭੁਗਤਾਨ ਕਰਨ ਦੇਣ ਲਈ bKash ਚਾਲੂ ਕਰੋ ਅਤੇ ਆਪਣੀ Tokenized Checkout App Key, App Secret, ਯੂਜ਼ਰਨੇਮ ਅਤੇ ਪਾਸਵਰਡ (bKash ਮਰਚੈਂਟ ਪੋਰਟਲ ਤੋਂ) ਦਰਜ ਕਰੋ।',
'StoreAdm_PG_Gw_Store_Id' => '{gw} Store ID',
